    #[test]
    fn native_theme_picker_keeps_builtins_first_and_adds_user_themes_once() {
        let choices = merge_theme_options([
            "My Solarized".to_string(),
            "dracula".to_string(),
            "Work Light".to_string(),
        ]);
        let builtins = aterm_types::scheme::builtin_names();
        assert_eq!(
            &choices[..builtins.len()],
            builtins.as_slice(),
            "the stable built-in registry remains the first picker section"
        );
        assert_eq!(
            &choices[builtins.len()..],
            ["My Solarized", "Work Light"],
            "user themes append in discovery order and cannot duplicate a built-in"
        );

        let picker = ChoicePicker::new(
            prefs::EDIT_THEME,
            ["Nord".to_string()],
            "Nord",
            true,
            true,
            "Default",
            &crate::app_config::ThemeCatalog::default(),
        );
        let nord = picker
            .options
            .iter()
            .find(|option| option.value.as_deref() == Some("Nord"))
            .expect("Nord picker option");
        assert_eq!(
            nord.terminal_theme,
            aterm_types::scheme::builtin("Nord")
                .as_ref()
                .map(PreviewTerminalTheme::from_scheme),
            "picker-open parsing caches the exact live preview palette"
        );

        let work_scheme = aterm_types::scheme::builtin("Dracula").unwrap();
        let custom = crate::app_config::ThemeCatalog::from_schemes([(
            "Work".to_string(),
            work_scheme.clone(),
        )]);
        assert!(settings_theme_options(&custom).ends_with(&["Work".to_string()]));
        let custom_picker = ChoicePicker::new(
            prefs::EDIT_THEME,
            settings_theme_options(&custom),
            "work",
            true,
            true,
            "Default",
            &custom,
        );
        let work = custom_picker
            .options
            .iter()
            .find(|option| option.value.as_deref() == Some("Work"))
            .unwrap();
        assert_eq!(
            work.terminal_theme,
            Some(PreviewTerminalTheme::from_scheme(&work_scheme)),
            "picker and runtime share case-insensitive custom-theme identity without a second file read"
        );
    }

    #[test]
    fn choice_picker_page_resize_preserves_selected_or_intentionally_paged_window() {
        for selected in [6_usize, 7] {
            for target in [3_usize, 2, 1] {
                let values = (0..10).map(|index| format!("Choice {index}"));
                let current = format!("Choice {selected}");
                let picker = ChoicePicker::new(
                    prefs::EDIT_THEME,
                    values,
                    &current,
                    false,
                    true,
                    "Choice 0",
                    &crate::app_config::ThemeCatalog::default(),
                );
                picker.page_size.set(4);
                picker.offset.set(4);
                picker.configure_page_size(target);
                assert!(
                    picker.visible_range().contains(&selected),
                    "4→{target} must keep selected boundary {selected} visible"
                );
                assert_eq!(picker.offset.get(), (selected / target) * target);
            }
        }

        let picker = ChoicePicker::new(
            prefs::EDIT_THEME,
            (0..10).map(|index| format!("Choice {index}")),
            "Choice 7",
            false,
            true,
            "Choice 0",
            &crate::app_config::ThemeCatalog::default(),
        );
        picker.page_size.set(4);
        picker.offset.set(0);
        picker.configure_page_size(3);
        assert_eq!(picker.offset.get(), 0);
        assert!(
            !picker.visible_range().contains(&picker.selected),
            "an intentionally paged-away selection must not pull the user's window"
        );

        picker.page_size.set(1);
        picker.offset.set(7);
        picker.configure_page_size(4);
        assert!(picker.visible_range().contains(&picker.selected));
        assert_eq!(
            picker.offset.get(),
            4,
            "1→4 expansion realigns around selection"
        );
    }

    #[test]
    fn split_theme_preview_follows_os_appearance_not_overridden_background_luminance() {
        let service = VersionedConfigService::new(
            "theme = \"dark:Dracula,light:GitHub Light\"\nbackground = \"#000000\"\n".to_string(),
        )
        .unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        let misleading_dark_host = aterm_render::Theme {
            bg: 0x000000,
            ..aterm_render::Theme::default()
        };
        let light = preview_terminal_theme(&state, misleading_dark_host, false);
        let dark = preview_terminal_theme(&state, misleading_dark_host, true);
        let expected_light = PreviewTerminalTheme::from_scheme(
            &aterm_types::scheme::builtin("GitHub Light").unwrap(),
        );
        let expected_dark =
            PreviewTerminalTheme::from_scheme(&aterm_types::scheme::builtin("Dracula").unwrap());

        assert_eq!(light.fg, expected_light.fg);
        assert_eq!(light.ansi, expected_light.ansi);
        assert_eq!(dark.fg, expected_dark.fg);
        assert_eq!(dark.ansi, expected_dark.ansi);
        assert_eq!(light.bg, 0x000000, "authored slot overrides still win");
        assert_eq!(dark.bg, 0x000000, "authored slot overrides still win");
    }

    #[test]
    fn theme_projection_and_preview_share_catalog_split_and_default_fallback_semantics() {
        let state_with_themes = |source: &str, themes: Arc<crate::app_config::ThemeCatalog>| {
            let config: Config = aterm_toml::from_str(source).unwrap();
            let mut assets = (*crate::app_config::ConfigAssetCatalog::empty()).clone();
            assets.themes = themes;
            SettingsViewState::from_config_and_assets(&config, Arc::new(assets))
        };
        let project = |state: &SettingsViewState| {
            setting_effect_projection(
                state,
                None,
                prefs::EDIT_THEME,
                audited_availability(),
                crate::native_app::ViewMotionCx::default(),
            )
        };
        let host = aterm_render::Theme {
            fg: 0x01_0203,
            bg: 0x04_0506,
            cursor: 0x07_0809,
            selection: 0x0A_0B0C,
        };
        let default = PreviewTerminalTheme::from_scheme(&aterm_types::ColorScheme::default());

        let builtin = state_with_themes(
            "theme = \"Nord\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(
            preview_terminal_theme(&builtin, host, false),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Nord").expect("built-in Nord")
            )
        );
        assert!(!effect_note_contains(&project(&builtin), "unavailable"));

        let missing = state_with_themes(
            "theme = \"Office Missing\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(preview_terminal_theme(&missing, host, false), default);
        assert!(effect_note_contains(&project(&missing), "Default fallback"));

        let split_missing = state_with_themes(
            "theme = \"dark:Dracula,light:Office Missing\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(
            preview_terminal_theme(&split_missing, host, true),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
            )
        );
        assert_eq!(preview_terminal_theme(&split_missing, host, false), default);
        let split_note = project(&split_missing);
        assert!(effect_note_contains(
            &split_note,
            "light \"Office Missing\""
        ));
        assert!(effect_note_contains(&split_note, "Default fallback"));

        let omitted_light = state_with_themes(
            "theme = \"dark:Dracula\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(preview_terminal_theme(&omitted_light, host, false), default);
        assert_eq!(
            preview_terminal_theme(&omitted_light, host, true),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
            )
        );
        assert!(
            project(&omitted_light).notes.is_empty(),
            "an intentionally omitted side is Default, not an unavailable theme"
        );

        let invalid_split = state_with_themes(
            "theme = \"dark:Dracula,night:Nord\"\n",
            crate::app_config::ThemeCatalog::empty(),
        );
        assert_eq!(
            preview_terminal_theme(&invalid_split, host, true),
            PreviewTerminalTheme::from_scheme(
                &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
            )
        );
        assert_eq!(preview_terminal_theme(&invalid_split, host, false), default);
        let invalid_projection = project(&invalid_split);
        assert!(effect_note_contains(
            &invalid_projection,
            "Invalid theme selector"
        ));
        assert!(effect_note_contains(
            &invalid_projection,
            "Dark (Dracula) still applies"
        ));
        assert!(invalid_projection.has_live_effect);

        let work_scheme = aterm_types::scheme::builtin("GitHub Light").unwrap();
        let custom = state_with_themes(
            "theme = \"Work\"\n",
            crate::app_config::ThemeCatalog::from_schemes([(
                "Work".to_string(),
                work_scheme.clone(),
            )]),
        );
        assert_eq!(
            preview_terminal_theme(&custom, host, false),
            PreviewTerminalTheme::from_scheme(&work_scheme)
        );
        assert!(project(&custom).notes.is_empty());
    }

    #[test]
    fn highlighted_uncommitted_trail_pack_is_the_live_preview_candidate() {
        let synthwave_path = trail_pack_asset("synthwave.toml");
        let service = VersionedConfigService::new(trail_pack_config(
            std::slice::from_ref(&synthwave_path),
            "phaser",
        ))
        .unwrap();
        let mut state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        state.navigate(SettingsRoute::CursorMotion);
        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();
        let before =
            renderer_preview_spec(&state, 900, motion, 13.0, theme).expect("committed preview");

        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .expect("trail style field");
        let picker = ChoicePicker::new(
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
                .expect("trail choices"),
            SettingsState::display_value(field),
            state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE),
            field.seed.is_some(),
            &effective_default_for_field(prefs::EDIT_CURSOR_TRAIL_STYLE),
            &state.assets.themes,
        );
        let pack_index = picker
            .options
            .iter()
            .position(|option| option.value.as_deref() == Some("pack:synthwave"))
            .expect("pack option");
        picker
            .offset
            .set((pack_index / ChoicePicker::PAGE_SIZE) * ChoicePicker::PAGE_SIZE);
        state.choice_picker = Some(picker);
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/choice/{}/{pack_index}",
            prefs::EDIT_CURSOR_TRAIL_STYLE
        )));

        let candidate =
            renderer_preview_spec(&state, 900, motion, 13.0, theme).expect("candidate preview");
        assert_eq!(candidate.cursor.trail_style, PreviewTrailStyle::Custom);
        assert_eq!(
            candidate
                .cursor
                .trail_pack
                .as_ref()
                .map(|pack| pack.pack_fp),
            state
                .trail_pack_catalog()
                .get("synthwave")
                .map(|pack| pack.pack_fp)
        );
        assert_eq!(candidate.animation(), PreviewAnimation::Continuous);
        assert!(
            candidate
                .audit_value()
                .contains("Trail Pack interpreter is live")
        );
        assert_ne!(before.paint_fingerprint(), candidate.paint_fingerprint());
        assert_eq!(
            state.raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE).as_deref(),
            Some("phaser"),
            "moving picker focus previews without persisting"
        );
    }

    #[test]
    fn renderer_preview_carries_rainbow_variant_identity_from_config() {
        use crate::settings_preview::PreviewTrailCompanion;
        use aterm_effects::kitty_pet::PetSpecies;

        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();
        for (raw, expected) in [
            // The underline spelling is a GEOMETRY of the kitty family and
            // draws the family's companion. It used to answer FlyingKitty here
            // — not by any rule, but because `style_names_kitty_pet` is a
            // whole-string equality that it happened not to match, so appending
            // one geometry word to `rainbow kitty` swapped the animal.
            (
                "rainbow kitty underline",
                PreviewTrailCompanion::Pet(PetSpecies::Cat),
            ),
            // `… tall` is the sibling spelling, and it draws the sibling's
            // ANIMAL: the word names the geometry the default already draws,
            // so it can no more swap the companion than `underline` can.
            (
                "rainbow kitty tall",
                PreviewTrailCompanion::Pet(PetSpecies::Cat),
            ),
            (
                "rainbow kitty pet",
                PreviewTrailCompanion::Pet(PetSpecies::Cat),
            ),
            (
                "rainbow dog pet",
                PreviewTrailCompanion::Pet(PetSpecies::Dog),
            ),
            ("rainbow kitty flying", PreviewTrailCompanion::FlyingKitty),
        ] {
            let config: Config = aterm_toml::from_str(&format!(
                "cursor_trail = true\ncursor_trail_style = {raw:?}\n"
            ))
            .unwrap();
            let mut state = SettingsViewState::new(&config);
            state.navigate(SettingsRoute::CursorMotion);
            let preview = renderer_preview_spec(&state, 900, motion, 13.0, theme)
                .unwrap_or_else(|| panic!("preview for {raw}"));

            assert_eq!(preview.cursor.trail_style, PreviewTrailStyle::RainbowKitty);
            assert_eq!(preview.cursor.effective_trail_style_raw(), raw);
            assert_eq!(preview.cursor.trail_companion(), expected, "{raw}");
        }
    }

    #[test]
    fn preview_activity_comes_from_the_exact_authored_spec() {
        // The runway ANIMATES because the trail draws on it; the master is asked
        // for rather than inherited, because its absent-key default is
        // platform-split (`app_config::DEFAULT_DECORATIVE_EFFECTS`) and this test
        // is about the preview's activity resolution, not about the default.
        let mut home = SettingsViewState::new(&Config {
            cursor_trail: Some(true),
            ..Config::default()
        });
        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();
        assert_eq!(
            home.preview_animation(
                100,
                motion,
                13.0,
                theme,
                LogicalRect::new(0.0, 0.0, 1_200.0, 720.0),
            ),
            PreviewAnimation::Continuous,
            "wide Top Settings animates its visible cursor runway without requiring focus"
        );
        assert_eq!(
            home.preview_animation(
                100,
                motion,
                13.0,
                theme,
                LogicalRect::new(0.0, 0.0, 390.0, 568.0),
            ),
            PreviewAnimation::None,
            "compact Top Settings page 0 renders only a static theme sample"
        );
        home.page_scroll = 2;
        assert_eq!(
            home.preview_animation(
                100,
                motion,
                13.0,
                theme,
                LogicalRect::new(0.0, 0.0, 390.0, 568.0),
            ),
            PreviewAnimation::Continuous,
            "the visible cursor-trail slice keeps its live preview"
        );

        let mut appearance = SettingsViewState::new(&Config::default());
        appearance.navigate(SettingsRoute::Appearance);
        assert_eq!(
            appearance.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::None,
            "Appearance is a genuinely static renderer sample"
        );
        assert!(
            renderer_preview_spec(&appearance, 100, motion, 17.5, theme)
                .unwrap()
                .audit_value()
                .contains("17.5 px"),
            "an unset font-size preview uses the renderer's applied size"
        );
        assert!(
            renderer_preview_spec(&appearance, 100, motion, 1.0, theme)
                .unwrap()
                .audit_value()
                .contains("6 px"),
            "host font fallback is normalized to the prefs minimum"
        );

        for (authored, expected) in [
            ("BAR", PreviewCursorStyle::Bar),
            (" Beam ", PreviewCursorStyle::Bar),
            ("Underline", PreviewCursorStyle::Bar),
            ("hidden", PreviewCursorStyle::Block),
        ] {
            let config: Config = aterm_toml::from_str(&format!(
                "cursor_style = {authored:?}\ncursor_blink = false\ncursor_trail = false\n"
            ))
            .unwrap();
            let mut state = SettingsViewState::new(&config);
            state.navigate(SettingsRoute::CursorMotion);
            assert_eq!(
                renderer_preview_spec(&state, 100, motion, 13.0, theme)
                    .unwrap()
                    .cursor
                    .style,
                expected,
                "cursor preview must share the owning resolver for {authored:?}"
            );
        }

        let hidden: Config = aterm_toml::from_str(
            "cursor_style = \"hidden\"\ncursor_blink = true\ncursor_trail = false\n",
        )
        .unwrap();
        let mut hidden = SettingsViewState::new(&hidden);
        hidden.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            hidden.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::BlinkEdge { after_ms: 430 },
            "an unknown configured cursor style falls back to the runtime's blinking Block"
        );

        let blink: Config = aterm_toml::from_str(
            "cursor_style = \"block\"\ncursor_blink = true\ncursor_trail = false\n",
        )
        .unwrap();
        let mut blink = SettingsViewState::new(&blink);
        blink.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            blink.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::BlinkEdge { after_ms: 430 }
        );

        let zero: Config = aterm_toml::from_str(
            "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = \"phaser\"\ncursor_trail_intensity = 0.0\n",
        )
        .unwrap();
        let mut zero = SettingsViewState::new(&zero);
        zero.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            zero.preview_animation(100, motion, 13.0, theme, view_cx().viewport),
            PreviewAnimation::None,
            "a zero-intensity trail does not arm invisible work"
        );
    }

    #[test]
    fn canonical_non_cursor_previews_are_pixel_static_across_live_blink_edges() {
        crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
        let config: Config = aterm_toml::from_str(
            "cursor_style = \"bar\"\ncursor_blink = true\ncursor_trail = true\ncursor_trail_style = \"phaser\"\n",
        )
        .unwrap();
        let motion = crate::native_app::ViewMotionCx::default();
        let theme = aterm_render::Theme::default();

        for route in [
            SettingsRoute::Appearance,
            SettingsRoute::TextFonts,
            SettingsRoute::WindowTabs,
        ] {
            let mut state = SettingsViewState::new(&config);
            state.navigate(route);
            let early = renderer_preview_spec(&state, 100, motion, 13.0, theme)
                .unwrap_or_else(|| panic!("early {route:?} preview"));
            let late = renderer_preview_spec(&state, 600, motion, 13.0, theme)
                .unwrap_or_else(|| panic!("late {route:?} preview"));

            assert_eq!(early.animation(), PreviewAnimation::None, "{route:?}");
            assert_eq!(late.animation(), PreviewAnimation::None, "{route:?}");
            assert!(!early.cursor.blink, "{route:?} keeps its static cursor");
            assert!(
                !early.cursor.trail_enabled,
                "{route:?} keeps cursor motion out of its scene"
            );
            assert_eq!(
                early.paint_fingerprint(),
                late.paint_fingerprint(),
                "{route:?} retained identity is phase-static"
            );
            assert_eq!(
                compile_preview_for_pixels(early).1,
                compile_preview_for_pixels(late).1,
                "{route:?} pixels are phase-static"
            );
        }
    }

    #[test]
    fn serious_mode_suppresses_native_preview_trails_post_fx_and_cadence() {
        let config: Config = aterm_toml::from_str(
            "cursor_blink = true\n\
             cursor_trail = true\n\
             cursor_trail_style = \"fire\"\n\
             cursor_trail_bloom = true\n\
             cursor_fire_shimmer = true\n\
             hdr_glow = true\n\
             cursor_glow_sdr_boost = 0.5\n",
        )
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_CURSOR_FIRE_SHIMMER
        )));
        let theme = aterm_render::Theme::default();

        let active = renderer_preview_spec(
            &state,
            100,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            theme,
        )
        .expect("active cursor preview");
        assert!(
            active.cursor.trail_enabled,
            "negative control: trail is authored"
        );
        assert!(active.post_fx.bloom, "negative control: bloom is authored");
        assert!(
            active.post_fx.fire_shimmer,
            "negative control: fire shimmer is authored"
        );

        let serious_motion = crate::native_app::ViewMotionCx {
            serious: true,
            ..crate::native_app::ViewMotionCx::default()
        };
        let serious = renderer_preview_spec(&state, 100, serious_motion, 13.0, theme)
            .expect("serious cursor preview remains available");
        assert!(serious.reduced_motion);
        assert!(!serious.cursor.trail_enabled);
        assert!(!serious.post_fx.bloom);
        assert!(!serious.post_fx.fire_shimmer);
        assert!(!serious.post_fx.hdr_glow);
        assert_eq!(serious.post_fx.sdr_boost, 0.0);
        assert_eq!(serious.animation(), PreviewAnimation::None);
        assert!(preview_reduced_motion(&state, serious_motion));
        assert_ne!(active.paint_fingerprint(), serious.paint_fingerprint());
    }

    #[test]
    fn serious_mode_trail_picker_previews_the_atomic_post_commit_candidate() {
        let config: Config = aterm_toml::from_str(
            "serious_mode = true\ncursor_trail = true\ncursor_trail_style = \"fire\"\n",
        )
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .unwrap();
        let picker = ChoicePicker::new(
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes).unwrap(),
            SettingsState::display_value(field),
            state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE),
            field.seed.is_some(),
            &effective_default_for_field(prefs::EDIT_CURSOR_TRAIL_STYLE),
            &state.assets.themes,
        );
        let water = picker
            .options
            .iter()
            .position(|option| option.value.as_deref() == Some("water"))
            .unwrap();
        let off = picker
            .options
            .iter()
            .position(|option| option.value.as_deref() == Some("off"))
            .unwrap();
        state.choice_picker = Some(picker);
        let serious = crate::native_app::ViewMotionCx {
            serious: true,
            ..crate::native_app::ViewMotionCx::default()
        };
        let theme = aterm_render::Theme::default();

        let focus_candidate = |state: &mut SettingsViewState, index: usize| {
            let picker = state.choice_picker.as_mut().unwrap();
            let page_size = picker.page_size.get();
            picker.offset.set((index / page_size) * page_size);
            state.common.hovered = None;
            state.common.last_focus = Some(UiKey::new(format!(
                "settings/choice/{}/{index}",
                prefs::EDIT_CURSOR_TRAIL_STYLE
            )));
        };
        focus_candidate(&mut state, water);
        let focused = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            theme,
            None,
        )
        .unwrap();
        assert!(focused.cursor.trail_enabled);
        assert!(!focused.reduced_motion);
        assert_eq!(focused.cursor.trail_style, PreviewTrailStyle::Water);
        assert!(focused.post_fx.motion_reason.contains("post-commit"));

        state.common.last_focus = Some(UiKey::new("settings/control/cursor_trail_style"));
        state.common.hovered = Some(UiKey::new(format!(
            "settings/choice/{}/{water}",
            prefs::EDIT_CURSOR_TRAIL_STYLE
        )));
        let hovered = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            theme,
            None,
        )
        .unwrap();
        assert!(hovered.cursor.trail_enabled);
        assert_eq!(hovered.cursor.trail_style, PreviewTrailStyle::Water);

        focus_candidate(&mut state, off);
        let off_candidate = renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            theme,
            None,
        )
        .unwrap();
        assert!(!off_candidate.cursor.trail_enabled);
        assert!(off_candidate.reduced_motion);
        assert!(field_bool(&state, prefs::EDIT_SERIOUS_MODE, false));
    }

    #[test]
    fn compact_top_settings_keeps_serious_mode_disclosure_semantically_reachable() {
        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let service = VersionedConfigService::new("serious_mode = true\n".to_string()).unwrap();
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
            let mut cx = view_cx_at(width, height);
            cx.motion.serious = true;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            compiled.validate_parity().unwrap();
            let disclosure = compiled
                .semantic(&UiKey::new("settings/top/serious-mode"))
                .expect("compact Serious Mode disclosure");
            assert!(disclosure.label.contains("keeps every other effect off"));
            assert!(disclosure.rect.x >= -0.01 && disclosure.rect.y >= -0.01);
            assert!(disclosure.rect.right() <= width + 0.01);
            assert!(disclosure.rect.bottom() <= height + 0.01);
            assert!(
                compiled
                    .paint
                    .iter()
                    .any(|node| node.key == UiKey::new("settings/top/serious-mode/visual")),
                "{width}×{height} keeps a bounded visual status"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/top/serious-mode/visual"))
                    .is_none(),
                "{width}×{height} publishes only the complete status"
            );
            for hit in &compiled.hits {
                assert!(
                    hit.rect.right() <= width + 0.01,
                    "{width}×{height}: {hit:?}"
                );
                assert!(
                    hit.rect.bottom() <= height + 0.01,
                    "{width}×{height}: {hit:?}"
                );
            }
        }
    }

    #[test]
    fn top_settings_paints_direct_labels_but_keeps_complete_label_semantics() {
        let (runtime, _instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_THEME)
            .unwrap();
        let expected_visual = field.label.to_string();
        let row = top_setting_row(
            state,
            prefs::EDIT_THEME,
            None,
            SettingsWidth::Wide,
            LogicalRect::new(0.0, 0.0, 900.0, 80.0),
        )
        .unwrap();
        let compiled = UiTree::new(row)
            .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
            .unwrap();
        let wrapper_key = UiKey::new(format!("settings/label/{}", prefs::EDIT_THEME));
        let semantic = compiled.semantic(&wrapper_key).unwrap();
        assert!(semantic.label.contains("Default"), "{}", semantic.label);
        let visual_key = UiKey::new(format!("settings/label/{}/visual", prefs::EDIT_THEME));
        let visual = compiled
            .paint
            .iter()
            .find_map(|node| {
                (node.key == visual_key)
                    .then_some(&node.content)
                    .and_then(|content| {
                        let UiContent::Text(spec) = content else {
                            return None;
                        };
                        Some(spec.text.as_str())
                    })
            })
            .unwrap();
        assert_eq!(visual, expected_visual);
        assert!(!visual.contains("Default"));
        assert!(!visual.contains("Override"));
        assert!(compiled.semantic(&visual_key).is_none());
    }

    #[test]
    fn music_suppression_resolver_covers_every_reason_and_priority() {
        let motion = crate::native_app::ViewMotionCx::default();
        // THE LADDER NEEDS ITS TOP RUNG STANDING. "Cursor trail is Off" outranks
        // every runtime suppression below it, and the master's absent-key default
        // is platform-split (`app_config::DEFAULT_DECORATIVE_EFFECTS`) — so an
        // inherited default would mask every LOWER reason this test exists to
        // order. Each case therefore ASKS for the master unless it authors one
        // itself; the trail-Off rung below still reaches its reason through
        // `cursor_trail_style = "off"`, which is the same Off by a different door.
        let state = |config: Config| {
            SettingsViewState::new(&Config {
                cursor_trail: config.cursor_trail.or(Some(true)),
                ..config
            })
        };

        assert_eq!(
            top_music_suppression_reason_for_output(&state(Config::default()), motion, false),
            Some("Saved On for macOS; audio output is unavailable on this platform.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    trail_sounds: Some(false),
                    ..Config::default()
                }),
                motion,
                false,
            ),
            Some("Saved Off; audio output is unavailable on this platform.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    trail_sounds: Some(false),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            None,
            "an authored Off switch is not described as suppressed"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    serious_mode: Some(true),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            None,
            "Serious Mode projects the switch Off instead of claiming it is On"
        );

        let all_runtime_suppressions = crate::native_app::ViewMotionCx {
            focused: false,
            system_reduced: true,
            performance_reduced: true,
            ..motion
        };
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    cursor_trail_style: Some("off".to_string()),
                    trail_sound_volume: Some(0.0),
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                all_runtime_suppressions,
                true,
            ),
            Some("On, currently silent because Cursor trail is Off."),
            "trail Off has priority over every later runtime suppression"
        );
        for style in ["pack:", "pack:missing"] {
            let reason = top_music_suppression_reason_for_output(
                &state(Config {
                    cursor_trail_style: Some(style.to_string()),
                    ..Config::default()
                }),
                motion,
                true,
            );
            assert_eq!(
                reason,
                Some("On, currently silent because Cursor trail style is unavailable."),
                "{style:?} has no admitted trail/audio runtime"
            );
            assert_eq!(
                reason.map(top_music_suppression_visual),
                Some("Trail unavailable")
            );
        }
        // A TYPO IS NOT A SILENCER. It resolves to the default style and the
        // trail renders, so the synth keeps its voice — only a resolution that
        // draws nothing takes it away.
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    cursor_trail_style: Some("not-a-trail".to_string()),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            None,
            "an unknown style falls back to the default trail and still plays"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    trail_sound_volume: Some(0.0),
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                all_runtime_suppressions,
                true,
            ),
            Some("On, currently silent because trail sound volume is 0."),
            "zero volume has priority over focus and motion"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                all_runtime_suppressions,
                true,
            ),
            Some("On, currently silent while this window is unfocused."),
            "window focus has priority over motion"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    motion: Some("reduced".to_string()),
                    ..Config::default()
                }),
                motion,
                true,
            ),
            Some("On, currently suppressed by Motion: Reduced.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config::default()),
                crate::native_app::ViewMotionCx {
                    system_reduced: true,
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            Some("On, currently suppressed by system Reduce Motion."),
            "system policy has priority over the adaptive limiter"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config::default()),
                crate::native_app::ViewMotionCx {
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            Some("On, currently suppressed by adaptive performance mode.")
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    load_adaptive_motion: Some(false),
                    ..Config::default()
                }),
                crate::native_app::ViewMotionCx {
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            None,
            "the authored adaptive-motion opt-out is respected"
        );
        assert_eq!(
            top_music_suppression_reason_for_output(
                &state(Config {
                    motion: Some("full".to_string()),
                    ..Config::default()
                }),
                crate::native_app::ViewMotionCx {
                    system_reduced: true,
                    performance_reduced: true,
                    ..motion
                },
                true,
            ),
            None,
            "explicit Full overrides system and adaptive reduction"
        );
    }

    #[test]
    fn music_effects_discloses_effective_motion_suppression_without_rewriting_toggle() {
        let auto = SettingsViewState::new(&Config::default());
        if crate::trail_audio::output_available() {
            let mut system_reduced = crate::native_app::ViewMotionCx {
                system_reduced: true,
                ..crate::native_app::ViewMotionCx::default()
            };
            assert_eq!(
                top_music_suppression_reason(&auto, system_reduced),
                Some("On, currently suppressed by system Reduce Motion.")
            );
            system_reduced.performance_reduced = true;
            system_reduced.system_reduced = false;
            assert_eq!(
                top_music_suppression_reason(&auto, system_reduced),
                Some("On, currently suppressed by adaptive performance mode.")
            );

            let reduced = SettingsViewState::new(&Config {
                motion: Some("reduced".to_string()),
                ..Config::default()
            });
            assert_eq!(
                top_music_suppression_reason(&reduced, crate::native_app::ViewMotionCx::default()),
                Some("On, currently suppressed by Motion: Reduced.")
            );
            let full = SettingsViewState::new(&Config {
                motion: Some("full".to_string()),
                ..Config::default()
            });
            assert_eq!(
                top_music_suppression_reason(
                    &full,
                    crate::native_app::ViewMotionCx {
                        system_reduced: true,
                        performance_reduced: true,
                        ..crate::native_app::ViewMotionCx::default()
                    }
                ),
                None,
                "explicit Full overrides system/adaptive reduction while focused"
            );
        } else {
            assert_eq!(
                top_music_suppression_reason(&auto, crate::native_app::ViewMotionCx::default()),
                Some("Saved On for macOS; audio output is unavailable on this platform.")
            );
            let off = SettingsViewState::new(&Config {
                trail_sounds: Some(false),
                ..Config::default()
            });
            assert_eq!(
                top_music_suppression_reason(&off, crate::native_app::ViewMotionCx::default()),
                Some("Saved Off; audio output is unavailable on this platform.")
            );
        }
        assert!(
            top_projected_music_value(&auto),
            "authored switch remains On"
        );

        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!()
                };
                state.reduce_page_scroll(5, SettingsPageScrollCommand::Absolute(3));
            }
            let mut cx = view_cx_at(width, height);
            cx.motion.system_reduced = true;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let status = compiled
                .semantic(&UiKey::new("settings/top/music-effects/suppression"))
                .expect("compact Music page carries its own suppression status");
            assert!(
                status
                    .label
                    .contains(if crate::trail_audio::output_available() {
                        "system Reduce Motion"
                    } else {
                        "audio output is unavailable"
                    })
            );
            let toggle = compiled
                .semantic(&UiKey::new(format!(
                    "settings/control/{}",
                    prefs::EDIT_TRAIL_SOUNDS
                )))
                .unwrap();
            assert_eq!(toggle.value, SemanticValue::Bool(true));
        }
    }

    #[test]
    fn compact_serious_trail_picker_keeps_disclosure_preview_and_every_choice_reachable() {
        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let service = VersionedConfigService::new("serious_mode = true\n".to_string()).unwrap();
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!(
                            "settings/set/{}",
                            prefs::EDIT_CURSOR_TRAIL_STYLE
                        )),
                        value: None,
                    }),
                )
                .unwrap();

            let mut cx = view_cx_at(width, height);
            cx.motion.serious = true;
            let mut seen = BTreeSet::new();
            // THE SWEEP GOES BOTH WAYS, and that is not belt-and-braces. The picker
            // opens on the AUTHORED candidate (`top_authored_trail_value`), and with
            // no `cursor_trail` key that value follows the platform default: a
            // mid-list style where the trail ships on, and the LAST option (`off`)
            // on Windows, where `DEFAULT_DECORATIVE_EFFECTS` makes the resident pet
            // an opt-in. A next-only walk would therefore have measured one page on
            // Windows and called it reachability. Paging back to the first page and
            // then forward to the last runs the same containment assertions over
            // every page on every host, from wherever the picker happened to open.
            for step in ["settings/choice-page-prev", "settings/choice-page-next"] {
                for _ in 0..16 {
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    compiled.validate_parity().unwrap();
                    for key in [
                        "settings/top/serious-mode",
                        "settings/top/choice-preview",
                        "settings/choice-close",
                        "settings/choice-page-prev",
                        "settings/choice-page-next",
                    ] {
                        let node = compiled
                            .semantic(&UiKey::new(key))
                            .unwrap_or_else(|| panic!("{width}×{height} picker is missing {key}"));
                        assert!(node.rect.right() <= width + 0.01, "{key}: {:?}", node.rect);
                        assert!(
                            node.rect.bottom() <= height + 0.01,
                            "{key}: {:?}",
                            node.rect
                        );
                    }
                    for node in &compiled.semantics {
                        if node.key.as_str().starts_with(&format!(
                            "settings/choice/{}/",
                            prefs::EDIT_CURSOR_TRAIL_STYLE
                        )) {
                            seen.insert(node.key.as_str().to_string());
                        }
                    }
                    for hit in &compiled.hits {
                        assert!(
                            hit.rect.right() <= width + 0.01,
                            "{width}×{height}: {hit:?}"
                        );
                        assert!(
                            hit.rect.bottom() <= height + 0.01,
                            "{width}×{height}: {hit:?}"
                        );
                    }
                    let more = compiled
                        .semantic(&UiKey::new(step))
                        .and_then(|node| node.state.as_ref())
                        .is_some_and(|state| state.enabled);
                    if !more {
                        break;
                    }
                    runtime
                        .dispatch(
                            instance,
                            view,
                            AppEvent::Action(ActionInvocation {
                                id: ActionId::new(step),
                                value: None,
                            }),
                        )
                        .unwrap();
                }
            }
            let AppViewState::Settings(state) = runtime.view_state(view).unwrap() else {
                unreachable!()
            };
            assert_eq!(
                seen.len(),
                state.choice_picker.as_ref().unwrap().options.len(),
                "{width}×{height} reaches every trail choice"
            );
        }
    }

    #[test]
    fn highlighted_motion_candidate_resolves_against_live_host_facts_before_commit() {
        let config: Config = aterm_toml::from_str("motion = \"reduced\"\n").unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        let field = state
            .legacy
            .fields
            .iter()
            .find(|field| field.key == prefs::EDIT_MOTION)
            .expect("motion field");
        let picker = ChoicePicker::new(
            prefs::EDIT_MOTION,
            choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
                .expect("motion choices"),
            SettingsState::display_value(field),
            true,
            true,
            &effective_default_for_field(prefs::EDIT_MOTION),
            &state.assets.themes,
        );
        state.choice_picker = Some(picker);
        let focus = |state: &mut SettingsViewState, value: &str| {
            let picker = state.choice_picker.as_mut().unwrap();
            let index = picker
                .options
                .iter()
                .position(|option| option.value.as_deref() == Some(value))
                .unwrap();
            picker
                .offset
                .set((index / ChoicePicker::PAGE_SIZE) * ChoicePicker::PAGE_SIZE);
            state.common.last_focus = Some(UiKey::new(format!(
                "settings/choice/{}/{index}",
                prefs::EDIT_MOTION
            )));
        };

        let constrained = crate::native_app::ViewMotionCx {
            system_reduced: true,
            focused: true,
            performance_reduced: true,
            system_dark: false,
            serious: false,
        };
        focus(&mut state, "full");
        assert!(
            !preview_reduced_motion(&state, constrained),
            "highlighted Full overrides OS and adaptive reduction"
        );
        focus(&mut state, "auto");
        assert!(preview_reduced_motion(&state, constrained));
        focus(&mut state, "reduced");
        assert!(preview_reduced_motion(
            &state,
            crate::native_app::ViewMotionCx::default()
        ));

        focus(&mut state, "auto");
        let load_only = crate::native_app::ViewMotionCx {
            system_reduced: false,
            focused: true,
            performance_reduced: true,
            system_dark: false,
            serious: false,
        };
        assert!(preview_reduced_motion(&state, load_only));
        state
            .legacy
            .fields
            .iter_mut()
            .find(|field| field.key == prefs::EDIT_LOAD_ADAPTIVE_MOTION)
            .unwrap()
            .seed = Some("false".to_string());
        assert!(!preview_reduced_motion(&state, load_only));

        focus(&mut state, "full");
        assert!(preview_reduced_motion(
            &state,
            crate::native_app::ViewMotionCx {
                focused: false,
                ..crate::native_app::ViewMotionCx::default()
            }
        ));
        assert_eq!(
            state.raw_value(prefs::EDIT_MOTION).as_deref(),
            Some("reduced")
        );
    }

    fn setup() -> (
        NativeRuntime,
        crate::native_app::AppInstanceId,
        crate::native_app::ViewId,
    ) {
        setup_with_update(UpdateState::from_status(1, "0.1.0", None, false))
    }

    fn setup_with_update(
        update: UpdateState,
    ) -> (
        NativeRuntime,
        crate::native_app::AppInstanceId,
        crate::native_app::ViewId,
    ) {
        let app = SettingsApp::new(update);
        let mut runtime = NativeRuntime::new();
        let instance = runtime.insert_instance(NativeApp::Settings(app)).unwrap();
        let mut core_views = ViewStore::default();
        let view = core_views.insert_native(instance).unwrap();
        runtime
            .attach_view(
                view,
                instance,
                AppViewState::Settings(Box::new(SettingsViewState::new(&Config::default()))),
            )
            .unwrap();
        (runtime, instance, view)
    }

    fn replace_settings_source(
        runtime: &mut NativeRuntime,
        view: crate::native_app::ViewId,
        source: String,
    ) {
        let snapshot = VersionedConfigService::new(source)
            .expect("valid Settings fixture")
            .snapshot();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        **state = SettingsViewState::from_snapshot(&snapshot).expect("project Settings fixture");
    }

    /// EVERY RUNG OF THE SOFTWARE UPDATE PAGE ADMITS THE FAILED APPLIES.
    ///
    /// The page collapses as the host narrows — hero label, headline, detail,
    /// minimum-detail — and each rung is authored separately, which is how the
    /// `installable` work once fixed a headline and left the card underneath
    /// contradicting it. So the assertion runs the whole ladder: on the owner's
    /// 2026-08-21 state (staged 0.56.0, two dead applies, `ChildDied`) none of them
    /// may read as "Ready", and the widest rungs must name the count AND the cause.
    #[test]
    fn every_rung_of_the_update_page_admits_a_stage_that_failed_to_apply() {
        use crate::update_apply_trouble::ApplyRetry;

        let mut status = update_status(true);
        status.failing_applies = 2;
        status.outcome = "staged 0.2.0 (build 2) \u{2014} verified and ready to apply".to_string();
        let troubled = UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_apply_lane(
                "overlap handoff failed safely: handoff proof ended ChildDied",
                ApplyRetry::Scheduled,
            )
            .projection();

        assert!(
            !troubled.apply_is_failing,
            "two is below the escalation threshold — the window the page used to \
             spend saying \"Ready\""
        );
        assert_eq!(compact_update_headline(&troubled), "Not applying");
        assert_eq!(compact_update_summary_detail(&troubled), "Not applying");
        let detail = compact_update_detail(&troubled);
        assert!(
            detail.contains("Tried twice") && detail.contains("didn\u{2019}t start"),
            "the compact detail names the count and the cause: {detail}"
        );
        assert!(
            !detail.contains("ChildDied"),
            "never the proof-outcome enum name: {detail}"
        );
        let minimum = compact_update_detail_minimum(&troubled);
        assert!(
            minimum.contains('2'),
            "the count survives to the tersest rung: {minimum}"
        );

        // A CLEAN STAGE IS UNCHANGED. Waiting for a quiet window records refusals,
        // never failures, so every rung must still read as plain readiness.
        let clean = UpdateState::from_status(1, "0.1.0", Some(&update_status(true)), false)
            .with_apply_lane(
                "overlap handoff failed safely: handoff proof ended ChildDied",
                ApplyRetry::Scheduled,
            )
            .projection();
        assert!(clean.apply_trouble.is_none());
        assert_eq!(compact_update_headline(&clean), "Ready");
        assert_eq!(compact_update_summary_detail(&clean), "Ready");
        assert_eq!(compact_update_detail(&clean), "Ready to install.");
        assert_eq!(compact_update_detail_minimum(&clean), "Ready.");
    }

    fn update_status(staged: bool) -> aterm_update::UpdateStatus {
        aterm_update::UpdateStatus {
            linux: None,
            enabled: true,
            current_build: 1,
            staged_build: staged.then_some(2),
            staged_version: staged.then(|| "0.2.0".to_string()),
            staged_commit: staged.then(|| "deadbeef".to_string()),
            staged_dmg_sha256: staged.then(|| "0".repeat(64)),
            changelog: staged
                .then(|| "### Better\n- compact Settings\n- semantic previews".to_string()),
            outcome: "Update service healthy".to_string(),
            updated_at: String::new(),
            failing_checks: 0,
            failing_kind: String::new(),
            failing_applies: 0,
            installable: true,
            failing_since: String::new(),
            failing_persistent: false,
            rescues: 0,
            failing_checks_kind: String::new(),
            channel_unreadable: false,
        }
    }

    fn view_cx() -> ViewCx<'static> {
        view_cx_at(1_200.0, 820.0)
    }

    fn view_cx_at(width: f32, height: f32) -> ViewCx<'static> {
        // NativeRuntime view tests bypass App/backend construction. Opt into
        // the exact host-prepared UI faces at this direct-view fixture boundary
        // instead of changing the cold font-store constructor under cfg(test).
        crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
        ViewCx {
            viewport: LogicalRect::new(0.0, 0.0, width, height),
            config_revision: 1,
            update_revision: 1,
            animation_phase_ms: 720,
            motion: crate::native_app::ViewMotionCx::default(),
            terminal_font_px: 12.0,
            terminal_theme: aterm_render::Theme::default(),
            semantic_font: None,
            document: None,
        }
    }

    // -----------------------------------------------------------------------
    // The macOS access block (design §3.4, §3.7)
    // -----------------------------------------------------------------------

    /// Every phrase `tools/grep_guard.sh` B12 fences, plus the shapes the
    /// value-level guard in `update_words.rs` enumerates. Belt and braces: the
    /// guard reads the FILE, this reads the strings a reader actually sees,
    /// including the ones built by `format!` that no grep can evaluate.
    const BANNED_PANEL_PHRASES: &[&str] = &[
        "restart",
        "relaunch",
        "re-launch",
        "reopen",
        "re-open",
        "reboot",
        "quit and open",
        "quit and reopen",
        "next launch",
        "open aterm again",
        "start aterm again",
    ];

    /// Vocabulary that would assert which folders a grant covers. §7 S4 has not
    /// been run, so `fda_coverage_measured` is false and NONE of this may
    /// appear. The one word that is allowed is "covers" inside the honest
    /// sentence that says aterm has NOT measured coverage — checked separately.
    const COVERAGE_CLAIM_WORDS: &[&str] = &[
        "retires",
        "covered",
        "all files",
        "every folder on",
        "network volume",
        "removable volume",
        "icloud",
        "other apps",
        "no longer be interrupted",
        "will not be interrupted",
    ];

    /// Words that would overstate propagation of a changed grant. §7 S1 has
    /// not been run; the current host's successful probe is not evidence that
    /// an existing or future session has gained access.
    const SCOPE_WORDS: &[&str] = &[
        "this process",
        "sessions started",
        "a newer aterm",
        "does not yet see",
        "already running",
        "started since",
    ];

    fn access_fixture(
        fda: FdaState,
        dr: DrClass,
        scope: aterm_containment::FdaScope,
    ) -> MacosAccess {
        MacosAccess {
            enabled: true,
            // The healthy anchor is the fixture default; the tests that care
            // set it explicitly.
            anchor: aterm_containment::ImageAnchor::Live,
            fda,
            probe: match fda {
                FdaState::Granted => ProbeLabel::OpenOk,
                FdaState::Denied => ProbeLabel::OpenEperm,
                FdaState::Unknown => ProbeLabel::RefusedOutOfBundle,
            },
            dr,
            evidence: SpikeEvidence {
                fda_scope: scope,
                ..SpikeEvidence::UNMEASURED
            },
            bundle_id: Some("com.example.fixture".to_string()),
            install: "installed",
            running: Some("/Applications/fixture.app/Contents/MacOS/fixture".to_string()),
            sessions_total: 2,
            sessions_adopted: 1,
            covers: Vec::new(),
            uncovered: vec!["file-provider-domains"],
            unmeasured: vec![
                "documents",
                "desktop",
                "downloads",
                "network-volumes",
                "removable-volumes",
                "app-data",
            ],
            tccutil: TccutilPresence::Executable,
            warmup_offered: true,
            warmup_live: false,
            warmup_rows: Vec::new(),
            reset: None,
            claimants: None,
            trash_tool: true,
            retire_live: false,
            retired: None,
        }
    }

    /// A census with the running copy (Developer ID when `running_stable`, else
    /// ad hoc), an ad-hoc `.rollback` beside it and a Developer-ID copy from
    /// another team.
    fn census_fixture(running_stable: bool) -> aterm_containment::consent::Claimants {
        use aterm_containment::consent::{Claimant, Claimants, Enumeration, classify_dr};
        let copy =
            |path: &str, dr_text: &str, signing: &'static str, team: Option<&str>| Claimant {
                path: std::path::PathBuf::from(path),
                dr: classify_dr(dr_text),
                dr_text: dr_text.to_string(),
                signing,
                team: team.map(str::to_string),
                running: path == "/Applications/aterm.app",
            };
        let dev_id = |team: &str| {
            format!(
                "designated => identifier \"x\" and anchor apple generic and certificate \
                 leaf[subject.OU] = \"{team}\""
            )
        };
        let running = if running_stable {
            copy(
                "/Applications/aterm.app",
                &dev_id("T"),
                "developer-id",
                Some("T"),
            )
        } else {
            copy(
                "/Applications/aterm.app",
                "designated => cdhash H\"00\"",
                "adhoc",
                None,
            )
        };
        Claimants {
            found: vec![
                running,
                copy(
                    "/Applications/aterm.app.rollback",
                    "designated => cdhash H\"aa\"",
                    "adhoc",
                    None,
                ),
                copy(
                    "/Users//a/Old/aterm.app",
                    &dev_id("U"),
                    "developer-id",
                    Some("U"),
                ),
            ],
            enumeration: Enumeration::Complete,
        }
    }

    fn every_retire_outcome() -> crate::consent_retire::RetireReport {
        use aterm_containment::consent::Retired;
        [
            ("/A/moved.app", Retired::Moved),
            ("/A/gone.app", Retired::NotOffered),
            ("/A/busy.app", Retired::InUse),
            (
                "/A/refused.app",
                Retired::Failed("The operation couldn’t be completed.".to_string()),
            ),
        ]
        .into_iter()
        .map(|(path, outcome)| (std::path::PathBuf::from(path), outcome))
        .collect()
    }

    /// The census on the panel: the mechanism once, a line per conflicting copy,
    /// and a *Move to Trash* button exactly when its plan is non-empty — only
    /// the ad-hoc copy, never the Developer-ID one. Without the tool, or beside
    /// an unstable running copy, there is no button and the panel says why.
    #[test]
    fn the_census_is_on_the_panel_and_the_trash_button_takes_only_what_it_lists() {
        use aterm_containment::FdaScope;
        let buttons = |access: &MacosAccess| -> Vec<String> {
            let mut out = Vec::new();
            fn walk(node: &UiNode, out: &mut Vec<String>) {
                if let UiContent::Button(control) = &node.content {
                    out.push(control.action.as_str().to_string());
                }
                for child in &node.children {
                    walk(child, out);
                }
            }
            walk(&macos_access_card(access, false), &mut out);
            out
        };
        let mut access = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
        assert!(
            macos_access_copy(&access).claimants.is_empty(),
            "no census, no rows"
        );

        access.claimants = Some(census_fixture(true));
        let copy = macos_access_copy(&access);
        assert_eq!(copy.claimants.len(), 3, "{:#?}", copy.claimants);
        assert!(copy.claimants[0].contains("clears this access for every copy"));
        assert_eq!(
            copy.claimants[1],
            "/Applications/aterm.app.rollback \u{2014} signed ad hoc"
        );
        assert_eq!(
            copy.claimants[2],
            "/Users//a/Old/aterm.app \u{2014} signed by team U"
        );
        assert_eq!(
            access.retire_plan(),
            vec![std::path::PathBuf::from("/Applications/aterm.app.rollback")]
        );
        assert!(buttons(&access).contains(&MACOS_ACCESS_TRASH.to_string()));
        assert!(
            macos_access_height(&access, false)
                > macos_access_height(
                    &MacosAccess {
                        claimants: None,
                        ..access.clone()
                    },
                    false
                ),
            "the card is authored tall enough for its rows"
        );

        access.trash_tool = false;
        assert!(access.retire_plan().is_empty());
        assert!(!buttons(&access).contains(&MACOS_ACCESS_TRASH.to_string()));
        assert!(
            macos_access_copy(&access)
                .claimants
                .last()
                .is_some_and(|line| line.contains("no trash tool"))
        );

        access.trash_tool = true;
        access.claimants = Some(census_fixture(false));
        assert!(
            access.retire_plan().is_empty(),
            "beside an unstable running copy"
        );
        assert!(!buttons(&access).contains(&MACOS_ACCESS_TRASH.to_string()));
        assert!(
            macos_access_copy(&access)
                .claimants
                .last()
                .is_some_and(|line| line.contains("only when it is signed ad hoc"))
        );

        access.retired = Some(every_retire_outcome());
        let retired = macos_access_copy(&access).retired;
        assert_eq!(retired.len(), 4);
        assert_eq!(retired[0], "Moved to the Trash: /A/moved.app.");
        assert!(retired[2].contains("in use"), "{retired:?}");
        assert!(retired[3].ends_with("The operation couldn’t be completed."));
    }

    /// A gesture that changes this Mac waits for the owner's yes. With no
    /// answer (the inert arm: no window, or a control client driving the page
    /// with `key`) the warm-up, the reset and *Move to Trash* do nothing and say
    /// so.
    #[test]
    fn an_unconfirmed_owner_gesture_changes_nothing() {
        use aterm_containment::FdaScope;
        let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        access.warmup_rows = denied_rows();
        access.claimants = Some(census_fixture(true));
        for (action, said) in [
            (MACOS_ACCESS_WARM_UP, "Nothing was asked."),
            (MACOS_ACCESS_ASK_AGAIN, "Nothing was changed."),
            (MACOS_ACCESS_TRASH, "Nothing was moved."),
        ] {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Security);
                state.replace_macos_access(access.clone());
            }
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(action),
                        value: None,
                    }),
                )
                .unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            assert!(!state.take_consent_warmup_request(), "{action}");
            assert_eq!(state.take_claimant_retire_request(), None, "{action}");
            assert!(
                state
                    .macos_access_for_test()
                    .is_some_and(|access| access.reset.is_none()),
                "{action}"
            );
            assert_eq!(state.feedback.as_deref(), Some(said), "{action}");
        }
    }

    /// The press records the plan for the host and says what it is doing; with
    /// nothing to move, or a worker already out, it records nothing.
    #[test]
    fn the_trash_press_records_its_plan_once() {
        use aterm_containment::FdaScope;
        let press = |access: MacosAccess| {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Security);
                state.replace_macos_access(access);
                state.arm_consent_gestures(ConsentGestures::confirming());
            }
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(MACOS_ACCESS_TRASH),
                        value: None,
                    }),
                )
                .unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            (state.take_claimant_retire_request(), state.feedback.clone())
        };
        let mut access = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
        access.claimants = Some(census_fixture(true));
        let (plan, said) = press(access.clone());
        assert_eq!(
            plan,
            Some(vec![std::path::PathBuf::from(
                "/Applications/aterm.app.rollback"
            )])
        );
        assert_eq!(
            said.as_deref(),
            Some("Moving 1 other copy of aterm to the Trash\u{2026}")
        );

        let (plan, said) = press(MacosAccess {
            retire_live: true,
            ..access.clone()
        });
        assert_eq!(plan, None);
        assert!(said.is_some_and(|s| s.contains("already moving")));

        let (plan, said) = press(MacosAccess {
            claimants: None,
            ..access
        });
        assert_eq!(plan, None);
        assert!(said.is_some_and(|s| s.contains("no other copy")));
    }

    /// A grant that macOS cannot CHECK is said so on the panel, beside the
    /// path, and does not hide behind a granted headline.
    ///
    /// The owner-facing half of the detector: an in-place apply renames the
    /// bundle a live aterm was exec'd from and boot-health deletes it, after
    /// which tccd can build no code identity and every request is asked again,
    /// while the probe's headline can still read "granted".
    #[test]
    fn a_bundle_that_is_no_longer_there_is_named_on_the_panel() {
        use aterm_containment::{FdaScope, ImageAnchor};

        let healthy = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
        let copy = macos_access_copy(&healthy);
        assert!(
            !copy.identity.contains("no longer on disk"),
            "a live anchor says nothing extra: {}",
            copy.identity
        );

        for anchor in [ImageAnchor::Displaced, ImageAnchor::Deleted] {
            let mut broken =
                access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
            broken.anchor = anchor;
            let copy = macos_access_copy(&broken);
            assert!(
                copy.identity.contains("no longer on disk under this name"),
                "{anchor:?}: {}",
                copy.identity
            );
            assert!(
                copy.identity.contains("asks again for everything"),
                "{anchor:?}: the consequence, not just the fact: {}",
                copy.identity
            );
            assert!(
                copy.identity.contains("is not reaching this copy"),
                "{anchor:?}: and that the Settings grant is not the problem: {}",
                copy.identity
            );
        }

        // The two non-faults stay silent: a dev run outside a bundle and a path
        // that could not be read are not broken grants.
        for benign in [ImageAnchor::NotBundled, ImageAnchor::Unknown] {
            let mut access =
                access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
            access.anchor = benign;
            assert!(
                !macos_access_copy(&access)
                    .identity
                    .contains("no longer on disk"),
                "{benign:?} is not a fault"
            );
        }
    }

    #[test]
    fn macos_access_app_data_uses_host_authority_without_claiming_adopted_access() {
        use aterm_containment::FdaScope;
        for fda in [FdaState::Granted, FdaState::Denied, FdaState::Unknown] {
            let mut access = access_fixture(fda, DrClass::Identity, FdaScope::Unknown);
            let split = crate::control_privacy::covers_split(fda, access.evidence);
            access.covers = split.covers;
            access.uncovered = split.uncovered;
            access.unmeasured = split.unmeasured;
            let copy = macos_access_copy(&access);
            let app_data = copy
                .services
                .iter()
                .find(|row| row.starts_with("Other applications' data"))
                .unwrap();
            if fda == FdaState::Granted {
                // NARROWED 2026-09-19. The row used to attribute its claim to
                // Apple's documentation, because that was all the tree had; §7
                // S4 measured this class on this OS, so it now says measured.
                // The obligation that survives is the one the test is named
                // for: the claim stops at the OBSERVING HOST. It may not be
                // stated for adopted sessions, which is what the `responsible`
                // assertion below still pins.
                assert!(app_data.contains("measured on this Mac"), "{app_data}");
                assert!(
                    !app_data.contains("Apple-documented"),
                    "a measurement is no longer reported as documentation: {app_data}"
                );
                assert!(!app_data.contains("not measured"), "{app_data}");
            } else {
                assert!(app_data.contains("not measured"), "{app_data}");
                assert!(!app_data.contains("confirmed"), "{app_data}");
            }
            assert!(copy.responsible.contains("does not establish their access"));
        }
    }

    fn denied_rows() -> Vec<MacosAccessRow> {
        Folder::ALL
            .iter()
            .map(|folder| (*folder, crate::consent_warmup::WarmupRow::Denied))
            .collect()
    }

    #[test]
    fn macos_access_recovery_names_the_bundle_without_claiming_adopted_access() {
        let access = access_fixture(
            FdaState::Denied,
            DrClass::Identity,
            aterm_containment::FdaScope::Unknown,
        );
        let copy = macos_access_copy(&access);
        assert!(copy.headline.contains("may already be enabled"));
        assert!(copy.route.contains("/Applications/fixture.app"));
        assert!(
            !copy.route.contains("Contents/MacOS"),
            "Settings takes the app, not its executable"
        );
        assert!(copy.route.contains("App Management is a different setting"));
        assert!(!copy.identity.contains("a grant made for this path applies"));
        assert!(copy.responsible.contains("does not establish their access"));
        assert!(copy.responsible.contains("A new tab"));
        assert!(copy.responsible.contains("existing work can keep running"));
    }

    /// THE MATRIX §3.4 asks for: `{granted, denied, unknown}` ×
    /// `{identity, cdhash}` × `{this_process, new_processes, unknown}`, with and
    /// without a denied folder set. Every cell must render a complete, total
    /// string table — and the scope axis must change NOTHING, because §3.4's
    /// escalation clause ships no scope sentence at all.
    #[test]
    fn the_macos_access_panel_renders_every_state_and_never_speaks_about_scope() {
        use aterm_containment::FdaScope;
        for fda in [FdaState::Granted, FdaState::Denied, FdaState::Unknown] {
            for dr in [DrClass::Identity, DrClass::Cdhash] {
                let mut baseline = None;
                for scope in [
                    FdaScope::ThisProcess,
                    FdaScope::NewProcesses,
                    FdaScope::Unknown,
                ] {
                    for rows in [Vec::new(), denied_rows()] {
                        let mut access = access_fixture(fda, dr, scope);
                        access.warmup_rows = rows.clone();
                        let copy = macos_access_copy(&access);
                        let context = format!("{fda:?}/{dr:?}/{scope:?}/{}", rows.len());

                        assert!(!copy.headline.is_empty(), "{context}: a state line");
                        assert!(!copy.probe_detail.is_empty(), "{context}: a probe reason");
                        assert!(!copy.coverage.is_empty(), "{context}: a coverage sentence");
                        assert!(!copy.trade.is_empty(), "{context}: the trade");
                        assert!(!copy.prompt.is_empty(), "{context}: the prompt state");
                        assert!(
                            copy.route.contains("Full Disk Access"),
                            "{context}: the route stays in words on every outcome"
                        );
                        assert_eq!(
                            copy.folders.len(),
                            rows.len(),
                            "{context}: one line per observed folder, no invention"
                        );

                        // The rendered card must also compile for this cell.
                        let card = macos_access_card(&access, false);
                        assert_eq!(card.key, UiKey::new("settings/macos-access"));

                        // THE SCOPE AXIS IS INERT. Same evidence but for
                        // `fda_scope`, same words — which is exactly what
                        // "ships with no scope sentence" means, expressed as a
                        // property rather than as a grep.
                        let strings = copy
                            .strings()
                            .into_iter()
                            .map(str::to_string)
                            .collect::<Vec<_>>();
                        match baseline.as_ref() {
                            None => baseline = Some((rows.len(), strings)),
                            Some((len, first)) if *len == rows.len() => assert_eq!(
                                first, &strings,
                                "{context}: fda_scope changed the copy; §3.4's escalation ships \
                                 no scope sentence until §7 S1 is measured"
                            ),
                            Some(_) => baseline = Some((rows.len(), strings)),
                        }
                    }
                }
            }
        }
    }

    /// §3.4's copy fence, checked on the VALUES rather than on the file. Every
    /// string the panel can produce, over the same matrix plus every probe
    /// label, every reset outcome and every warm-up row.
    #[test]
    fn no_macos_access_string_is_fence_dirty_or_claims_coverage() {
        use crate::consent_warmup::WarmupRow;
        use aterm_containment::FdaScope;
        let mut seen = Vec::new();
        for fda in [FdaState::Granted, FdaState::Denied, FdaState::Unknown] {
            for dr in [
                DrClass::Identity,
                DrClass::Cdhash,
                DrClass::Unsigned,
                DrClass::Unknown,
            ] {
                for probe in [
                    ProbeLabel::Pending,
                    ProbeLabel::OpenOk,
                    ProbeLabel::OpenEperm,
                    ProbeLabel::OpenErrno(13),
                    ProbeLabel::RefusedOutOfBundle,
                    ProbeLabel::RefusedNoExe,
                    ProbeLabel::RefusedDisabled,
                    ProbeLabel::RefusedNoHome,
                    ProbeLabel::RefusedBadPath,
                    ProbeLabel::UnsupportedPlatform,
                ] {
                    for row in [
                        WarmupRow::Unknown,
                        WarmupRow::Asking,
                        WarmupRow::Allowed,
                        WarmupRow::Denied,
                        WarmupRow::Error,
                    ] {
                        for reset in [
                            None,
                            Some(MacosAccessReset {
                                outcome: ResetOutcome::AllReset,
                                reset: Folder::ALL.to_vec(),
                                declined: Vec::new(),
                            }),
                            Some(MacosAccessReset {
                                outcome: ResetOutcome::Partial,
                                reset: vec![Folder::Documents],
                                declined: vec![
                                    (Folder::Desktop, Some(1)),
                                    (Folder::Downloads, None),
                                ],
                            }),
                            Some(MacosAccessReset {
                                outcome: ResetOutcome::NoneReset,
                                reset: Vec::new(),
                                declined: vec![(Folder::Documents, Some(70))],
                            }),
                            Some(MacosAccessReset {
                                outcome: ResetOutcome::ToolAbsent,
                                reset: Vec::new(),
                                declined: Vec::new(),
                            }),
                            Some(MacosAccessReset {
                                outcome: ResetOutcome::NotAttempted,
                                reset: Vec::new(),
                                declined: Vec::new(),
                            }),
                        ] {
                            for enabled in [true, false] {
                                let mut access = access_fixture(fda, dr, FdaScope::Unknown);
                                access.enabled = enabled;
                                access.probe = probe;
                                access.warmup_rows =
                                    Folder::ALL.iter().map(|f| (*f, row)).collect();
                                access.reset = reset.clone();
                                access.claimants = Some(census_fixture(true));
                                access.retired = Some(every_retire_outcome());
                                seen.extend(
                                    macos_access_copy(&access)
                                        .strings()
                                        .into_iter()
                                        .map(str::to_string),
                                );
                            }
                        }
                    }
                }
            }
        }
        assert!(!seen.is_empty());
        // The service rows say what is MEASURED about each class and nothing
        // more: with the measurement unrun, none may say the grant applies.
        for line in seen.iter().filter(|l| l.contains(" \u{2014} not measured")) {
            assert!(!line.contains("applies"), "{line}");
        }
        for line in &seen {
            let lower = line.to_ascii_lowercase();
            for banned in BANNED_PANEL_PHRASES {
                assert!(
                    !lower.contains(banned),
                    "the panel says {banned:?} (owner ruling; grep_guard B12): {line}"
                );
            }
            // §7 S4 is unrun, so `fda_coverage_measured` is false everywhere in
            // this sweep and NO string may assert what a grant covers.
            for claim in COVERAGE_CLAIM_WORDS {
                assert!(
                    !lower.contains(claim),
                    "the panel claims coverage ({claim:?}) while fda_coverage_measured is \
                     false: {line}"
                );
            }
            for scope in SCOPE_WORDS {
                assert!(
                    !lower.contains(scope),
                    "the panel states a grant's scope ({scope:?}) while §7 S1 is unmeasured: \
                     {line}"
                );
            }
            assert!(
                !lower.contains("no more prompt") && !lower.contains("never be interrupted"),
                "the panel promises elimination; the owner's ruling is that mitigating this is \
                 acceptable: {line}"
            );
        }
    }

    /// THE BLOCK IS REACHABLE ON THE WINDOW IT WAS MEASURED ABSENT ON
    /// (2026-09-10): 624x348 logical takes the landscape pager, which never
    /// carried it; and on a short compact page it is a page-0 disclosure, so
    /// page 1 shows a control row instead of the block again.
    #[test]
    fn the_macos_access_block_is_reachable_on_a_short_landscape_window() {
        use aterm_containment::FdaScope;
        let access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            assert!(state.replace_macos_access(access.clone()));
        }
        let cx = view_cx_at(624.0, 348.0);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new("settings/macos-access/heading"))
                .is_some(),
            "page 0 of the landscape pager is the block"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(MACOS_ACCESS_OPEN_FDA))
                .is_some(),
            "and its Open Privacy & Security button is a hit target there"
        );
        // Page 1 is a control row, not the block again.
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = 1;
        }
        let next = compile_settings_view(&runtime, instance, view, &cx);
        next.validate_parity().unwrap();
        assert!(
            next.semantic(&UiKey::new("settings/macos-access/heading"))
                .is_none(),
            "the block is a page-0 slice"
        );
        assert!(
            next.semantics
                .iter()
                .any(|node| node.key.as_str().starts_with("settings/row/")),
            "page 1 reaches a permission toggle"
        );
        // A tall page carries the complete block: identity, attribution and
        // every service class in words.
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = 0;
        }
        let tall = compile_settings_view(&runtime, instance, view, &view_cx_at(1_280.0, 900.0));
        tall.validate_parity().unwrap();
        for key in [
            "settings/macos-access/identity",
            "settings/macos-access/responsible",
            "settings/macos-access/service/0",
            "settings/macos-access/service/6",
        ] {
            assert!(tall.semantic(&UiKey::new(key)).is_some(), "{key}");
        }
        let copy = macos_access_copy(&access);
        assert!(
            copy.identity.contains("installed in Applications"),
            "{}",
            copy.identity
        );
        assert!(
            copy.responsible.contains("1 of 2 sessions"),
            "{}",
            copy.responsible
        );
        assert_eq!(copy.services.len(), 7);
        assert!(
            copy.services
                .iter()
                .any(|s| s.starts_with("Other applications' data \u{2014} not measured")),
            "{:?}",
            copy.services
        );
        assert!(
            copy.services
                .iter()
                .any(|s| s.contains("Cloud-storage") && s.contains("does not apply")),
            "{:?}",
            copy.services
        );
    }

    /// The coverage sentence is selected by a NAMED FIELD, not by prose, and it
    /// keeps the measured and unmeasured halves APART.
    ///
    /// NARROWED 2026-09-19, not deleted. The original asserted that the shipped
    /// sentence says aterm "has not measured" — full stop — which was right
    /// while §7 S4 was unrun and became wrong the day app-data was measured.
    /// The tripwire's real job survives and is now stated as two obligations:
    /// the sentence must still disclaim the classes nobody has measured, AND it
    /// may not claim measured coverage for them. Naming the unmeasured classes
    /// individually is what lets both assertions be checked at once.
    #[test]
    fn the_coverage_sentence_is_gated_on_measured_evidence() {
        use aterm_containment::FdaScope;
        let unmeasured = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
        assert!(!unmeasured.evidence.fda_coverage_measured);
        let today = macos_access_copy(&unmeasured);
        assert!(
            today.coverage.contains("has not been measured"),
            "the sentence must still say which reach was NOT measured: {}",
            today.coverage
        );
        // The four classes S4 could not isolate have to be named, so the
        // disclaimer cannot quietly shrink to nothing.
        for unmeasured_class in ["Documents", "network and removable drives", "already open"] {
            assert!(
                today.coverage.contains(unmeasured_class),
                "the unmeasured classes are named, not folded away ({unmeasured_class}): {}",
                today.coverage
            );
        }
        assert!(
            today.coverage.contains("single grant macOS offers"),
            "…while still naming Full Disk Access as the one grant on offer: {}",
            today.coverage
        );
        assert!(
            today.prompt.contains("cannot be ruled out"),
            "a held grant whose breadth is unmeasured still leaves a prompt possible — and \
             says so as a GRANTED state, not as the missing-grant sentence: {}",
            today.prompt
        );
        let denied = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        assert!(
            macos_access_copy(&denied)
                .prompt
                .contains("can still be interrupted"),
            "the missing-grant sentence is the denied state's"
        );

        let mut measured = unmeasured.clone();
        measured.evidence.fda_coverage_measured = true;
        let strengthened = macos_access_copy(&measured);
        assert_ne!(
            strengthened.coverage, today.coverage,
            "the strengthening is a field flip, not a prose rewrite"
        );
        for folder in Folder::ALL {
            assert!(
                !strengthened
                    .coverage
                    .to_ascii_lowercase()
                    .contains(folder.as_str()),
                "even the measured sentence names no folder here; the measurement does"
            );
        }
    }

    /// §3.7's denied state, said exactly as the design words it, plus the two
    /// owner-initiated repairs and nothing automatic.
    #[test]
    fn a_denied_folder_says_macos_is_not_asking_again_and_offers_two_repairs() {
        use aterm_containment::FdaScope;
        let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        access.warmup_rows = denied_rows();
        let copy = macos_access_copy(&access);
        assert_eq!(copy.folders.len(), Folder::ALL.len(), "{:?}", copy.folders);
        for (line, folder) in copy.folders.iter().zip(Folder::ALL) {
            // §3.7's sentence, with the NOUN the item takes: the three folders
            // are folders of the human's, and the fourth is another app's data.
            assert!(
                line.contains(&format!(
                    "macOS is not asking again for this {}",
                    folder.noun()
                )),
                "a denied row must say exactly that: {line}"
            );
            assert!(
                line.starts_with(folder.label()),
                "a row names its item first: {line}"
            );
        }
        assert!(
            copy.repair
                .iter()
                .any(|line| line.contains("yours to start")),
            "neither repair is automatic: {:?}",
            copy.repair
        );

        // Both repairs are drawn, and both are buttons — nothing runs without a
        // press.
        let card = macos_access_card(&access, false);
        let actions = card
            .children
            .iter()
            .find(|node| node.key == UiKey::new("settings/macos-access/actions"))
            .expect("the action row");
        let keys = actions
            .children
            .iter()
            .map(|node| node.key.clone())
            .collect::<Vec<_>>();
        assert!(keys.contains(&UiKey::new(MACOS_ACCESS_OPEN_FILES)));
        assert!(keys.contains(&UiKey::new(MACOS_ACCESS_ASK_AGAIN)));
        assert!(access.shows_reset_button());

        // And with nothing denied, neither repair is offered at all.
        let mut quiet = access.clone();
        quiet.warmup_rows = Vec::new();
        assert!(!quiet.shows_reset_button());
        let quiet_card = macos_access_card(&quiet, false);
        let quiet_actions = quiet_card
            .children
            .iter()
            .find(|node| node.key == UiKey::new("settings/macos-access/actions"))
            .expect("the action row");
        assert!(
            !quiet_actions
                .children
                .iter()
                .any(|node| node.key == UiKey::new(MACOS_ACCESS_ASK_AGAIN)),
            "a reset is offered only for folders macOS actually refused"
        );
    }

    /// §3.7's suppression: a grant bound to a `cdhash` was invalidated by a
    /// REBUILD, not by the owner. The button is not drawn, no plan exists, and
    /// the panel says what happened instead of offering a repair that cannot
    /// hold. The same holds for an unsigned build (§3.1's dev-build line).
    #[test]
    fn a_rebuild_invalidated_identity_suppresses_the_reset_and_explains_itself() {
        use aterm_containment::FdaScope;
        for dr in [DrClass::Cdhash, DrClass::Unsigned] {
            let mut access = access_fixture(FdaState::Denied, dr, FdaScope::Unknown);
            access.warmup_rows = denied_rows();
            assert_eq!(access.reset_offer(), ResetOffer::ExplainRebuild, "{dr:?}");
            assert!(!access.shows_reset_button(), "{dr:?}");
            assert!(
                access.reset_plan().is_none(),
                "{dr:?}: no argv is even built"
            );

            let copy = macos_access_copy(&access);
            let rebuild = copy.rebuild.as_deref().expect("the rebuild explanation");
            assert!(rebuild.contains("rebuild"), "{dr:?}: {rebuild}");
            assert!(rebuild.contains("not by you"), "{dr:?}: {rebuild}");
            assert!(
                rebuild.contains("Developer ID"),
                "{dr:?}: it points at the dev-identity fix: {rebuild}"
            );

            let card = macos_access_card(&access, false);
            let actions = card
                .children
                .iter()
                .find(|node| node.key == UiKey::new("settings/macos-access/actions"))
                .expect("the action row");
            assert!(
                !actions
                    .children
                    .iter()
                    .any(|node| node.key == UiKey::new(MACOS_ACCESS_ASK_AGAIN)),
                "{dr:?}: the button is not shown at all"
            );
            assert!(
                actions
                    .children
                    .iter()
                    .any(|node| node.key == UiKey::new(MACOS_ACCESS_OPEN_FILES)),
                "{dr:?}: the deep link stays — it is the repair that still works"
            );
        }

        // An UNKNOWN requirement is not a rebuild claim. It offers the repair
        // with no durability promise rather than asserting something nobody
        // observed.
        let mut unknown = access_fixture(FdaState::Denied, DrClass::Unknown, FdaScope::Unknown);
        unknown.warmup_rows = denied_rows();
        assert_eq!(unknown.reset_offer(), ResetOffer::Offer);
        assert!(macos_access_copy(&unknown).rebuild.is_none());
    }

    /// The other two suppressions §3.7 names: an absent or unproven `tccutil`,
    /// and a bundle id there is no way to claim. Both hide the button entirely
    /// rather than offering a destructive gesture that cannot work.
    #[test]
    fn the_reset_button_is_hidden_without_a_proven_tool_or_a_subject() {
        use aterm_containment::FdaScope;
        for tccutil in [
            TccutilPresence::Missing,
            TccutilPresence::NotExecutable,
            TccutilPresence::Unknown,
        ] {
            let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
            access.warmup_rows = denied_rows();
            access.tccutil = tccutil;
            assert_eq!(access.reset_offer(), ResetOffer::HideNoTool, "{tccutil:?}");
            assert!(!access.shows_reset_button(), "{tccutil:?}");
        }
        for bundle_id in [None, Some(String::new()), Some("  ".to_string())] {
            let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
            access.warmup_rows = denied_rows();
            access.bundle_id = bundle_id.clone();
            assert_eq!(
                access.reset_offer(),
                ResetOffer::HideNoBundleId,
                "{bundle_id:?}"
            );
            assert!(!access.shows_reset_button(), "{bundle_id:?}");
        }
    }

    /// The plan is built from the RUNNING bundle id and from exactly the
    /// folders macOS refused — never a literal, never a folder nobody denied,
    /// and never the every-app form.
    #[test]
    fn the_reset_plan_names_the_running_bundle_and_only_the_refused_folders() {
        use crate::consent_warmup::WarmupRow;
        use aterm_containment::FdaScope;
        let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        access.bundle_id = Some("com.example.running".to_string());
        access.warmup_rows = vec![
            (Folder::Documents, WarmupRow::Denied),
            (Folder::Desktop, WarmupRow::Allowed),
            (Folder::Downloads, WarmupRow::Denied),
        ];
        let plan = access.reset_plan().expect("a plan for the refused folders");
        assert_eq!(plan.bundle_id(), "com.example.running");
        assert_eq!(plan.folders(), &[Folder::Documents, Folder::Downloads]);
        for (folder, argv) in plan.commands() {
            assert_eq!(
                argv.len(),
                4,
                "{folder:?}: the dangerous every-app form is unreachable"
            );
            assert_eq!(argv[3], "com.example.running");
            assert!(argv.contains(&folder.tcc_service().to_string()));
        }
    }

    /// The fold, at the exact strength each outcome earned. `AllReset` is the
    /// only value allowed to speak for the whole set; a partial success names
    /// what it cleared and gives every declined invocation its own line with
    /// the exit status. No retry appears anywhere.
    #[test]
    fn a_partial_reset_is_reported_as_partial_with_one_line_per_failure() {
        let all = MacosAccessReset::from_attempts(&[
            ResetAttempt::from_exit_status(Folder::Documents, Some(0)),
            ResetAttempt::from_exit_status(Folder::Desktop, Some(0)),
        ]);
        assert_eq!(all.outcome, ResetOutcome::AllReset);
        let lines = macos_access_reset_lines(&all);
        assert!(lines[0].contains("every folder asked"));
        assert_eq!(lines.len(), 1, "nothing declined, so no failure line");

        let partial = MacosAccessReset::from_attempts(&[
            ResetAttempt::from_exit_status(Folder::Documents, Some(0)),
            ResetAttempt::from_exit_status(Folder::Desktop, Some(1)),
            ResetAttempt::from_exit_status(Folder::Downloads, None),
        ]);
        assert_eq!(partial.outcome, ResetOutcome::Partial);
        let lines = macos_access_reset_lines(&partial);
        assert!(
            !lines[0].contains("every folder"),
            "a partial success never speaks for the set: {}",
            lines[0]
        );
        assert!(lines[0].contains("Documents"));
        assert!(!lines[0].contains("Desktop"));
        assert_eq!(lines.len(), 3, "one line per declined invocation");
        assert!(lines[1].contains("Desktop") && lines[1].contains("exit status 1"));
        assert!(lines[2].contains("Downloads") && lines[2].contains("signal"));

        let none = MacosAccessReset::from_attempts(&[ResetAttempt::from_exit_status(
            Folder::Documents,
            Some(70),
        )]);
        assert_eq!(none.outcome, ResetOutcome::NoneReset);
        assert!(macos_access_reset_lines(&none)[0].contains("cleared no saved answer"));

        let absent =
            MacosAccessReset::from_attempts(&[ResetAttempt::tool_absent(Folder::Documents)]);
        assert_eq!(absent.outcome, ResetOutcome::ToolAbsent);
        assert!(
            absent.declined.is_empty(),
            "an absent tool is not a decline"
        );

        assert_eq!(
            MacosAccessReset::from_attempts(&[]).outcome,
            ResetOutcome::NotAttempted
        );
        assert!(macos_access_reset_lines(&MacosAccessReset::from_attempts(&[])).is_empty());
    }

    /// The block is absent until the HOST publishes a posture, and the gesture
    /// arms a view is born with cannot reach the OS. This is the §3.3 guardrail
    /// that keeps a unit test — a headless-constructible `App` by definition —
    /// away from `NSWorkspace` and `tccd`.
    #[test]
    fn an_unpublished_or_unarmed_settings_view_reaches_no_os_consent_surface() {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            assert!(
                state.macos_access.is_none(),
                "nothing is published until a windowed host publishes it"
            );
            assert!(
                !state.consent_gestures.is_live(),
                "a view is born with the arms that cannot reach the OS"
            );
            assert!(!prefers_macos_access(state));
        }
        let cx = view_cx_at(1_280.0, 900.0);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            compiled
                .semantic(&UiKey::new("settings/macos-access"))
                .is_none(),
            "no card, and therefore no button, on an unpublished view"
        );

        // Even pressed directly, the gestures are inert: nothing opens and
        // nothing spawns.
        assert!(
            !ConsentGestures::inert().is_live(),
            "the default arms are the inert ones"
        );
        assert_eq!(
            (ConsentGestures::inert().open_settings)(crate::menu::PrivacyPane::FullDiskAccess),
            crate::menu::SettingsOpen::Refused
        );
        let plan = ResetPlan::new("com.example.fixture", Folder::ALL).unwrap();
        let attempts = (ConsentGestures::inert().run_reset)(&plan);
        assert_eq!(attempts.len(), Folder::ALL.len());
        assert_eq!(
            MacosAccessReset::from_attempts(&attempts).outcome,
            ResetOutcome::ToolAbsent,
            "the inert arm reports that nothing ran, never that a reset happened"
        );
    }

    /// The published block renders on Security, its every hit target is whole
    /// at each responsive width, and the route stays in words beside the button
    /// because `openURL:` cannot promise the pane scrolled to the row.
    #[test]
    fn the_published_macos_access_block_paints_whole_on_the_security_page() {
        use aterm_containment::FdaScope;
        let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        access.warmup_rows = denied_rows();
        for width in [360.0, 760.0, 1_280.0] {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Security);
                assert!(state.replace_macos_access(access.clone()));
                assert!(
                    !state.replace_macos_access(access.clone()),
                    "an unchanged posture repaints nothing"
                );
            }
            let cx = view_cx_at(width, 900.0);
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            compiled.validate_parity().unwrap();
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/macos-access"))
                    .is_some(),
                "the block is on the Security page at width {width}"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new(MACOS_ACCESS_OPEN_FDA))
                    .is_some(),
                "Open Privacy & Security… at width {width}"
            );
            for hit in &compiled.hits {
                if !hit.key.as_str().starts_with("settings/macos-access") {
                    continue;
                }
                let painted = compiled
                    .paint
                    .iter()
                    .find(|node| node.key == hit.key)
                    .expect("a macOS access action is painted");
                let delta = (painted.rect.x - hit.rect.x).abs()
                    + (painted.rect.y - hit.rect.y).abs()
                    + (painted.rect.width - hit.rect.width).abs()
                    + (painted.rect.height - hit.rect.height).abs();
                assert!(delta < 0.01, "{:?} clips at width {width}", hit.key);
                assert!(hit.rect.width > 0.0 && hit.rect.height > 0.0);
            }
        }
    }

    /// The warm-up gesture: one press records one request, a second press while
    /// a worker is live records nothing and starts nothing, and the request is
    /// consumed exactly once by the host.
    #[test]
    fn the_warm_up_gesture_latches_once_and_a_second_press_starts_no_second_worker() {
        let press = |runtime: &mut NativeRuntime, instance, view| {
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(MACOS_ACCESS_WARM_UP),
                        value: None,
                    }),
                )
                .unwrap();
        };
        use aterm_containment::FdaScope;
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(access_fixture(
                FdaState::Denied,
                DrClass::Identity,
                FdaScope::Unknown,
            ));
            state.arm_consent_gestures(ConsentGestures::confirming());
        }
        press(&mut runtime, instance, view);
        press(&mut runtime, instance, view);
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        assert_eq!(
            state.consent_warmup_requests, 1,
            "two presses are still one request; the worker walks folders in sequence"
        );
        assert!(state.take_consent_warmup_request());
        assert!(
            !state.take_consent_warmup_request(),
            "the host consumes the request exactly once"
        );

        // While a worker IS live the press is a stated no-op, and the button is
        // drawn busy rather than pretending to be idle.
        let mut live = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        live.warmup_live = true;
        state.replace_macos_access(live.clone());
        press(&mut runtime, instance, view);
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        assert_eq!(
            state.consent_warmup_requests, 0,
            "a second gesture while a worker is live starts no second worker"
        );
        assert!(
            state
                .feedback
                .as_deref()
                .is_some_and(|line| line.contains("already asking")),
            "and it says so: {:?}",
            state.feedback
        );
    }

    /// *Ask again* runs the plan through the injected arm, folds the result at
    /// its earned strength, and keeps it on the panel. With the inert arm
    /// nothing ran, and the panel says exactly that.
    #[test]
    fn ask_again_folds_the_injected_arms_result_onto_the_panel() {
        use aterm_containment::FdaScope;
        let (mut runtime, instance, view) = setup();
        let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        access.warmup_rows = denied_rows();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(access);
            state.arm_consent_gestures(ConsentGestures::confirming());
        }
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(MACOS_ACCESS_ASK_AGAIN),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        let report = state
            .macos_access
            .as_ref()
            .and_then(|access| access.reset.clone())
            .expect("the outcome is kept on the panel");
        assert_eq!(
            report.outcome,
            ResetOutcome::ToolAbsent,
            "the inert arm ran nothing and the panel reports nothing reset"
        );
        assert!(
            state
                .feedback
                .as_deref()
                .is_some_and(|line| line.contains("Nothing was changed")),
            "{:?}",
            state.feedback
        );
    }

    /// The deep-link gesture always leaves the route in words on screen,
    /// whatever the shell did with the URL — `openURL:` answers "System
    /// Settings took it", never "it scrolled to the row".
    #[test]
    fn the_deep_link_gesture_always_names_the_route_in_words() {
        use aterm_containment::FdaScope;
        for (action, words) in [
            (
                MACOS_ACCESS_OPEN_FDA,
                crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::FullDiskAccess),
            ),
            (
                MACOS_ACCESS_OPEN_FILES,
                crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::FilesAndFolders),
            ),
        ] {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Security);
                state.replace_macos_access(access_fixture(
                    FdaState::Unknown,
                    DrClass::Identity,
                    FdaScope::Unknown,
                ));
            }
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(action),
                        value: None,
                    }),
                )
                .unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            let feedback = state.feedback.as_deref().expect("feedback");
            assert!(feedback.contains(words), "{action}: {feedback}");
            let lower = feedback.to_ascii_lowercase();
            for banned in BANNED_PANEL_PHRASES {
                assert!(!lower.contains(banned), "{action}: {feedback}");
            }
        }
    }

    /// aterm never mirrors the System Settings toggle. The panel's state comes
    /// from its own probe, and one line says so — because a row that reads ON
    /// while every check silently fails is the failure worth surfacing (§1.2).
    #[test]
    fn the_panel_reports_its_own_probe_and_never_the_system_settings_toggle() {
        use aterm_containment::FdaScope;
        let copy = macos_access_copy(&access_fixture(
            FdaState::Granted,
            DrClass::Identity,
            FdaScope::Unknown,
        ));
        assert!(
            copy.observation
                .contains("never the switch in System Settings"),
            "{}",
            copy.observation
        );
        assert!(copy.probe_detail.contains("aterm's own check"));
        // A granted grant with a cdhash requirement is exactly the stale-`csreq`
        // shape: the panel still reports its own probe, and never a toggle.
        let stale = macos_access_copy(&access_fixture(
            FdaState::Granted,
            DrClass::Cdhash,
            FdaScope::Unknown,
        ));
        assert_eq!(stale.observation, copy.observation);
    }

    #[test]
    fn an_async_access_check_preserves_the_security_pages_observed_facts() {
        use aterm_containment::FdaScope;
        let mut access = access_fixture(FdaState::Unknown, DrClass::Identity, FdaScope::Unknown);
        access.probe = ProbeLabel::Pending;
        let pending = macos_access_copy(&access);
        assert!(pending.headline.contains("checking"));
        assert!(pending.probe_detail.contains("background"));
        assert!(
            pending
                .identity
                .contains("/Applications/fixture.app/Contents/MacOS/fixture")
        );
        assert!(pending.responsible.contains("1 of 2 sessions"));
        assert!(
            pending
                .services
                .iter()
                .any(|line| line.contains("not measured"))
        );

        access.fda = FdaState::Denied;
        access.probe = ProbeLabel::OpenEperm;
        let denied = macos_access_copy(&access);
        assert!(denied.headline.contains("may already be enabled"));
        assert!(!denied.headline.contains("not granted"));
        assert_eq!(denied.services, pending.services);
        assert_eq!(denied.identity, pending.identity);
        assert_eq!(denied.responsible, pending.responsible);
    }

    /// The switched-off case is spelled as a refusal to check, never as a
    /// denial — a probe that was deliberately not consulted is not a probe that
    /// answered no.
    #[test]
    fn a_switched_off_privacy_check_is_not_rendered_as_a_denial() {
        use aterm_containment::FdaScope;
        let mut access = access_fixture(FdaState::Unknown, DrClass::Identity, FdaScope::Unknown);
        access.enabled = false;
        access.probe = ProbeLabel::RefusedDisabled;
        let copy = macos_access_copy(&access);
        assert!(copy.headline.contains("not checked"), "{}", copy.headline);
        assert!(
            !copy.headline.to_ascii_lowercase().contains("denied"),
            "{}",
            copy.headline
        );
        assert!(
            copy.probe_detail.contains("switched off in aterm.toml"),
            "{}",
            copy.probe_detail
        );
    }

    /// The main thread may never wait on `tccd` without a ceiling. A child that
    /// never exits must be killed, reaped, and reported as a DECLINE — never as
    /// a success, and never as `ToolAbsent` (the tool did run).
    ///
    /// This is the 2026-08-17 hazard class: WindowServer's main thread sat in a
    /// `tccd` preflight for forty seconds and the watchdog took the whole GUI
    /// session down. `run_tccutil_reset` runs on the main thread from the
    /// Settings reducer, so its wait is bounded by construction.
    #[test]
    fn a_reset_invocation_can_never_hold_the_main_thread_open_ended() {
        let ceiling = std::time::Duration::from_millis(150);
        let mut child = std::process::Command::new("/bin/sleep")
            .arg("30")
            .spawn()
            .expect("spawn a child that will not exit on its own");

        let started = std::time::Instant::now();
        let code = wait_bounded(&mut child, ceiling);
        let waited = started.elapsed();

        assert!(
            waited < std::time::Duration::from_secs(5),
            "the bounded wait returned after {waited:?}; it must give up at the ceiling"
        );
        assert_eq!(
            code, None,
            "a killed child reports no exit code, which folds to a decline"
        );
        // The kill must also REAP: a second wait on a reaped child cannot block.
        assert!(
            !ResetAttempt::from_exit_status(Folder::Documents, code).is_reset(),
            "a timed-out invocation must never read as a successful reset"
        );
    }

    /// A child that exits promptly is reported by its real exit code — the
    /// ceiling is a ceiling, not a delay.
    #[test]
    fn a_prompt_invocation_is_reported_by_its_own_exit_code() {
        let mut ok = std::process::Command::new("/usr/bin/true")
            .spawn()
            .expect("spawn /usr/bin/true");
        assert_eq!(wait_bounded(&mut ok, RESET_INVOCATION_CEILING), Some(0));

        let mut bad = std::process::Command::new("/usr/bin/false")
            .spawn()
            .expect("spawn /usr/bin/false");
        let code = wait_bounded(&mut bad, RESET_INVOCATION_CEILING);
        assert!(matches!(code, Some(n) if n != 0), "got {code:?}");
        assert!(!ResetAttempt::from_exit_status(Folder::Desktop, code).is_reset());
    }

    /// §3.7's fence, which the design asks for and which no other file owns:
    /// `tccutil reset` is a destructive mutation of the human's privacy state
    /// and is reachable ONLY from this panel's *Ask again* button. If a program
    /// inside a session could trigger a reset it could re-arm a prompt the human
    /// already answered — a consent surface an agent controls, which is the same
    /// rule that keeps the warm-up off the verb table.
    #[test]
    fn no_control_dispatch_arm_can_reach_the_reset() {
        // The entry points that actually RUN the tool. The fence is about
        // execution, not vocabulary: `consent::tccutil_reset_command` is a PURE
        // argv builder and `control_privacy.rs` legitimately calls it to render
        // the `remediate reset=` recipe the `privacy` verb is specified to
        // print (design §5.1). Printing the recipe tells a human what to type;
        // it resets nothing. Executing it from a control surface is the thing
        // that must be impossible, so these are the tokens that matter.
        const RESET_ENTRY_POINTS: &[&str] = &["run_tccutil_reset", "wait_bounded", "ResetPlan"];
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut checked = 0usize;
        for entry in std::fs::read_dir(&dir).expect("read aterm-gui/src") {
            let path = entry.expect("dir entry").path();
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_default()
                .to_string();
            if !name.starts_with("control") || !name.ends_with(".rs") {
                continue;
            }
            checked += 1;
            let src = std::fs::read_to_string(&path).expect("read a control module");
            for token in RESET_ENTRY_POINTS {
                assert!(
                    !src.contains(token),
                    "{name} references the reset entry point `{token}`: the control \
                     surface must not be able to reset a human's privacy answers"
                );
            }
        }
        assert!(
            checked >= 2,
            "expected to scan several control*.rs modules, scanned {checked} — \
             the fence is vacuous if it matched nothing"
        );

        // And the fence must be checking something real: the control surface
        // may name the recipe (it prints it), so prove that allowance is live
        // rather than silently unused, or the test above could pass because
        // nothing anywhere touches reset at all.
        let privacy = std::fs::read_to_string(dir.join("control_privacy.rs"))
            .expect("read control_privacy.rs");
        assert!(
            privacy.contains("tccutil_reset_command"),
            "the `privacy` verb is specified to print a `remediate reset=` recipe; \
             if that call is gone, this fence is no longer proving anything"
        );
    }

    fn compile_settings_view(
        runtime: &NativeRuntime,
        instance: crate::native_app::AppInstanceId,
        view: crate::native_app::ViewId,
        cx: &ViewCx<'_>,
    ) -> crate::native_ui::CompiledUi {
        runtime
            .render(instance, view, cx)
            .expect("Settings renders")
            .compile(cx.viewport)
            .expect("Settings compiles")
    }

    /// The Home page's welcome flourish: on a roomy host the rainbow banner is
    /// present with a descriptive semantic label, decorative (no action,
    /// unfocusable), and paint-clean; ornamental chrome yields on short hosts
    /// and under Serious Mode.
    #[test]
    fn top_settings_rainbow_banner_present_and_yielding() {
        let key = UiKey::new("settings/top/rainbow");
        let (runtime, instance, view) = setup();
        let cx = view_cx_at(1_200.0, 810.0);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let node = compiled
            .semantic(&key)
            .expect("roomy Home page shows the rainbow banner");
        assert_eq!(node.label, "A rainbow arcs over the settings");
        assert!(node.action.is_none(), "the banner is pure decoration");
        assert_zero_top_paint(&compiled, "rainbow banner at 1200x810 1x");

        // A host below the fit gate keeps today's exact layout.
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 700.0));
        assert!(
            compiled.semantic(&key).is_none(),
            "short hosts must not gain the banner"
        );

        // Serious Mode hides the unapologetically playful.
        let mut serious = view_cx_at(1_200.0, 810.0);
        serious.motion = crate::native_app::ViewMotionCx {
            serious: true,
            ..crate::native_app::ViewMotionCx::default()
        };
        let compiled = compile_settings_view(&runtime, instance, view, &serious);
        assert!(
            compiled.semantic(&key).is_none(),
            "Serious Mode must not show the banner"
        );
    }

    fn assert_zero_top_paint(compiled: &crate::native_ui::CompiledUi, context: &str) {
        compiled
            .validate_parity()
            .unwrap_or_else(|error| panic!("{context}: {error:?}"));
        let audit = compiled.paint_audit_lines();
        let summary = audit.first().expect("paint audit summary");
        let failures = audit
            .iter()
            .filter(|line| line.contains("overflow=true") || line.contains("clip-truncated=true"))
            .cloned()
            .collect::<Vec<_>>();
        assert!(
            summary.contains("overflow=0") && summary.contains("clipped=0"),
            "{context}: {summary}\n{}",
            audit.join("\n")
        );
        assert!(
            failures.is_empty(),
            "{context}: renderer text overflow or clip:\n{}",
            failures.join("\n")
        );
        for node in compiled
            .semantics
            .iter()
            .filter(|node| node.action.is_some())
        {
            assert!(
                node.rect.x >= compiled.bounds.x - 0.01
                    && node.rect.y >= compiled.bounds.y - 0.01
                    && node.rect.right() <= compiled.bounds.right() + 0.01
                    && node.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                "{context}: actionable {:?} escapes {:?}: {:?}",
                node.key,
                compiled.bounds,
                node.rect
            );
        }
    }

    fn assert_picker_descendants_contained(
        compiled: &crate::native_ui::CompiledUi,
        key: &str,
        context: &str,
    ) {
        let picker = compiled
            .semantic(&UiKey::new(format!("settings/choice-picker/{key}")))
            .unwrap_or_else(|| panic!("{context}: missing picker"));
        let contains = |rect: LogicalRect| {
            rect.x >= picker.rect.x - 0.01
                && rect.y >= picker.rect.y - 0.01
                && rect.right() <= picker.rect.right() + 0.01
                && rect.bottom() <= picker.rect.bottom() + 0.01
        };
        for node in compiled.semantics.iter().filter(|node| {
            node.key.as_str().starts_with("settings/choice/")
                || matches!(
                    node.key.as_str(),
                    "settings/choice-close"
                        | "settings/choice-page-prev"
                        | "settings/choice-page-next"
                )
        }) {
            assert!(
                contains(node.rect),
                "{context}: semantic {:?} escapes picker {:?}: {:?}",
                node.key,
                picker.rect,
                node.rect
            );
        }
        for hit in compiled.hits.iter().filter(|hit| {
            hit.key.as_str().starts_with("settings/choice/")
                || matches!(
                    hit.key.as_str(),
                    "settings/choice-close"
                        | "settings/choice-page-prev"
                        | "settings/choice-page-next"
                )
        }) {
            assert!(
                contains(hit.rect),
                "{context}: hit {:?} escapes picker {:?}: {:?}",
                hit.key,
                picker.rect,
                hit.rect
            );
        }
    }

    fn assert_material_hit(compiled: &crate::native_ui::CompiledUi, key: &str, context: &str) {
        let semantic = compiled
            .semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{context}: missing semantic action {key}"));
        assert!(
            semantic.action.is_some(),
            "{context}: {key} lost its semantic action"
        );
        let hit = compiled
            .hits
            .iter()
            .find(|hit| hit.key.as_str() == key)
            .unwrap_or_else(|| panic!("{context}: missing hit region {key}"));
        assert!(
            hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
            "{context}: {key} is not a material hit target: {:?}",
            hit.rect
        );
        assert!(
            hit.rect.x >= compiled.bounds.x - 0.01
                && hit.rect.y >= compiled.bounds.y - 0.01
                && hit.rect.right() <= compiled.bounds.right() + 0.01
                && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
            "{context}: {key} hit escapes {:?}: {:?}",
            compiled.bounds,
            hit.rect
        );
    }

    fn assert_all_hits_material_and_contained(
        compiled: &crate::native_ui::CompiledUi,
        context: &str,
    ) {
        for hit in &compiled.hits {
            assert!(
                hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
                "{context}: {:?} is not a material hit target: {:?}",
                hit.key,
                hit.rect
            );
            assert!(
                hit.rect.x >= compiled.bounds.x - 0.01
                    && hit.rect.y >= compiled.bounds.y - 0.01
                    && hit.rect.right() <= compiled.bounds.right() + 0.01
                    && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                "{context}: {:?} hit escapes {:?}: {:?}",
                hit.key,
                compiled.bounds,
                hit.rect
            );
        }
    }

    fn assert_short_landscape_geometry(
        compiled: &crate::native_ui::CompiledUi,
        scale: f32,
        context: &str,
    ) {
        const WIDTH: f32 = 568.0;
        const HEIGHT: f32 = 320.0;
        compiled
            .validate_parity()
            .unwrap_or_else(|error| panic!("{context}: {error:?}"));
        for semantic in compiled
            .semantics
            .iter()
            .filter(|semantic| semantic.action.is_some())
        {
            assert!(
                semantic.rect.x >= -0.01
                    && semantic.rect.y >= -0.01
                    && semantic.rect.right() <= WIDTH + 0.01
                    && semantic.rect.bottom() <= HEIGHT + 0.01,
                "{context}: actionable semantic {:?} escapes the viewport: {:?}",
                semantic.key,
                semantic.rect
            );
            if scale >= 2.0 {
                assert!(
                    semantic.rect.height >= scaled_control_height_at_scale(2.0) - 0.01,
                    "{context}: {:?} was clipped below its 2× control allocation: {:?}",
                    semantic.key,
                    semantic.rect
                );
            }
        }
        for hit in &compiled.hits {
            let paint = compiled
                .paint
                .iter()
                .find(|paint| paint.key == hit.key)
                .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
            assert_eq!(paint.rect, hit.rect, "{context}: {:?} hit parity", hit.key);
            assert!(
                hit.rect.x >= -0.01
                    && hit.rect.y >= -0.01
                    && hit.rect.right() <= WIDTH + 0.01
                    && hit.rect.bottom() <= HEIGHT + 0.01,
                "{context}: {:?} escapes the viewport: {:?}",
                hit.key,
                hit.rect
            );
        }
    }

    fn assert_accessible_pager(
        compiled: &crate::native_ui::CompiledUi,
        key: &str,
        page: usize,
        total: usize,
        context: &str,
    ) {
        assert!(total > 1);
        let previous = compiled
            .semantic(&UiKey::new(format!("{key}/previous")))
            .unwrap_or_else(|| panic!("{context}: missing accessible Previous"));
        let next = compiled
            .semantic(&UiKey::new(format!("{key}/next")))
            .unwrap_or_else(|| panic!("{context}: missing accessible Next"));
        assert_eq!(
            previous.state.expect("pager state").enabled,
            page > 0,
            "{context}: Previous enabled state"
        );
        assert_eq!(
            next.state.expect("pager state").enabled,
            page + 1 < total,
            "{context}: Next enabled state"
        );
    }

    fn pager_total(compiled: &crate::native_ui::CompiledUi, status_key: &str) -> usize {
        compiled
            .semantic(&UiKey::new(status_key))
            .unwrap_or_else(|| panic!("missing pager status {status_key}"))
            .label
            .rsplit_once(" of ")
            .and_then(|(_, total)| total.parse::<usize>().ok())
            .unwrap_or_else(|| panic!("invalid pager status {status_key}"))
    }

    #[test]
    fn smart_title_health_is_runtime_backed_and_transport_truthful() {
        let (mut runtime, instance, view) = setup();
        let health = TitleSummaryHealth {
            state: TitleSummaryRuntimeState::Error,
            provider: crate::app_config::TitleSummaryProvider::Ollama,
            model: Some("qwen3.5:4b-q4_K_M".to_string()),
            endpoint: Some("http://127.0.0.1:11434/api/chat".to_string()),
            locality: TitleSummaryLocality::UnattestedLoopback,
            managed_install_present: false,
            model_ready: false,
            last_error: Some("managed runtime is not installed".to_string()),
            next_retry_after: Some(std::time::Duration::from_secs(9)),
            next_refresh_after: None,
            timeout: Some(std::time::Duration::from_secs(42)),
            proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Direct),
            ca_file: None,
        };
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::WindowTabs);
            assert!(state.replace_title_summary_health(health.clone()));
            assert!(!state.replace_title_summary_health(health));
        }

        let cx = view_cx();
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let label = |key: &str| {
            compiled
                .semantic(&UiKey::new(format!("settings/smart-titles/health/{key}")))
                .unwrap_or_else(|| panic!("missing Smart Titles health row {key}"))
                .label
                .clone()
        };
        assert!(label("state").contains("Needs attention"));
        assert!(label("locality").contains("not proof of local-only"));
        assert!(label("transport").contains("42s timeout"));
        assert!(label("transport").contains("direct connection (forced)"));
        assert!(label("transport").contains("TLS/CA not used"));
        assert!(label("readiness").contains("no automatic download"));
        assert!(label("readiness").contains("latest request has not confirmed model readiness"));
        assert!(label("detail").contains("managed runtime is not installed"));
        assert!(label("detail").contains("Error retry"));
        assert!(label("precedence").contains("Authored Description wins"));

        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.replace_title_summary_health(TitleSummaryHealth {
                state: TitleSummaryRuntimeState::Ready,
                provider: crate::app_config::TitleSummaryProvider::OpenAiCompatible,
                model: Some("private-model".to_string()),
                endpoint: Some("https://127.0.0.1:9443/v1/chat/completions".to_string()),
                locality: TitleSummaryLocality::UnattestedLoopback,
                managed_install_present: false,
                model_ready: true,
                last_error: None,
                next_retry_after: None,
                next_refresh_after: Some(std::time::Duration::from_secs(30)),
                timeout: Some(std::time::Duration::from_secs(20)),
                proxy_mode: Some(crate::app_config::TitleSummaryProxyMode::Direct),
                ca_file: Some("/tmp/private-model-ca.pem".to_string()),
            });
        }
        let openai = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let openai_transport = openai
            .semantic(&UiKey::new("settings/smart-titles/health/transport"))
            .unwrap()
            .label
            .clone();
        assert!(openai_transport.contains("direct connection"));
        assert!(openai_transport.contains("platform roots replaced"));
        let openai_detail = openai
            .semantic(&UiKey::new("settings/smart-titles/health/detail"))
            .unwrap()
            .label
            .clone();
        assert!(openai_detail.contains("Routine activity refresh"));

        for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
            let compact_cx = view_cx_at(width, height);
            let compact = runtime
                .render(instance, view, &compact_cx)
                .unwrap()
                .compile(compact_cx.viewport)
                .unwrap();
            let keys = if height <= 420.0 {
                vec!["state", "summary"]
            } else {
                vec![
                    "state",
                    "locality",
                    "transport",
                    "readiness",
                    "detail",
                    "precedence",
                ]
            };
            for key in keys {
                let node = compact
                    .semantic(&UiKey::new(format!("settings/smart-titles/health/{key}")))
                    .unwrap_or_else(|| panic!("{width}×{height} loses health row {key}"));
                assert!(
                    node.rect.bottom() <= compact_cx.viewport.bottom() + 0.01,
                    "{width}×{height} clips health row {key}: {:?}",
                    node.rect
                );
            }
        }
    }

