    #[test]
    fn route_activation_keeps_focus_on_a_surviving_visible_control() {
        let (mut runtime, instance, view) = setup();

        // The macOS-style desktop rail survives a route transition. Keep the
        // selected destination focused instead of moving focus to the structural
        // page Group, which is absent from the keyboard focus order.
        let desktop_key = UiKey::new("settings/nav/appearance");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::FocusChanged(Some(desktop_key.clone())),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view")
        };
        state.common.focus_visible = true;
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Appearance),
                    value: None,
                }),
            )
            .unwrap();
        let desktop = compile_settings_view(&runtime, instance, view, &view_cx());
        let desktop_control = desktop
            .semantic(&desktop_key)
            .expect("selected desktop route remains visible");
        assert!(desktop.focus_order.contains(&desktop_key));
        assert!(
            desktop_control
                .state
                .is_some_and(|state| { state.focused && state.focus_visible && state.selected })
        );

        // The compact category sheet does not survive selection. Its stable
        // successor is the toolbar's category/back button, including when the
        // user chooses the already-selected route (which must still close the
        // sheet).
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/compact-navigation"),
                    value: None,
                }),
            )
            .unwrap();
        let compact_cx = view_cx_at(600.0, 820.0);
        let sheet = compile_settings_view(&runtime, instance, view, &compact_cx);
        let sheet_close_key = UiKey::new("settings/compact-navigation-close");
        assert!(sheet.focus_order.contains(&sheet_close_key));
        assert!(
            sheet
                .semantic(&sheet_close_key)
                .and_then(|node| node.state)
                .is_some_and(|state| state.focused && state.focus_visible)
        );
        let compact_route_key = UiKey::new("settings/categories/appearance");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::FocusChanged(Some(compact_route_key)),
            )
            .unwrap();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Appearance),
                    value: None,
                }),
            )
            .unwrap();
        let compact = compile_settings_view(&runtime, instance, view, &compact_cx);
        let compact_key = UiKey::new("settings/compact-navigation");
        let compact_control = compact
            .semantic(&compact_key)
            .expect("compact route selection returns focus to the toolbar");
        assert!(compact.focus_order.contains(&compact_key));
        assert!(
            compact_control
                .state
                .is_some_and(|state| state.focused && state.focus_visible)
        );
        assert!(
            compact
                .semantic(&UiKey::new("settings/categories/page"))
                .is_none(),
            "choosing the current route must close the compact category sheet"
        );

        // Menu/control navigation has no source row to infer. The most recent
        // real breakpoint still supplies a surviving target, rather than the
        // non-focusable page Group used by the old fallback.
        let (mut external, external_instance, external_view) = setup();
        let wide_cx = view_cx();
        let _ = compile_settings_view(&external, external_instance, external_view, &wide_cx);
        external
            .dispatch(
                external_instance,
                external_view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::About),
                    value: None,
                }),
            )
            .unwrap();
        let desktop_external_key = UiKey::new("settings/nav/about");
        let desktop_external =
            compile_settings_view(&external, external_instance, external_view, &wide_cx);
        assert!(desktop_external.focus_order.contains(&desktop_external_key));
        assert_eq!(
            external
                .view_state(external_view)
                .and_then(|state| state.common().last_focus.as_ref()),
            Some(&desktop_external_key)
        );

        let _ = compile_settings_view(&external, external_instance, external_view, &compact_cx);
        external
            .dispatch(
                external_instance,
                external_view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Terminal),
                    value: None,
                }),
            )
            .unwrap();
        let compact_external =
            compile_settings_view(&external, external_instance, external_view, &compact_cx);
        assert!(compact_external.focus_order.contains(&compact_key));
        assert_eq!(
            external
                .view_state(external_view)
                .and_then(|state| state.common().last_focus.as_ref()),
            Some(&compact_key)
        );
    }

