    #[test]
    fn authored_weight_axis_survives_until_an_explicit_weight_alias_overrides_it() {
        let axis_value = |candidate: &crate::widget::SemanticFontCandidate| {
            candidate
                .variations
                .iter()
                .find(|variation| variation.tag == aterm_render::variation::WGHT_TAG)
                .map(|variation| variation.value())
        };
        let variation_only = SettingsViewState::new(&Config {
            font_variation: Some(crate::app_config::FontList(vec!["wght=450".to_string()])),
            ..Config::default()
        });
        assert_eq!(
            axis_value(&preview_font_candidate(&variation_only)),
            Some(450.0)
        );

        let explicit_alias = SettingsViewState::new(&Config {
            font_variation: Some(crate::app_config::FontList(vec!["wght=450".to_string()])),
            font_weight: Some(625),
            ..Config::default()
        });
        let candidate = preview_font_candidate(&explicit_alias);
        assert_eq!(axis_value(&candidate), Some(625.0));
        assert_eq!(
            candidate
                .variations
                .iter()
                .filter(|variation| variation.tag == aterm_render::variation::WGHT_TAG)
                .count(),
            1,
            "the explicit alias replaces rather than duplicates the axis",
        );

        let mut retained_draft = variation_only;
        retained_draft.field_inputs.insert(
            prefs::EDIT_FONT_WEIGHT.to_string(),
            crate::native_text_input::TextInputState::new("700".to_string()),
        );
        // The preview intentionally retains a draft after focus moves to a
        // sibling font field, so it must outrank the committed variation too.
        retained_draft.editing_field = Some(prefs::EDIT_FONT_FAMILY.to_string());
        assert_eq!(
            axis_value(&preview_font_candidate(&retained_draft)),
            Some(700.0)
        );

        let mut cleared_alias = SettingsViewState::new(&Config {
            font_variation: Some(crate::app_config::FontList(vec!["wght=450".to_string()])),
            font_weight: Some(625),
            ..Config::default()
        });
        cleared_alias.field_inputs.insert(
            prefs::EDIT_FONT_WEIGHT.to_string(),
            crate::native_text_input::TextInputState::new(String::new()),
        );
        assert_eq!(
            axis_value(&preview_font_candidate(&cleared_alias)),
            Some(450.0),
            "a retained blank is an authored reset and must not fall through to the raw alias",
        );
    }

    #[test]
    fn snapshot_font_lists_use_parsed_values_while_raw_toml_only_proves_presence() {
        let service = VersionedConfigService::new(
            "font_variation = [\"wght=450\", \"opsz=14\"]\n\
             fallback_fonts = [\"Alpha Mono\", \"Beta Sans\"]\n"
                .to_string(),
        )
        .unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        assert_eq!(
            state.raw_value(prefs::EDIT_FONT_VARIATION).as_deref(),
            Some("[\"wght=450\", \"opsz=14\"]"),
            "the production OCC projection is deliberately canonical TOML",
        );
        assert_eq!(
            state.raw_value(prefs::EDIT_FALLBACK_FONTS).as_deref(),
            Some("[\"Alpha Mono\", \"Beta Sans\"]")
        );

        let candidate = preview_font_candidate(&state);
        assert_eq!(candidate.fallback, ["Alpha Mono", "Beta Sans"]);
        assert_eq!(
            candidate
                .variations
                .iter()
                .find(|variation| variation.tag == aterm_render::variation::WGHT_TAG)
                .map(|variation| variation.value()),
            Some(450.0),
        );
        assert!(
            candidate
                .variations
                .iter()
                .any(|variation| variation.tag == u32::from_be_bytes(*b"opsz")
                    && variation.value() == 14.0),
            "the second array entry is parsed without TOML punctuation",
        );
        assert_eq!(candidate.variations.len(), 2);
    }

    #[test]
    fn blank_drafts_preview_reset_defaults_instead_of_stale_color_number_and_padding() {
        let mut color = SettingsViewState::new(&Config {
            foreground: Some("#112233".to_string()),
            ..Config::default()
        });
        color.route = SettingsRoute::Appearance;
        color.editing_field = Some(prefs::EDIT_FOREGROUND.to_string());
        color.field_inputs.insert(
            prefs::EDIT_FOREGROUND.to_string(),
            crate::native_text_input::TextInputState::new(String::new()),
        );
        assert_eq!(field_text(&color, prefs::EDIT_FOREGROUND, ""), "");
        assert_eq!(field_color(&color, prefs::EDIT_FOREGROUND), None);
        let host = aterm_render::Theme {
            fg: 0x00aa_bbcc,
            ..aterm_render::Theme::default()
        };
        let mut reset = SettingsViewState::new(&Config::default());
        reset.route = SettingsRoute::Appearance;
        let reset_fg = renderer_preview_spec(
            &reset,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            host,
        )
        .expect("default appearance preview")
        .terminal_theme
        .expect("terminal palette")
        .fg;
        let appearance = renderer_preview_spec(
            &color,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            host,
        )
        .expect("appearance preview");
        assert_eq!(
            appearance.terminal_theme.expect("terminal palette").fg,
            reset_fg
        );
        assert_ne!(reset_fg, 0x0011_2233, "negative control: override differs");
        color.editing_field = Some(prefs::EDIT_BACKGROUND.to_string());
        color.field_inputs.insert(
            prefs::EDIT_BACKGROUND.to_string(),
            crate::native_text_input::TextInputState::new(String::new()),
        );
        assert_eq!(field_text(&color, prefs::EDIT_FOREGROUND, ""), "");
        let after_focus_move = renderer_preview_spec(
            &color,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            host,
        )
        .expect("appearance preview after sibling focus");
        assert_eq!(
            after_focus_move
                .terminal_theme
                .expect("terminal palette")
                .fg,
            reset_fg,
            "the retained blank keeps previewing removal after focus moves",
        );

        let mut new_draft = SettingsViewState::new(&Config::default());
        new_draft.route = SettingsRoute::Appearance;
        new_draft.field_inputs.insert(
            prefs::EDIT_FOREGROUND.to_string(),
            crate::native_text_input::TextInputState::new("#345678".to_string()),
        );
        new_draft.editing_field = Some(prefs::EDIT_BACKGROUND.to_string());
        let retained = renderer_preview_spec(
            &new_draft,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            host,
        )
        .expect("appearance preview with retained new draft");
        assert_eq!(
            retained.terminal_theme.expect("terminal palette").fg,
            0x0034_5678,
            "a nonexplicit retained draft remains projected after focus moves",
        );

        let mut number = SettingsViewState::new(&Config {
            line_height: Some(1.8),
            ..Config::default()
        });
        number.route = SettingsRoute::TextFonts;
        number.editing_field = Some(prefs::EDIT_LINE_HEIGHT.to_string());
        number.field_inputs.insert(
            prefs::EDIT_LINE_HEIGHT.to_string(),
            crate::native_text_input::TextInputState::new(String::new()),
        );
        let typography = renderer_preview_spec(
            &number,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            aterm_render::Theme::default(),
        )
        .expect("typography preview");
        assert_eq!(typography.line_height, 1.0);

        let mut padding = SettingsViewState::new(&Config {
            window_padding: Some(4.0),
            window_padding_top: Some(8.0),
            ..Config::default()
        });
        assert_eq!(constrained_window_top_padding(&padding), Some((8.0, 4.0)));
        padding.field_inputs.insert(
            prefs::EDIT_WINDOW_PADDING.to_string(),
            crate::native_text_input::TextInputState::new(String::new()),
        );
        assert_eq!(
            constrained_window_top_padding(&padding),
            None,
            "a retained blank resets base padding to 12 instead of preserving the stale 4",
        );
    }

    #[test]
    fn about_copy_and_update_install_actions_emit_exact_typed_effects_and_complete() {
        let staged = update_status(true);
        let (mut runtime, instance, view) =
            setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&staged), false));
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::About),
                    value: None,
                }),
            )
            .unwrap();
        let copied = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("about/copy-build-info"),
                    value: None,
                }),
            )
            .unwrap();
        let copy_operation = copied
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::Clipboard { request, reply } => {
                    assert_eq!(
                        request,
                        &ClipboardRequest::CopyText {
                            text: crate::about::provenance_text(),
                            sensitive: false,
                        }
                    );
                    Some(reply.operation)
                }
                _ => None,
            })
            .expect("copy emits one typed clipboard request");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ClipboardFinished {
                    operation: copy_operation,
                    outcome: ClipboardOutcome::Copied,
                },
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert_eq!(state.feedback.as_deref(), Some("Build information copied"));

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        // ONE button. With a build staged it installs it.
        let relaunch = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("updates/install-now"),
                    value: None,
                }),
            )
            .unwrap();
        let relaunch_operation = relaunch
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::Update { request, reply } => {
                    assert_eq!(*request, UpdateRequest::InstallAndRelaunch);
                    Some(reply.operation)
                }
                _ => None,
            })
            .expect("relaunch emits typed updater request");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::UpdateFinished {
                    operation: relaunch_operation,
                    outcome: UpdateOutcome::Blocked {
                        reasons: vec!["two sessions are still running".to_string()],
                    },
                },
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert_eq!(
            state.feedback.as_deref(),
            Some("Before it can apply: two sessions are still running")
        );

        // …and with nothing staged the SAME button goes and looks, so the user
        // never has to know which updater stage they are in.
        let current = update_status(false);
        let (mut idle_runtime, idle_instance, idle_view) =
            setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&current), false));
        idle_runtime
            .dispatch(
                idle_instance,
                idle_view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let check = idle_runtime
            .dispatch(
                idle_instance,
                idle_view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("updates/install-now"),
                    value: None,
                }),
            )
            .unwrap();
        let check_operation = check
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::Update { request, reply } => {
                    assert_eq!(*request, UpdateRequest::Check);
                    Some(reply.operation)
                }
                _ => None,
            })
            .expect("the one button checks when nothing is staged");
        idle_runtime
            .dispatch(
                idle_instance,
                idle_view,
                AppEvent::UpdateFinished {
                    operation: check_operation,
                    outcome: UpdateOutcome::Accepted,
                },
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = idle_runtime.view_state(idle_view) else {
            panic!("Settings view")
        };
        assert_eq!(state.feedback.as_deref(), Some("Update request accepted"));
    }

    #[test]
    fn pending_config_disables_reset_and_undo_without_consuming_the_undo_token() {
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view")
        };
        state.route = SettingsRoute::Modified;
        state.last_undo = Some(77);
        state
            .raw_values
            .insert(prefs::EDIT_CURSOR_BLINK.to_string(), "false".to_string());
        state
            .legacy
            .fields
            .iter_mut()
            .find(|field| field.key == prefs::EDIT_CURSOR_BLINK)
            .unwrap()
            .seed = Some("false".to_string());
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK)),
                    value: Some(SemanticInput::Bool(true)),
                }),
            )
            .unwrap();

        let cx = view_cx();
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let reset = compiled
            .semantic(&UiKey::new(format!(
                "settings/reset/{}",
                prefs::EDIT_CURSOR_BLINK
            )))
            .expect("pending modified row retains disabled Reset semantics");
        let reset_state = reset.state.unwrap();
        assert!(!reset_state.enabled && reset_state.busy);
        assert!(compiled.semantic(&UiKey::new("settings/undo")).is_none());
        assert!(
            !runtime
                .commands(instance, view)
                .unwrap()
                .into_iter()
                .find(|command| command.id.as_str() == "settings/undo")
                .unwrap()
                .enabled
        );

        let undo = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/undo"),
                    value: None,
                }),
            )
            .unwrap();
        assert!(
            undo.effects
                .iter()
                .all(|effect| !matches!(effect, AppEffect::ConfigUndo { .. }))
        );
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert_eq!(state.last_undo, Some(77));
        assert_eq!(
            state.feedback.as_deref(),
            Some("Finish applying the current change before Undo.")
        );
    }

    #[test]
    fn wide_motion_packages_and_update_copy_has_zero_real_paint_overflow() {
        let cx = view_cx_at(1_200.0, 822.0);

        let (mut motion_runtime, motion_instance, motion_view) = setup();
        let motion_key = UiKey::new(format!("settings/control/{}", prefs::EDIT_MOTION));
        let mut motion_compiled = None;
        for page in 0..32 {
            let Some(AppViewState::Settings(state)) = motion_runtime.view_state_mut(motion_view)
            else {
                unreachable!();
            };
            state.navigate(SettingsRoute::CursorMotion);
            state.page_scroll = page;
            let compiled =
                compile_settings_view(&motion_runtime, motion_instance, motion_view, &cx);
            if compiled.semantic(&motion_key).is_some() {
                motion_compiled = Some(compiled);
                break;
            }
        }
        let motion_compiled = motion_compiled.expect("Motion control is reachable");
        let motion_semantic = motion_compiled.semantic(&motion_key).unwrap();
        // The OS's own accessibility setting has a DIFFERENT NAME per platform:
        // macOS calls it "Reduce Motion", Windows calls it "Show animations in
        // Windows". This assertion hardcoded the macOS wording, so it went red on
        // Windows the moment the per-platform copy landed. Assert against the
        // SHIPPED copy so the test tracks `prefs::motion_auto_copy` rather than
        // drifting from it.
        let (auto_value, auto_note) = prefs::motion_auto_copy(std::env::consts::OS);
        assert!(
            motion_semantic.label.contains(auto_value) || motion_semantic.label.contains(auto_note),
            "the Motion label must carry this platform's own motion copy, got {:?}",
            motion_semantic.label
        );
        let motion_audit = motion_compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("paint-text key=\"settings/control/motion\""))
            .collect::<Vec<_>>();
        assert!(
            motion_audit
                .iter()
                .all(|line| line.contains("overflow=false")),
            "{}",
            motion_audit.join("\n")
        );

        let (mut packages_runtime, packages_instance, packages_view) = setup();
        assert!(packages_runtime.replace_settings_packages(live_packages_state(None), 2));
        let Some(AppViewState::Settings(state)) = packages_runtime.view_state_mut(packages_view)
        else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
        let packages =
            compile_settings_view(&packages_runtime, packages_instance, packages_view, &cx);
        let consent = packages
            .semantic(&UiKey::new("packages/consent-note"))
            .expect("complete package consent semantics");
        // Phase 4: the switch is live — "takes effect at once", never "next launch".
        for expected in [
            "in the background",
            "takes effect at once",
            "several GB",
            "where you say yes",
            "next package check",
        ] {
            assert!(consent.label.contains(expected), "{}", consent.label);
        }
        assert!(!consent.label.contains("next launch"), "{}", consent.label);
        let consent_audit = packages
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("paint-text key=\"packages/consent-note/line/"))
            .collect::<Vec<_>>();
        assert_eq!(consent_audit.len(), 2);
        assert!(
            consent_audit
                .iter()
                .all(|line| line.contains("overflow=false")),
            "{}",
            consent_audit.join("\n")
        );

        let compact_packages_state = live_packages_state(None);
        let compact_total = packages_compact_sections(
            &compact_packages_state.projection(),
            SettingsWidth::Compact,
            0,
        );
        let (mut compact_runtime, compact_instance, compact_view) = setup();
        assert!(compact_runtime.replace_settings_packages(compact_packages_state, 2));
        let mut compact_consent = None;
        let compact_cx = view_cx_at(474.0, 658.0);
        for page in 0..compact_total {
            let Some(AppViewState::Settings(state)) = compact_runtime.view_state_mut(compact_view)
            else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Packages);
            state.page_scroll = page;
            let compiled = compile_settings_view(
                &compact_runtime,
                compact_instance,
                compact_view,
                &compact_cx,
            );
            if compiled
                .semantic(&UiKey::new("packages/consent-note"))
                .is_some()
            {
                compact_consent = Some(compiled);
                break;
            }
        }
        let compact_consent = compact_consent.expect("compact package consent page");
        let compact_semantic = compact_consent
            .semantic(&UiKey::new("packages/consent-note"))
            .unwrap();
        for expected in ["takes effect at once", "next package check", "several GB"] {
            assert!(
                compact_semantic.label.contains(expected),
                "{}",
                compact_semantic.label
            );
        }
        let compact_audit = compact_consent
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("paint-text key=\"packages/consent-note/line/"))
            .collect::<Vec<_>>();
        assert_eq!(compact_audit.len(), 2);
        assert!(
            compact_audit
                .iter()
                .all(|line| line.contains("overflow=false")),
            "{}",
            compact_audit.join("\n")
        );

        let status = update_status(false);
        let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
        let (mut update_runtime, update_instance, update_view) = setup_with_update(update_state);
        let Some(AppViewState::Settings(state)) = update_runtime.view_state_mut(update_view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::SoftwareUpdate);
        let update = compile_settings_view(&update_runtime, update_instance, update_view, &cx);
        // Every painted string the simplified Update page authors — the status
        // card, the one action, the automatic-updates switch row and its
        // caption, and the release notes — must fit the box it was measured
        // into. This replaced an audit of the retired "How aterm updates"
        // explainer, whose three headings and three details were the only copy
        // on the page dense enough to overflow.
        let update_audit = update
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("paint-text key=\"updates/"))
            .collect::<Vec<_>>();
        let update_geometry = update
            .paint
            .iter()
            .filter(|node| node.key.as_str().starts_with("updates/"))
            .map(|node| {
                format!(
                    "{} rect={:?} clip={:?}",
                    node.key.as_str(),
                    node.rect,
                    node.clip
                )
            })
            .collect::<Vec<_>>();
        assert!(
            update_audit.len() >= 5,
            "the Update page authors status, action, switch and notes copy: {update_audit:?}"
        );
        assert!(
            update_audit
                .iter()
                .all(|line| line.contains("overflow=false")),
            "{}\n{}",
            update_audit.join("\n"),
            update_geometry.join("\n")
        );
    }

    #[test]
    fn open_choice_picker_reflows_across_live_dynamic_type_changes() {
        const CHILD: &str = "ATERM_SETTINGS_PICKER_SCALE_CHILD";
        const EXACT: &str =
            "native_settings::tests::open_choice_picker_reflows_across_live_dynamic_type_changes";
        if std::env::var_os(CHILD).is_none() {
            let status = std::process::Command::new(std::env::current_exe().unwrap())
                .args(["--exact", EXACT, "--nocapture"])
                .env(CHILD, "1")
                .env("RUST_TEST_THREADS", "1")
                .status()
                .expect("launch isolated live Dynamic Type picker audit");
            assert!(status.success());
            return;
        }

        let install_scale = |text_scale| {
            crate::native_appearance::install_preferences(
                crate::native_appearance::AppearancePreferences {
                    text_scale,
                    ..crate::native_appearance::current_preferences()
                },
            );
        };
        install_scale(1.0);
        let cx = view_cx_at(286.5, 558.0);
        let (mut runtime, instance, view) = setup();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                    value: None,
                }),
            )
            .unwrap();

        let ordinary = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&ordinary, "open picker at 1×");
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        let picker = state.choice_picker.as_ref().unwrap();
        assert_eq!(picker.page_size.get(), 3);
        assert!(picker.visible_range().contains(&picker.selected));

        install_scale(2.0);
        let maximum = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&maximum, "same open picker at 2×");
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        let picker = state.choice_picker.as_ref().unwrap();
        assert_eq!(picker.page_size.get(), 1);
        assert!(picker.visible_range().contains(&picker.selected));

        install_scale(1.0);
        let expanded = compile_settings_view(&runtime, instance, view, &cx);
        assert_zero_top_paint(&expanded, "same open picker expanded back to 1×");
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        let picker = state.choice_picker.as_ref().unwrap();
        assert_eq!(picker.page_size.get(), 3);
        assert!(picker.visible_range().contains(&picker.selected));
    }

    #[test]
    fn compact_top_status_cross_product_keeps_controls_and_recovery_actions_reachable() {
        const CHILD: &str = "ATERM_SETTINGS_STATUS_DOCK_CHILD";
        const SCALE: &str = "ATERM_SETTINGS_STATUS_DOCK_SCALE";
        const EXACT: &str = "native_settings::tests::compact_top_status_cross_product_keeps_controls_and_recovery_actions_reachable";
        if std::env::var_os(CHILD).is_none() {
            for scale in ["1.0", "1.5", "2.0"] {
                let status = std::process::Command::new(std::env::current_exe().unwrap())
                    .args(["--exact", EXACT, "--nocapture"])
                    .env(CHILD, "1")
                    .env(SCALE, scale)
                    .env("RUST_TEST_THREADS", "1")
                    .status()
                    .expect("launch isolated compact status-dock audit");
                assert!(status.success(), "status-dock audit failed at {scale}×");
            }
            return;
        }

        let scale = std::env::var(SCALE).unwrap().parse::<f32>().unwrap();
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale: scale,
                ..crate::native_appearance::current_preferences()
            },
        );
        const WARNING: &str = "aterm.toml reload rejected: repair the invalid authored value before automatic reload can resume.";
        const VARIANTS: [&str; 4] = ["watcher", "ordinary", "draft", "reset"];
        const TOP_CONTROLS: [&str; TOP_SETTING_SECTIONS] = [
            prefs::EDIT_THEME,
            prefs::EDIT_WINDOW_THEME,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            prefs::EDIT_TRAIL_SOUNDS,
            SPARKLE_WORDS_KEY,
            KEYWORD_KITTIES_KEY,
        ];
        const TOP_PREVIEWS: [Option<&str>; TOP_SETTING_SECTIONS] = [
            Some("settings/top/theme/preview"),
            Some("settings/top/system-appearance/preview"),
            Some("settings/top/cursor-trail/preview"),
            None,
            None,
            None,
        ];
        let configure = |state: &mut SettingsViewState, variant: &str| {
            state.config_watch_status = Some(WARNING.to_string());
            state.feedback = None;
            state.last_undo = None;
            state.reset_all_confirmation = false;
            state.draft_discard_confirmation = false;
            state.field_inputs.clear();
            match variant {
                "watcher" => {}
                "ordinary" => {
                    state.feedback = Some("Saved. Undo is available.".to_string());
                    state.last_undo = Some(7);
                }
                "draft" => {
                    state.field_inputs.insert(
                        prefs::EDIT_FONT_FAMILY.to_string(),
                        crate::native_text_input::TextInputState::new(
                            "A retained unsaved font-family draft".to_string(),
                        ),
                    );
                }
                "reset" => {
                    state.feedback = Some("Reset all settings?".to_string());
                    state.reset_all_confirmation = true;
                }
                _ => unreachable!(),
            }
        };
        let assert_statuses = |compiled: &crate::native_ui::CompiledUi,
                               variant: &str,
                               context: &str| {
            assert_eq!(
                compiled
                    .semantics
                    .iter()
                    .filter(|node| {
                        node.key.as_str() == "settings/config-watch-status/detail"
                            && node.role == SemanticRole::Status
                    })
                    .count(),
                1,
                "{context}: one watcher live region"
            );
            assert_eq!(
                compiled
                    .semantic(&UiKey::new("settings/config-watch-status/detail"))
                    .map(|node| node.label.as_str()),
                Some(format!("Reload warning. {WARNING}").as_str()),
                "{context}: complete watcher detail"
            );
            let feedback_key = match variant {
                "watcher" => None,
                "draft" => Some("settings/draft-recovery/status"),
                "ordinary" | "reset" => Some("settings/status"),
                _ => unreachable!(),
            };
            if let Some(key) = feedback_key {
                assert_eq!(
                    compiled
                        .semantics
                        .iter()
                        .filter(|node| node.key.as_str() == key && node.role == SemanticRole::Status)
                        .count(),
                    1,
                    "{context}: one feedback live region"
                );
            }
            assert_material_hit(compiled, "settings/compact-navigation", context);
            let action_keys: &[&str] = match variant {
                "watcher" => &[],
                "ordinary" => &["settings/undo"],
                "draft" => &["settings/drafts/review", "settings/drafts/discard-all"],
                "reset" => &["settings/reset-all-cancel", "settings/reset-all-confirm"],
                _ => unreachable!(),
            };
            for key in action_keys {
                assert_material_hit(compiled, key, context);
            }
            assert_all_hits_material_and_contained(compiled, context);
            let serious = compiled
                .semantic(&UiKey::new("settings/top/serious-mode"))
                .unwrap_or_else(|| panic!("{context}: Serious Mode disclosure missing"));
            assert!(serious.label.contains("keeps every other effect off"));
            assert!(
                serious.rect.x >= compiled.bounds.x - 0.01
                    && serious.rect.y >= compiled.bounds.y - 0.01
                    && serious.rect.right() <= compiled.bounds.right() + 0.01
                    && serious.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                "{context}: Serious Mode disclosure escapes: {:?}",
                serious.rect
            );
        };

        for (viewport_width, viewport_height) in [(568.0, 320.0), (286.5, 558.0)] {
            let mut cx = view_cx_at(viewport_width, viewport_height);
            cx.motion.serious = true;
            for variant in VARIANTS {
                for (page, key) in TOP_CONTROLS.into_iter().enumerate() {
                    let (mut runtime, instance, view) = setup();
                    replace_settings_source(
                        &mut runtime,
                        view,
                        "serious_mode = true\n".to_string(),
                    );
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    configure(state, variant);
                    state.page_scroll = page;
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!(
                        "{variant} Top page {page} at {viewport_width}×{viewport_height} {scale}×"
                    );
                    assert_zero_top_paint(&compiled, &context);
                    assert_statuses(&compiled, variant, &context);
                    assert_material_hit(&compiled, &format!("settings/control/{key}"), &context);
                    if let Some(preview_key) = TOP_PREVIEWS[page] {
                        let preview = compiled
                            .semantic(&UiKey::new(preview_key))
                            .unwrap_or_else(|| panic!("{context}: missing live preview"));
                        assert!(
                            preview.rect.width > 0.0
                                && preview.rect.height > 0.0
                                && preview.rect.right() <= compiled.bounds.right() + 0.01
                                && preview.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                            "{context}: preview escapes: {:?}",
                            preview.rect
                        );
                    }
                    if scale >= 2.0 {
                        let label_key = UiKey::new(format!("settings/label/{key}"));
                        assert!(
                            compiled.semantic(&label_key).is_none(),
                            "{context}: Top visual label duplicated semantics"
                        );
                        assert!(
                            compiled.paint.iter().any(|node| node.key == label_key),
                            "{context}: Top visual label must still paint"
                        );
                        assert!(compiled.semantics.iter().any(|node| {
                            node.key.as_str().starts_with("settings/row/")
                                && node.key.as_str().ends_with(&format!("/{key}"))
                                && !node.label.is_empty()
                        }));
                    }
                }

                for key in [
                    prefs::EDIT_THEME,
                    prefs::EDIT_WINDOW_THEME,
                    prefs::EDIT_CURSOR_TRAIL_STYLE,
                ] {
                    let (mut runtime, instance, view) = setup();
                    replace_settings_source(
                        &mut runtime,
                        view,
                        "serious_mode = true\n".to_string(),
                    );
                    runtime
                        .dispatch(
                            instance,
                            view,
                            AppEvent::Action(ActionInvocation {
                                id: ActionId::new(format!("settings/set/{key}")),
                                value: None,
                            }),
                        )
                        .unwrap();
                    let (pages, page_size) = {
                        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view)
                        else {
                            unreachable!();
                        };
                        configure(state, variant);
                        configure_choice_picker_for_width(state, SettingsWidth::Compact);
                        let picker = state.choice_picker.as_ref().unwrap();
                        (
                            picker.options.len().div_ceil(picker.page_size.get()),
                            picker.page_size.get(),
                        )
                    };
                    for page in 0..pages {
                        let offset = {
                            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view)
                            else {
                                unreachable!();
                            };
                            let picker = state.choice_picker.as_mut().unwrap();
                            picker.offset.set(page * page_size);
                            picker.offset.get()
                        };
                        let compiled = compile_settings_view(&runtime, instance, view, &cx);
                        let context = format!(
                            "{variant} {key} picker {}/{pages} at {viewport_width}×{viewport_height} {scale}×",
                            page + 1
                        );
                        assert_zero_top_paint(&compiled, &context);
                        assert_statuses(&compiled, variant, &context);
                        assert_picker_descendants_contained(&compiled, key, &context);
                        assert_material_hit(&compiled, "settings/choice-close", &context);
                        assert_material_hit(
                            &compiled,
                            &format!("settings/choice/{key}/{offset}"),
                            &context,
                        );
                        if page > 0 {
                            assert_material_hit(&compiled, "settings/choice-page-prev", &context);
                        }
                        if page + 1 < pages {
                            assert_material_hit(&compiled, "settings/choice-page-next", &context);
                        }
                        let preview = compiled
                            .semantic(&UiKey::new("settings/top/choice-preview"))
                            .unwrap_or_else(|| panic!("{context}: missing picker preview"));
                        assert!(
                            preview.rect.width > 0.0
                                && preview.rect.height > 0.0
                                && preview.rect.right() <= compiled.bounds.right() + 0.01
                                && preview.rect.bottom() <= compiled.bounds.bottom() + 0.01,
                            "{context}: picker preview escapes: {:?}",
                            preview.rect
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow() {
        const CHILD: &str = "ATERM_SETTINGS_TOP_PAINT_CHILD";
        const SCALE: &str = "ATERM_SETTINGS_TOP_PAINT_SCALE";
        const EXACT: &str = "native_settings::tests::top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow";
        if std::env::var_os(CHILD).is_none() {
            for scale in ["1.0", "1.5", "2.0"] {
                let status = std::process::Command::new(std::env::current_exe().unwrap())
                    .args(["--exact", EXACT, "--nocapture"])
                    .env(CHILD, "1")
                    .env(SCALE, scale)
                    .env("RUST_TEST_THREADS", "1")
                    .status()
                    .expect("launch isolated Top Settings paint audit");
                assert!(
                    status.success(),
                    "Top Settings paint audit failed at {scale}×"
                );
            }
            return;
        }

        let scale = std::env::var(SCALE).unwrap().parse::<f32>().unwrap();
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale: scale,
                ..crate::native_appearance::current_preferences()
            },
        );
        let viewports = match scale {
            value if value < 1.25 => vec![(1_200.0, 810.0), (390.0, 558.0), (568.0, 320.0)],
            value if value < 1.75 => vec![
                (1_140.0, 810.0),
                (390.0, 558.0),
                (286.5, 558.0),
                (568.0, 320.0),
            ],
            _ => vec![
                (1_520.0, 900.0),
                (320.0, 568.0),
                (286.5, 558.0),
                (568.0, 320.0),
            ],
        };
        let quote = |value: &str| aterm_toml::Value::String(value.to_string()).to_string();
        let cases = [
            (
                prefs::EDIT_THEME,
                0_usize,
                aterm_types::scheme::builtin_names()
                    .into_iter()
                    .map(str::to_string)
                    .collect::<Vec<_>>(),
            ),
            (
                prefs::EDIT_WINDOW_THEME,
                1_usize,
                prefs::WINDOW_THEMES
                    .iter()
                    .map(|value| (*value).to_string())
                    .collect::<Vec<_>>(),
            ),
            (
                prefs::EDIT_CURSOR_TRAIL_STYLE,
                2_usize,
                prefs::CURSOR_TRAIL_STYLES
                    .iter()
                    .map(|value| (*value).to_string())
                    .collect::<Vec<_>>(),
            ),
        ];

        for (viewport_width, viewport_height) in viewports.iter().copied() {
            let cx = view_cx_at(viewport_width, viewport_height);

            // Every one of the six requested Top cards is a complete virtual
            // page on responsive hosts. Audit all of them, not only the three
            // preview-bearing choices.
            let (mut runtime, instance, view) = setup();
            for page in 0..TOP_SETTING_SECTIONS {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                assert_zero_top_paint(
                    &compiled,
                    &format!(
                        "default Top page {page} at {viewport_width}×{viewport_height} {scale}×"
                    ),
                );
            }

            // Commit every built-in value through the same authoritative
            // snapshot projection used after a real config save. The control
            // keeps the exact value in semantics while its visual label must
            // remain within the renderer's authored measure.
            for (key, page, values) in &cases {
                for value in values {
                    let (mut runtime, instance, view) = setup();
                    // THE TRAIL CASE AUTHORS ITS MASTER. Top Settings presents the
                    // trail's style and its ENABLEMENT as one honest choice, so a
                    // committed style alone cannot make the control read that style
                    // while the master is off — and the master's absent-key default
                    // is platform-split (`app_config::DEFAULT_DECORATIVE_EFFECTS`).
                    // Writing both is exactly what the picker itself writes: one
                    // patch carrying the style AND `cursor_trail = true`. The `off`
                    // style still projects "off" through this source, so the value
                    // list keeps its full span.
                    let source = if *key == prefs::EDIT_CURSOR_TRAIL_STYLE {
                        format!("cursor_trail = true\n{key} = {}\n", quote(value))
                    } else {
                        format!("{key} = {}\n", quote(value))
                    };
                    replace_settings_source(&mut runtime, view, source);
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.page_scroll = *page;
                    state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!(
                        "committed {key}={value:?} at {viewport_width}×{viewport_height} {scale}×"
                    );
                    assert_zero_top_paint(&compiled, &context);
                    let control = compiled
                        .semantic(&UiKey::new(format!("settings/control/{key}")))
                        .unwrap_or_else(|| panic!("{context}: missing committed control"));
                    assert_eq!(
                        control.value,
                        SemanticValue::Text(value.clone()),
                        "{context}: complete semantic value"
                    );
                    assert!(
                        control.label.contains(value),
                        "{context}: complete semantic label {:?}",
                        control.label
                    );
                }
            }

            // One explicit committed value per picker gives the matrix its
            // reset candidate as well as every built-in. Walk every real page
            // and prove all semantic labels survive the bounded visuals.
            for (key, _, values) in &cases {
                let current = values.first().expect("Top picker has choices");
                let (mut runtime, instance, view) = setup();
                replace_settings_source(
                    &mut runtime,
                    view,
                    format!("{key} = {}\n", quote(current)),
                );
                runtime
                    .dispatch(
                        instance,
                        view,
                        AppEvent::Action(ActionInvocation {
                            id: ActionId::new(format!("settings/set/{key}")),
                            value: None,
                        }),
                    )
                    .unwrap();
                let (pages, page_size, expected_labels) = {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                    configure_choice_picker_for_width(
                        state,
                        SettingsWidth::for_viewport(viewport_width),
                    );
                    let picker = state.choice_picker.as_ref().unwrap();
                    (
                        picker.options.len().div_ceil(picker.page_size.get()),
                        picker.page_size.get(),
                        picker
                            .options
                            .iter()
                            .map(|option| option.label.clone())
                            .collect::<BTreeSet<_>>(),
                    )
                };
                let mut seen_labels = BTreeSet::new();
                for page in 0..pages {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    let picker = state.choice_picker.as_mut().unwrap();
                    picker.offset.set(page * page_size);
                    state.common.last_focus = Some(UiKey::new(format!(
                        "settings/choice/{key}/{}",
                        picker.offset.get()
                    )));
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!(
                        "{key} picker {}/{pages} at {viewport_width}×{viewport_height} {scale}×",
                        page + 1
                    );
                    assert_zero_top_paint(&compiled, &context);
                    assert_picker_descendants_contained(&compiled, key, &context);
                    seen_labels.extend(
                        compiled
                            .semantics
                            .iter()
                            .filter(|node| {
                                node.key
                                    .as_str()
                                    .starts_with(&format!("settings/choice/{key}/"))
                            })
                            .map(|node| node.label.clone()),
                    );
                }
                assert_eq!(
                    seen_labels, expected_labels,
                    "complete {key} picker semantics"
                );
            }
        }

        // Serious Mode is a hidden projection state, not a separate route.
        // Exercise all Top pages and all visual pickers with the disclosure
        // present, including the tight feedback-owned landscape budget.
        for (viewport_width, viewport_height) in viewports
            .iter()
            .copied()
            .filter(|(width, _)| SettingsWidth::for_viewport(*width) == SettingsWidth::Compact)
        {
            let mut cx = view_cx_at(viewport_width, viewport_height);
            cx.motion.serious = true;
            let (mut runtime, instance, view) = setup();
            replace_settings_source(&mut runtime, view, "serious_mode = true\n".to_string());
            for page in 0..TOP_SETTING_SECTIONS {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = page;
                state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = format!(
                    "Serious Top page {page} at {viewport_width}×{viewport_height} {scale}×"
                );
                assert_zero_top_paint(&compiled, &context);
                let disclosure = compiled
                    .semantic(&UiKey::new("settings/top/serious-mode"))
                    .unwrap_or_else(|| panic!("{context}: missing Serious Mode disclosure"));
                assert!(disclosure.label.contains("keeps every other effect off"));
            }
            for key in [
                prefs::EDIT_THEME,
                prefs::EDIT_WINDOW_THEME,
                prefs::EDIT_CURSOR_TRAIL_STYLE,
            ] {
                let (mut runtime, instance, view) = setup();
                replace_settings_source(&mut runtime, view, "serious_mode = true\n".to_string());
                runtime
                    .dispatch(
                        instance,
                        view,
                        AppEvent::Action(ActionInvocation {
                            id: ActionId::new(format!("settings/set/{key}")),
                            value: None,
                        }),
                    )
                    .unwrap();
                let (pages, page_size) = {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.feedback = (viewport_height <= 320.0).then(|| "Saved".to_string());
                    configure_choice_picker_for_width(
                        state,
                        SettingsWidth::for_viewport(viewport_width),
                    );
                    let picker = state.choice_picker.as_ref().unwrap();
                    (
                        picker.options.len().div_ceil(picker.page_size.get()),
                        picker.page_size.get(),
                    )
                };
                for page in 0..pages {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    let picker = state.choice_picker.as_mut().unwrap();
                    picker.offset.set(page * page_size);
                    state.common.last_focus = Some(UiKey::new(format!(
                        "settings/choice/{key}/{}",
                        picker.offset.get()
                    )));
                    let compiled = compile_settings_view(&runtime, instance, view, &cx);
                    let context = format!(
                        "Serious {key} picker {}/{pages} at {viewport_width}×{viewport_height} {scale}×",
                        page + 1
                    );
                    assert_zero_top_paint(&compiled, &context);
                    assert_picker_descendants_contained(&compiled, key, &context);
                }
            }
        }

        // Platform availability chooses only one of these branches at runtime,
        // so compile every authored status directly. The parent remains the
        // complete accessibility contract while the child is bounded visual
        // copy at the narrowest real card measure.
        for reason in [
            "Saved On for macOS; audio output is unavailable on this platform.",
            "Saved Off; audio output is unavailable on this platform.",
            "On, currently silent because Cursor trail is Off.",
            "On, currently silent because trail sound volume is 0.",
            "On, currently silent while this window is unfocused.",
            "On, currently suppressed by Motion: Reduced.",
            "On, currently suppressed by system Reduce Motion.",
            "On, currently suppressed by adaptive performance mode.",
        ] {
            let compiled = UiTree::new(top_music_suppression_node(reason))
                .compile(LogicalRect::new(0.0, 0.0, 234.5, page_subtitle_height()))
                .unwrap();
            let context = format!("music status {reason:?} at {scale}×");
            assert_zero_top_paint(&compiled, &context);
            assert_eq!(
                compiled
                    .semantic(&UiKey::new("settings/top/music-effects/suppression"))
                    .unwrap()
                    .label,
                reason
            );
        }

        // The longest transient Top transaction status is also part of the
        // supported responsive state space.
        if scale >= 2.0 {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback = Some(top_effect_apply_feedback(true));
            let cx = view_cx_at(286.5, 558.0);
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(
                &compiled,
                "Serious Mode transaction feedback at 286.5×558 2×",
            );

            // Recovery/status surfaces can coexist with any route and used to
            // bypass the ordinary bounded-feedback projection. Exercise their
            // longest narrow-host states independently.
            for confirmation in [false, true] {
                let (mut runtime, instance, view) = setup();
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.field_inputs.insert(
                    prefs::EDIT_FONT_FAMILY.to_string(),
                    crate::native_text_input::TextInputState::new(
                        "A retained unsaved font-family draft".to_string(),
                    ),
                );
                state.draft_discard_confirmation = confirmation;
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                let context = if confirmation {
                    "draft discard confirmation at 286.5×558 2×"
                } else {
                    "draft recovery at 286.5×558 2×"
                };
                assert_zero_top_paint(&compiled, context);
                let status = compiled
                    .semantic(&UiKey::new("settings/draft-recovery/status"))
                    .unwrap();
                assert!(status.label.contains("unsaved Settings draft"));
                for key in ["settings/drafts/review", "settings/drafts/discard-all"] {
                    assert!(
                        compiled.semantic(&UiKey::new(key)).is_some(),
                        "{context}: {key}"
                    );
                }
            }

            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback = Some("Reset all settings?".to_string());
            state.reset_all_confirmation = true;
            let reset = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(&reset, "Reset All disclosure at 286.5×558 2×");
            assert_eq!(
                reset
                    .semantic(&UiKey::new("settings/status"))
                    .unwrap()
                    .label,
                "Reset all scalar preferences? Lists and maps stay. Custom records stay. Unknown keys stay."
            );

            let (mut runtime, instance, view) = setup();
            let warning = "aterm.toml reload rejected at /Users//example/配置/very-long-profile-name/aterm.toml: an authored value is invalid and must be repaired.";
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.config_watch_status = Some(warning.to_string());
            let watched = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(&watched, "config watcher warning at 286.5×558 2×");
            assert_eq!(
                watched
                    .semantic(&UiKey::new("settings/config-watch-status/detail"))
                    .unwrap()
                    .label,
                format!("Reload warning. {warning}")
            );
            assert_eq!(
                watched
                    .semantics
                    .iter()
                    .filter(|node| {
                        node.key
                            .as_str()
                            .starts_with("settings/config-watch-status")
                            && node.role == SemanticRole::Status
                    })
                    .count(),
                1,
                "one reload warning must produce one live status"
            );
        }

        // Dynamic names are arbitrary user data. Keep them byte-exact in the
        // semantic value while proving their UTF-8 visual projection is clean.
        if scale >= 2.0 {
            let name = "Aurora 👩‍💻 Observatory — a deliberately very long personal color theme";
            let scheme = aterm_types::scheme::builtin("Dracula").unwrap();
            let themes =
                crate::app_config::ThemeCatalog::from_schemes([(name.to_string(), scheme)]);
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            **state = SettingsViewState::new(&Config {
                theme: Some(name.to_string()),
                ..Config::default()
            });
            let mut assets = (*state.assets).clone();
            assets.themes = themes;
            state.assets = Arc::new(assets);
            state.page_scroll = 0;
            let cx = view_cx_at(286.5, 558.0);
            let committed = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(&committed, "long Unicode committed theme");
            let control = committed
                .semantic(&UiKey::new(format!(
                    "settings/control/{}",
                    prefs::EDIT_THEME
                )))
                .unwrap();
            assert_eq!(control.value, SemanticValue::Text(name.to_string()));
            assert!(control.label.contains(name));
            assert!(committed.paint_audit_lines().iter().any(|line| {
                line.contains(&format!("key=\"settings/control/{}\"", prefs::EDIT_THEME))
                    && line.contains('…')
                    && line.contains("overflow=false")
            }));

            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                        value: None,
                    }),
                )
                .unwrap();
            let index = match runtime.view_state_mut(view) {
                Some(AppViewState::Settings(state)) => {
                    let picker = state.choice_picker.as_mut().unwrap();
                    let index = picker
                        .options
                        .iter()
                        .position(|option| option.value.as_deref() == Some(name))
                        .unwrap();
                    let page_size = picker.page_size.get();
                    picker.offset.set((index / page_size) * page_size);
                    state.common.last_focus = Some(UiKey::new(format!(
                        "settings/choice/{}/{index}",
                        prefs::EDIT_THEME
                    )));
                    index
                }
                _ => unreachable!(),
            };
            let picker = compile_settings_view(&runtime, instance, view, &cx);
            assert_zero_top_paint(&picker, "long Unicode theme picker");
            let option = picker
                .semantic(&UiKey::new(format!(
                    "settings/choice/{}/{index}",
                    prefs::EDIT_THEME
                )))
                .unwrap();
            assert_eq!(option.label, name);
            assert_picker_descendants_contained(
                &picker,
                prefs::EDIT_THEME,
                "long Unicode theme picker",
            );
        }
    }

    #[test]
    fn top_settings_is_default_native_page_with_requested_controls_and_previews() {
        let (runtime, instance, view) = setup();
        let cx = view_cx_at(1_200.0, 820.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        let overflow = compiled
            .paint_audit_lines()
            .into_iter()
            .filter(|line| line.contains("overflow=true"))
            .collect::<Vec<_>>();
        assert!(
            overflow.is_empty(),
            "wide Top Settings text must fit its authored bounds:\n{}",
            overflow.join("\n")
        );

        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert_eq!(state.route, SettingsRoute::Home);
        assert_eq!(state.route.label(), "Top Settings");
        for key in [
            prefs::EDIT_THEME,
            prefs::EDIT_WINDOW_THEME,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            prefs::EDIT_TRAIL_SOUNDS,
            SPARKLE_WORDS_KEY,
            KEYWORD_KITTIES_KEY,
        ] {
            assert!(
                compiled
                    .semantic(&UiKey::new(format!("settings/control/{key}")))
                    .is_some(),
                "Top Settings exposes {key}"
            );
        }
        for key in [
            "settings/top/theme/preview",
            "settings/top/cursor-trail/preview",
        ] {
            assert!(compiled.semantic(&UiKey::new(key)).is_some(), "{key}");
        }
        assert!(
            compiled
                .semantic(&UiKey::new("settings/home/hero"))
                .is_none(),
            "the removed marketing hero is not in the native tree"
        );

        let medium_cx = view_cx_at(900.0, 820.0);
        let medium = runtime
            .render(instance, view, &medium_cx)
            .unwrap()
            .compile(medium_cx.viewport)
            .unwrap();
        for key in [
            prefs::EDIT_THEME,
            prefs::EDIT_WINDOW_THEME,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            prefs::EDIT_TRAIL_SOUNDS,
            SPARKLE_WORDS_KEY,
            KEYWORD_KITTIES_KEY,
        ] {
            assert!(
                medium
                    .semantic(&UiKey::new(format!("settings/control/{key}")))
                    .is_some(),
                "ordinary macOS-sized Top Settings exposes {key}"
            );
        }
        let manual = compiled
            .hits
            .iter()
            .find(|hit| hit.key == UiKey::new("settings/nav/manual"))
            .expect("Manual is a first-class native destination");
        assert_eq!(manual.action.as_str(), "settings/manual/open");
    }

    #[test]
    fn compact_category_sheet_reaches_every_settings_route() {
        let (mut runtime, instance, view) = setup();
        let cx = view_cx_at(390.0, 568.0);
        let initial = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        assert!(
            initial
                .semantic(&UiKey::new("settings/compact-navigation"))
                .is_some()
        );
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/compact-navigation"),
                    value: None,
                }),
            )
            .unwrap();

        let mut seen = BTreeSet::new();
        for _ in 0..SettingsRoute::ALL.len() {
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            compiled.validate_parity().unwrap();
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/navigation"))
                    .is_none()
            );
            for route in SettingsRoute::ALL {
                let key = UiKey::new(format!("settings/categories{}", route.path()));
                if let Some(node) = compiled.semantic(&key) {
                    assert!(node.rect.bottom() <= cx.viewport.bottom() + 0.01);
                    let hit = compiled
                        .hits
                        .iter()
                        .find(|hit| hit.key == key)
                        .expect("visible category has a native hit target");
                    assert_eq!(hit.action, route_action(route));
                    seen.insert(route.path());
                }
            }
            let Some(next) = compiled
                .hits
                .iter()
                .find(|hit| hit.action.as_str() == "settings/page-down")
                .map(|hit| hit.action.clone())
            else {
                break;
            };
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: next,
                        value: None,
                    }),
                )
                .unwrap();
        }
        assert_eq!(seen.len(), SettingsRoute::ALL.len());
    }

    #[test]
    fn top_keyword_toys_and_cursor_trail_emit_complete_runtime_patches() {
        let (mut runtime, instance, view) = setup();
        let toy = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{SPARKLE_WORDS_KEY}")),
                    value: Some(SemanticInput::Bool(false)),
                }),
            )
            .unwrap();
        let toy_patch = toy
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch),
                _ => None,
            })
            .expect("toy toggle emits one typed config patch");
        assert_eq!(
            toy_patch
                .edits
                .iter()
                .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
                .collect::<Vec<_>>(),
            [
                (SPARKLE_MASTER_KEY, None),
                (SPARKLE_WORDS_KEY, Some("false")),
                (KEYWORD_KITTIES_KEY, None),
            ]
        );

        let legacy_service =
            VersionedConfigService::new("[sparkle_words]\nenabled = false\n".to_string()).unwrap();
        let legacy = SettingsViewState::from_snapshot(&legacy_service.snapshot()).unwrap();
        assert!(legacy.is_explicit(SPARKLE_WORDS_KEY));
        assert!(legacy.is_explicit(KEYWORD_KITTIES_KEY));
        assert!(!top_projected_toy_value(&legacy, SPARKLE_WORDS_KEY));
        assert!(!top_projected_toy_value(&legacy, KEYWORD_KITTIES_KEY));

        let (mut runtime, instance, view) = setup();
        let trail = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_TRAIL_STYLE)),
                    value: Some(SemanticInput::Text("off".to_string())),
                }),
            )
            .unwrap();
        let trail_patch = trail
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch),
                _ => None,
            })
            .expect("trail choice emits one typed config patch");
        assert_eq!(
            trail_patch
                .edits
                .iter()
                .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
                .collect::<Vec<_>>(),
            [
                (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("off")),
                (prefs::EDIT_CURSOR_TRAIL, Some("false")),
            ]
        );
    }

    #[test]
    fn top_effect_controls_truthfully_escape_the_serious_mode_override() {
        fn projection(state: &SettingsViewState) -> (String, bool, bool, bool) {
            (
                top_projected_trail_value(state),
                top_projected_music_value(state),
                top_projected_toy_value(state, SPARKLE_WORDS_KEY),
                top_projected_toy_value(state, KEYWORD_KITTIES_KEY),
            )
        }

        fn dispatch_patch(
            source: &str,
            key: &str,
            value: SemanticInput,
        ) -> (VersionedConfigService, ConfigPatch) {
            let service = VersionedConfigService::new(source.to_string()).unwrap();
            let before = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
            assert!(field_bool(&before, prefs::EDIT_SERIOUS_MODE, false));
            assert_eq!(
                projection(&before),
                ("off".to_string(), false, false, false),
                "Serious Mode must suppress the complete product projection"
            );

            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                panic!("Settings view")
            };
            **state = before;
            let outcome = runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(format!("settings/set/{key}")),
                        value: Some(value),
                    }),
                )
                .unwrap();
            let patch = outcome
                .effects
                .iter()
                .find_map(|effect| match effect {
                    AppEffect::ConfigPatch { patch, .. } => Some(patch.clone()),
                    _ => None,
                })
                .expect("one atomic Top Settings patch");
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                unreachable!()
            };
            assert_eq!(
                state.feedback.as_deref(),
                Some("Applying… Serious Mode will turn off; other effects stay off.")
            );
            let unique = patch
                .edits
                .iter()
                .map(|edit| edit.key.as_str())
                .collect::<BTreeSet<_>>();
            assert_eq!(unique.len(), patch.edits.len(), "patch keys are unique");
            for edit in &patch.edits {
                assert_eq!(
                    edit.expected,
                    ExpectedConfigValue::Exact(
                        SettingsViewState::from_snapshot(&service.snapshot())
                            .unwrap()
                            .raw_value(&edit.key)
                    ),
                    "{} keeps an exact OCC precondition",
                    edit.key
                );
            }
            (service, patch)
        }

        fn assert_transition(
            source: &str,
            key: &str,
            value: SemanticInput,
            expected_patch: &[(&str, Option<&str>)],
            expected_projection: (&str, bool, bool, bool),
        ) -> SettingsViewState {
            let (mut service, patch) = dispatch_patch(source, key, value);
            assert_eq!(
                patch
                    .edits
                    .iter()
                    .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
                    .collect::<Vec<_>>(),
                expected_patch
            );
            let (snapshot, _) = apply_real_config_patch(&mut service, &patch);
            let after = SettingsViewState::from_snapshot(&snapshot).unwrap();
            assert!(!field_bool(&after, prefs::EDIT_SERIOUS_MODE, false));
            assert_eq!(
                projection(&after),
                (
                    expected_projection.0.to_string(),
                    expected_projection.1,
                    expected_projection.2,
                    expected_projection.3,
                ),
                "only the selected Top Settings effect may change"
            );
            after
        }

        // THE SIBLING-PIN IS PLATFORM-CONDITIONAL, and that is the law working
        // rather than an exception to it. Escaping Serious Mode writes an explicit
        // `false` for every sibling that would otherwise spring back to life on the
        // way out. Where `cursor_trail` is un-authored AND its platform default is
        // already OFF (`app_config::DEFAULT_DECORATIVE_EFFECTS`, i.e. Windows), the
        // trail springs back to nothing — so there is nothing to pin and the honest
        // patch leaves the key unwritten. "Only the selected effect may change" is
        // the invariant under test; the edit list is its consequence, and the
        // PROJECTION assertions below are identical on every host.
        //
        // Only a `false` PIN is conditional. An edit that turns the trail ON is the
        // user's own selection and appears everywhere.
        fn expect(
            edits: &[(&'static str, Option<&'static str>)],
        ) -> Vec<(&'static str, Option<&'static str>)> {
            edits
                .iter()
                .copied()
                .filter(|(key, value)| {
                    crate::app_config::DEFAULT_DECORATIVE_EFFECTS
                        || !(*key == prefs::EDIT_CURSOR_TRAIL && *value == Some("false"))
                })
                .collect()
        }

        let defaulted = "serious_mode = true\n";
        assert_transition(
            defaulted,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            SemanticInput::Text("water".to_string()),
            &expect(&[
                (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("water")),
                (prefs::EDIT_CURSOR_TRAIL, Some("true")),
                (prefs::EDIT_TRAIL_SOUNDS, Some("false")),
                (SPARKLE_WORDS_KEY, Some("false")),
                (KEYWORD_KITTIES_KEY, Some("false")),
                (prefs::EDIT_SERIOUS_MODE, None),
            ]),
            ("water", false, false, false),
        );
        assert_transition(
            defaulted,
            prefs::EDIT_TRAIL_SOUNDS,
            SemanticInput::Bool(true),
            &expect(&[
                (prefs::EDIT_TRAIL_SOUNDS, None),
                (prefs::EDIT_CURSOR_TRAIL, Some("false")),
                (SPARKLE_WORDS_KEY, Some("false")),
                (KEYWORD_KITTIES_KEY, Some("false")),
                (prefs::EDIT_SERIOUS_MODE, None),
            ]),
            ("off", true, false, false),
        );
        assert_transition(
            defaulted,
            SPARKLE_WORDS_KEY,
            SemanticInput::Bool(true),
            &expect(&[
                (SPARKLE_MASTER_KEY, None),
                (SPARKLE_WORDS_KEY, None),
                (KEYWORD_KITTIES_KEY, Some("false")),
                (prefs::EDIT_CURSOR_TRAIL, Some("false")),
                (prefs::EDIT_TRAIL_SOUNDS, Some("false")),
                (prefs::EDIT_SERIOUS_MODE, None),
            ]),
            ("off", false, true, false),
        );
        assert_transition(
            defaulted,
            KEYWORD_KITTIES_KEY,
            SemanticInput::Bool(true),
            &expect(&[
                (SPARKLE_MASTER_KEY, None),
                (SPARKLE_WORDS_KEY, Some("false")),
                (KEYWORD_KITTIES_KEY, None),
                (prefs::EDIT_CURSOR_TRAIL, Some("false")),
                (prefs::EDIT_TRAIL_SOUNDS, Some("false")),
                (prefs::EDIT_SERIOUS_MODE, None),
            ]),
            ("off", false, false, true),
        );

        let explicitly_suppressed = "serious_mode = true\n\
             cursor_trail = false\n\
             cursor_trail_style = \"phaser\"\n\
             trail_sounds = false\n\
             [sparkle_words]\n\
             enabled = false\n\
             [sparkle_words.profanity]\n\
             enabled = true\n\
             [sparkle_words.feline]\n\
             enabled = true\n";
        let after = assert_transition(
            explicitly_suppressed,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            SemanticInput::Text("water".to_string()),
            &[
                (prefs::EDIT_CURSOR_TRAIL_STYLE, Some("water")),
                (prefs::EDIT_CURSOR_TRAIL, Some("true")),
                (prefs::EDIT_SERIOUS_MODE, None),
            ],
            ("water", false, false, false),
        );
        assert_eq!(
            after.raw_value(SPARKLE_MASTER_KEY).as_deref(),
            Some("false"),
            "an explicit shared-off toy policy needs no rewrite"
        );
        assert_eq!(
            after.raw_value(prefs::EDIT_TRAIL_SOUNDS).as_deref(),
            Some("false"),
            "an explicit sibling override is preserved byte-semantically"
        );
    }

