    #[test]
    fn ordinary_advanced_effect_rows_disclose_saved_on_but_runtime_suppressed() {
        let service = VersionedConfigService::new(
            "serious_mode = true\nstream_fade = true\n[matrix_rain]\nenabled = true\n".to_string(),
        )
        .unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        for (key, route) in [
            (prefs::EDIT_STREAM_FADE, SettingsRoute::CursorMotion),
            (prefs::EDIT_MATRIX_RAIN_ENABLED, SettingsRoute::Appearance),
        ] {
            assert_eq!(route.section(), Some(prefs::section_of(key)));
            let (index, field) = state
                .legacy
                .fields
                .iter()
                .enumerate()
                .find(|(_, field)| field.key == key)
                .unwrap();
            let compiled = UiTree::new(setting_row(
                &state,
                index,
                field,
                false,
                false,
                SettingsWidth::Wide,
            ))
            .compile(LogicalRect::new(0.0, 0.0, 900.0, 90.0))
            .unwrap();
            let control = compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap();
            assert_eq!(
                control.value,
                SemanticValue::Bool(true),
                "saved value remains On"
            );
            assert!(
                control
                    .label
                    .contains("Currently inactive because Serious Mode suppresses this effect"),
                "the ordinary Advanced control exposes its effective Off state: {key}"
            );
            let label = compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .unwrap();
            assert!(label.label.contains("Inactive · Serious Mode"));
        }
        let stream_note = prefs::group_footnote("Stream fade").unwrap();
        for cause in [
            "Reduce Motion",
            "unfocused",
            "full-screen apps",
            "scrollback",
            "input",
            "Serious Mode",
        ] {
            assert!(
                stream_note.contains(cause),
                "missing stream-fade bypass: {cause}"
            );
        }
        let rain_note = prefs::group_footnote("Matrix rain").unwrap();
        assert!(rain_note.contains("Serious Mode"));
        assert!(rain_note.contains("Reduce Motion"));
    }

    #[test]
    fn modified_groups_manual_structures_preserves_unknowns_and_only_resets_registered_paths() {
        let source = r#"theme = "Nord"
[packages]
exclude = ["ay"]
[keybindings]
"cmd+shift+t" = "new_tab"
[[sparkle_words.custom]]
words = ["ultrathink"]
[future_feature]
enabled = true
"#;
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        let snapshot = service.snapshot();
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::Modified);
        let overrides = authored_manual_overrides(state);
        assert_eq!(
            overrides
                .iter()
                .map(|entry| entry.key.as_str())
                .collect::<Vec<_>>(),
            [
                "future_feature.enabled",
                "keybindings",
                "packages.exclude",
                "sparkle_words.custom",
            ],
            "opaque maps/structured lists are one override; native/table parents are not duplicates"
        );
        assert!(
            overrides
                .iter()
                .find(|entry| entry.key == "future_feature.enabled")
                .is_some_and(|entry| !entry.known && !entry.reset_safe)
        );
        assert!(
            overrides
                .iter()
                .find(|entry| entry.key == "keybindings")
                .is_some_and(|entry| entry.known && entry.reset_safe),
            "the exact known map is safely reset as a unit, never as guessed child paths"
        );
        state.page_scroll = overrides
            .iter()
            .position(|entry| entry.key == "keybindings")
            .unwrap();

        let cx = view_cx_at(1_080.0, 720.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new("settings/modified/manual-overrides"))
                .is_some()
        );
        assert!(
            compiled
                .semantic(&UiKey::new("settings/modified/manual/reset/keybindings"))
                .is_some(),
            "known opaque maps have an exact Reset action"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(
                    "settings/modified/manual/reset/future-feature-enabled"
                ))
                .is_none(),
            "unknown forward-compatible paths never gain a destructive action"
        );

        let expected_package = snapshot.values().unwrap().get("packages.exclude").cloned();
        let package_index = manual_reset_schema_index("packages.exclude").unwrap();
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/reset-manual/{package_index}")),
                    value: None,
                }),
            )
            .unwrap();
        let patch = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch),
                _ => None,
            })
            .expect("registered Manual reset emits one CAS patch");
        assert_eq!(patch.edits.len(), 1);
        assert_eq!(patch.edits[0].key, "packages.exclude");
        assert_eq!(patch.edits[0].value, None);
        assert_eq!(
            patch.edits[0].expected,
            ExpectedConfigValue::Exact(expected_package)
        );
    }

    #[test]
    fn modified_and_reset_keep_literal_dotted_keys_distinct_from_nested_paths() {
        let source = r#""packages.exclude" = ["literal"]

[packages]
exclude = ["nested"]
"#;
        let mut service = VersionedConfigService::new(source.to_string()).unwrap();
        let snapshot = service.snapshot();
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::Modified);
        let overrides = authored_manual_overrides(state);
        let literal = overrides
            .iter()
            .find(|entry| entry.key == r#""packages.exclude""#)
            .expect("the literal dotted segment remains visible in Modified");
        assert!(!literal.known && !literal.reset_safe);
        assert!(
            overrides
                .iter()
                .find(|entry| entry.key == "packages.exclude")
                .is_some_and(|entry| entry.known && entry.reset_safe),
            "the independently authored nested path retains its exact schema action"
        );

        state.page_scroll = overrides
            .iter()
            .position(|entry| entry.key == r#""packages.exclude""#)
            .unwrap();
        let cx = view_cx_at(1_080.0, 720.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled.validate_parity().unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new(format!(
                    "settings/modified/manual/reset/{}",
                    key_fragment(r#""packages.exclude""#)
                )))
                .is_none(),
            "an unknown literal segment must never gain a destructive action"
        );

        let package_index = manual_reset_schema_index("packages.exclude").unwrap();
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/reset-manual/{package_index}")),
                    value: None,
                }),
            )
            .unwrap();
        let patch = outcome
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch),
                _ => None,
            })
            .expect("the registered nested path retains its exact Reset action");
        assert_eq!(patch.edits.len(), 1);
        assert_eq!(patch.edits[0].key, "packages.exclude");
        let (after, _) = apply_real_config_patch(&mut service, patch);
        let values = after.values().unwrap();
        assert!(!values.contains_key("packages.exclude"));
        assert_eq!(
            values.get(r#""packages.exclude""#).map(String::as_str),
            Some(r#"["literal"]"#),
            "resetting the nested path cannot remove the lookalike literal segment"
        );
    }

    #[test]
    fn authored_lists_stay_lossless_in_manual_and_survive_reset_all() {
        let source = r#"shell_args = ["-c", "printf a,b"]
fallback_fonts = ["A, B", "Apple Symbols"]
theme = "Nord"
"#;
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        let snapshot = service.snapshot();
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::Modified);
        let overrides = authored_manual_overrides(state);
        assert!(
            overrides
                .iter()
                .any(|entry| entry.key == prefs::EDIT_SHELL_ARGS)
        );
        assert!(
            overrides
                .iter()
                .any(|entry| entry.key == prefs::EDIT_FALLBACK_FONTS)
        );
        assert_eq!(
            state.raw_value(prefs::EDIT_SHELL_ARGS).as_deref(),
            Some("[\"-c\", \"printf a,b\"]")
        );
        assert!(!settings_field_is_visible(
            prefs::EDIT_SHELL_ARGS,
            true,
            false
        ));

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all"),
                    value: None,
                }),
            )
            .unwrap();
        let confirmed = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/reset-all-confirm"),
                    value: None,
                }),
            )
            .unwrap();
        let patch = confirmed
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { patch, .. } => Some(patch),
                _ => None,
            })
            .unwrap();
        assert!(patch.edits.iter().any(|edit| edit.key == prefs::EDIT_THEME));
        assert!(
            patch
                .edits
                .iter()
                .all(|edit| !prefs::manual_only_key(&edit.key))
        );
    }

    #[test]
    fn modified_manual_previews_are_typed_bounded_and_do_not_echo_unknown_values() {
        let secret = "do-not-render-this-forward-compatible-secret";
        let source = format!(
            "shell_args = [\"-c\", \"printf a,b\"]\nfuture_secret = \"{secret}\"\n[keybindings]\n\"cmd+t\" = \"new_tab\"\n\"cmd+w\" = \"close_tab\"\n"
        );
        let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
        let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        let overrides = authored_manual_overrides(&state);

        let list = overrides
            .iter()
            .find(|entry| entry.key == prefs::EDIT_SHELL_ARGS)
            .expect("known Manual list override");
        assert_eq!(list.preview, "Current list · 2 values");
        let map = overrides
            .iter()
            .find(|entry| entry.key == "keybindings")
            .expect("known Manual map override");
        assert_eq!(map.preview, "Current map · 2 entries");
        let unknown = overrides
            .iter()
            .find(|entry| entry.key == "future_secret")
            .expect("forward-compatible override");
        assert!(unknown.preview.contains("forward-compatible value"));
        assert!(unknown.preview.contains("Open Manual to inspect"));
        assert!(!unknown.preview.contains(secret));

        let ordinal = overrides
            .iter()
            .position(|entry| entry.key == unknown.key)
            .unwrap();
        let compact = UiTree::new(manual_override_node(
            &state,
            unknown,
            ordinal,
            overrides.len(),
            SettingsWidth::Compact,
        ))
        .compile(LogicalRect::new(0.0, 0.0, 340.0, 280.0))
        .unwrap();
        let value_key = UiKey::new(format!(
            "settings/modified/manual/value/{}",
            key_fragment(&unknown.key)
        ));
        assert_eq!(compact.semantic(&value_key).unwrap().label, unknown.preview);
        assert!(
            compact
                .semantics
                .iter()
                .all(|node| !node.label.contains(secret)),
            "Modified semantics must not leak an unknown authored value"
        );

        let (landscape_node, height) =
            manual_override_landscape_node(&state, unknown, ordinal, overrides.len());
        let landscape = UiTree::new(landscape_node)
            .compile(LogicalRect::new(0.0, 0.0, 900.0, height))
            .unwrap();
        assert_eq!(
            landscape.semantic(&value_key).unwrap().label,
            unknown.preview
        );
        assert!(
            landscape
                .semantics
                .iter()
                .all(|node| !node.label.contains(secret))
        );

        let long = "x".repeat(MANUAL_OVERRIDE_VALUE_PREVIEW_GRAPHEMES + 20);
        let bounded = bounded_manual_override_value(&long);
        assert!(bounded.ends_with('…'));
        assert_eq!(
            bounded.chars().count(),
            MANUAL_OVERRIDE_VALUE_PREVIEW_GRAPHEMES + 1
        );
        assert_eq!(
            bounded_manual_override_value("alpha\n\tbeta\0"),
            "alpha beta"
        );
        for cluster in ["e\u{301}", "👩\u{200d}💻", "🇺🇳"] {
            let exact = format!("{}{cluster}", "x".repeat(71));
            assert_eq!(bounded_manual_override_value(&exact), exact);
            assert_eq!(exact.graphemes().count(), 72);
            let overflow = format!("{exact}y");
            assert_eq!(
                bounded_manual_override_value(&overflow),
                format!("{exact}…"),
                "72-boundary must keep {cluster:?} whole"
            );
        }

        // The 73rd normalized visible cluster proves truncation immediately;
        // the multi-megabyte ASCII/whitespace tail is never normalized or
        // retained merely to paint this 72-cluster glance.
        let mut huge = "q".repeat(73);
        huge.push_str(&" \n".repeat(1_100_000));
        assert!(huge.len() > 2 * 1024 * 1024);
        assert_eq!(
            bounded_manual_override_value(&huge),
            format!("{}…", "q".repeat(72))
        );
    }

    #[test]
    fn modified_identifies_retired_bottom_hud_keys_without_offering_reset() {
        let source = concat!(
            "show_hud = true\n",
            "show_resources_hud = false\n",
            "show_engine_hud = true\n",
        );
        let snapshot = VersionedConfigService::new(source.to_string())
            .unwrap()
            .snapshot();
        let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::Modified);
        let overrides = authored_manual_overrides(&state);

        for key in ["show_hud", "show_resources_hud", "show_engine_hud"] {
            let ordinal = overrides
                .iter()
                .position(|entry| entry.key == key)
                .unwrap_or_else(|| panic!("retired {key} remains visible in Modified"));
            let retired = &overrides[ordinal];
            assert_eq!(retired.label, "Retired Bottom HUD setting");
            assert_eq!(retired.preview, "No effect · Open Manual…");
            assert!(retired.known);
            assert!(!retired.reset_safe, "retired keys are preserve-only");

            let compiled = UiTree::new(manual_override_node(
                &state,
                retired,
                ordinal,
                overrides.len(),
                SettingsWidth::Wide,
            ))
            .compile(LogicalRect::new(0.0, 0.0, 900.0, 320.0))
            .unwrap();
            let fragment = key_fragment(key);
            assert_eq!(
                compiled
                    .semantic(&UiKey::new(format!(
                        "settings/modified/manual/value/{fragment}"
                    )))
                    .map(|node| node.label.as_str()),
                Some("No effect · Open Manual…")
            );
            assert!(
                compiled
                    .semantic(&UiKey::new(format!(
                        "settings/modified/manual/reset/{fragment}"
                    )))
                    .is_none(),
                "retired {key} must not gain a destructive Reset action"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/modified/manual/open"))
                    .is_some(),
                "Manual remains the explicit preservation/editing path"
            );
        }
    }

    #[test]
    fn retired_keyword_kitty_controls_are_manual_only_and_name_no_effect() {
        let source = concat!(
            "[sparkle_words.feline]\n",
            "idle = true\n",
            "gaze = false\n",
            "color = \"#44ccff\"\n",
            "intensity = 0.7\n",
        );
        let snapshot = VersionedConfigService::new(source.to_string())
            .unwrap()
            .snapshot();
        let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::Modified);
        let overrides = authored_manual_overrides(&state);

        for key in [
            "sparkle_words.feline.idle",
            "sparkle_words.feline.gaze",
            "sparkle_words.feline.color",
            "sparkle_words.feline.intensity",
        ] {
            assert!(native_compatibility_only_key(key));
            let registered = state
                .legacy
                .fields
                .iter()
                .find(|field| field.key == key)
                .unwrap_or_else(|| panic!("retired {key} remains registered for Manual metadata"));
            assert!(
                !settings_field_is_visible(registered.key, true, false),
                "retired {key} stays in the registry but must not render a native control"
            );
            let (ordinal, authored) = overrides
                .iter()
                .enumerate()
                .find(|(_, authored)| authored.key == key)
                .unwrap_or_else(|| panic!("retired {key} remains reachable in Modified"));
            assert!(authored.label.starts_with("Retired Keyword Kitty"));
            assert_eq!(authored.preview, "No effect · Open Manual…");
            assert!(authored.known);
            assert!(!authored.reset_safe);

            let compiled = UiTree::new(manual_override_node(
                &state,
                authored,
                ordinal,
                overrides.len(),
                SettingsWidth::Wide,
            ))
            .compile(LogicalRect::new(0.0, 0.0, 900.0, 320.0))
            .unwrap();
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/modified/manual/open"))
                    .is_some(),
                "Manual is the explicit preservation/editing path for {key}"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new(format!(
                        "settings/modified/manual/reset/{}",
                        key_fragment(key)
                    )))
                    .is_none(),
                "retired {key} is preserve-only"
            );
        }
    }

    #[test]
    fn modified_pages_every_manual_override_at_normal_and_large_text() {
        const CHILD: &str = "ATERM_MODIFIED_MANUAL_PAGES_CHILD";
        const SCALE: &str = "ATERM_MODIFIED_MANUAL_PAGES_SCALE";
        const EXACT: &str =
            "native_settings::tests::modified_pages_every_manual_override_at_normal_and_large_text";
        if std::env::var_os(CHILD).is_none() {
            for scale in ["1.0", "2.0"] {
                let status = std::process::Command::new(std::env::current_exe().unwrap())
                    .args(["--exact", EXACT, "--nocapture"])
                    .env(CHILD, "1")
                    .env(SCALE, scale)
                    .env("RUST_TEST_THREADS", "1")
                    .status()
                    .expect("launch isolated Modified paging test");
                assert!(status.success(), "Modified paging failed at {scale}×");
            }
            return;
        }
        let scale = std::env::var(SCALE).unwrap().parse::<f32>().unwrap();
        crate::native_appearance::install_preferences(
            crate::native_appearance::AppearancePreferences {
                text_scale: scale,
                ..crate::native_appearance::current_preferences()
            },
        );
        let source = (0..7)
            .map(|index| format!("future_{index} = {index}\n"))
            .collect::<String>();
        let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view");
        };
        **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::Modified);
        let overrides = authored_manual_overrides(state);
        assert_eq!(overrides.len(), 7);
        assert_eq!(settings_field_result_count(state), overrides.len());
        let cx = view_cx_at(320.0, 568.0);
        for (offset, authored) in overrides.iter().enumerate() {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.page_scroll = offset;
            let compiled = runtime
                .render(instance, view, &cx)
                .unwrap()
                .compile(cx.viewport)
                .unwrap();
            compiled.validate_parity().unwrap();
            let label = compiled
                .semantic(&UiKey::new(format!(
                    "settings/modified/manual/label/{}",
                    key_fragment(&authored.key)
                )))
                .unwrap_or_else(|| panic!("{} is reachable at offset {offset}", authored.key));
            assert!(label.rect.bottom() <= cx.viewport.bottom() + 0.01);
            let value = compiled
                .semantic(&UiKey::new(format!(
                    "settings/modified/manual/value/{}",
                    key_fragment(&authored.key)
                )))
                .unwrap_or_else(|| {
                    panic!("{} preview is reachable at offset {offset}", authored.key)
                });
            assert!(value.rect.bottom() <= cx.viewport.bottom() + 0.01);
            assert!(label.rect.bottom() <= value.rect.y + 0.01);
        }
    }

    #[test]
    fn reset_all_preserves_every_toml_native_and_forward_compatible_structure() {
        let source = r#"theme = "Nord"
cursor_nyan_sprite = "/aterm/no-such-reset-cat.png"
[packages]
exclude = ["ay"]
[keybindings]
"cmd+t" = "new_tab"
[[sparkle_words.custom]]
words = ["ultrathink"]
[future_feature]
enabled = true
"#;
        let mut service = VersionedConfigService::new(source.to_string()).unwrap();
        let snapshot = service.snapshot();
        let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        let result = service.reset_all(
            snapshot.revision,
            state
                .legacy
                .fields
                .iter()
                .filter(|field| !prefs::manual_only_key(field.key))
                .map(|field| field.key.to_string()),
        );
        let ConfigPatchResult::Applied { snapshot, .. } = result else {
            panic!("Reset All removes the native theme override");
        };
        assert!(!snapshot.text.contains("theme = \"Nord\""));
        for preserved in [
            "cursor_nyan_sprite = \"/aterm/no-such-reset-cat.png\"",
            "exclude = [\"ay\"]",
            "\"cmd+t\" = \"new_tab\"",
            "[[sparkle_words.custom]]",
            "[future_feature]",
            "enabled = true",
        ] {
            assert!(snapshot.text.contains(preserved), "missing {preserved:?}");
        }
    }

    #[test]
    fn manual_route_identity_and_every_action_open_the_typed_editor() {
        let (mut runtime, instance, view) = setup();
        assert_eq!(
            SettingsRoute::from_path("/manual"),
            Some(SettingsRoute::Manual),
            "restore keeps a stable route identity without performing IO"
        );
        assert_eq!(
            route_action(SettingsRoute::Manual).as_str(),
            "settings/manual/open"
        );
        let commands = runtime.commands(instance, view).unwrap();
        let manual = commands
            .iter()
            .find(|command| command.title == "Settings: Go to Manual")
            .expect("Manual participates in the native command surface");
        assert_eq!(manual.id.as_str(), "settings/manual/open");

        let open = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Manual),
                    value: None,
                }),
            )
            .unwrap();
        let operation = open
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::OpenConfigEditor { reply, .. } => Some(reply.operation),
                _ => None,
            })
            .expect("Manual emits exactly one path-free editor effect");
        let commands = runtime.commands(instance, view).unwrap();
        assert!(
            !commands
                .iter()
                .find(|command| command.id.as_str() == "settings/manual/open")
                .unwrap()
                .enabled,
            "a duplicate open is disabled only while the typed request is pending"
        );
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ConfigEditorFinished {
                    operation,
                    outcome: ConfigEditorOutcome::Failed {
                        message: "test denial".to_string(),
                    },
                },
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert!(state.pending.is_empty());
        assert!(state.feedback.as_deref().unwrap().contains("test denial"));
        let commands = runtime.commands(instance, view).unwrap();
        assert!(
            commands
                .iter()
                .find(|command| command.id.as_str() == "settings/manual/open")
                .unwrap()
                .enabled,
            "the Manual command reopens its editor while Settings remains on /manual"
        );
    }

    /// THE SOUND MENU, on the NATIVE surface (owner ask: "add the volume and
    /// SFX menu to settings"). `settings.rs` pins the in-grid box; this pins the
    /// native Advanced pane, where the routing actually has to hold: every
    /// audible key reachable at all is reachable on ONE route under ONE caption,
    /// and nothing audible is left behind in Manual except where the platform
    /// has no host for it.
    ///
    /// NON-VACUOUS: it asserts its own preconditions — the menu is non-empty and
    /// every member is a live registry row — and then names the six keys that
    /// were Manual-only or non-existent before this change, so the test cannot
    /// pass by surfacing nothing.
    #[test]
    fn native_sound_menu_is_one_box_on_one_route() {
        let fields = prefs::editable_fields(&Config::default());
        assert!(
            prefs::SOUND_MENU_KEYS.len() >= 9,
            "the Sound menu lost members: {:?}",
            prefs::SOUND_MENU_KEYS
        );
        for key in prefs::SOUND_MENU_KEYS {
            assert!(
                fields.iter().any(|field| &field.key == key),
                "{key} left the registry; the Sound menu would silently shrink"
            );
        }

        // THE ROUTING CLAIM, SPELLED OUT rather than derived: every audible key
        // must land on the same pane under the same caption. Naming them here
        // means a misrouted key fails loudly instead of quietly dropping out of
        // both sides of a self-derived comparison.
        for key in [
            "trail_sounds",
            "trail_sound_volume",
            "trail_sound_style",
            "tone_melody",
            "trail_sound_bed",
            "trail_sound_riff",
            "bell_sound",
            "sparkle_words.profanity.bonk",
            "sparkle_words.profanity.bonk_detonation",
            // PRISM WAKE's output pip — audible, so it owes the same routing.
            "output_streak.sound",
        ] {
            assert!(
                prefs::SOUND_MENU_KEYS.contains(&key),
                "{key} is audible but absent from SOUND_MENU_KEYS"
            );
            assert_eq!(prefs::section_of(key), prefs::Section::Cursor, "{key}");
            assert_eq!(prefs::group_of(key).0, "Sound", "{key}");
        }
        // Nothing NON-audible smuggled itself into the routing list.
        assert_eq!(
            prefs::SOUND_MENU_KEYS.len(),
            10,
            "the Sound menu's membership changed: {:?}",
            prefs::SOUND_MENU_KEYS
        );

        let shown: Vec<&str> = prefs::SOUND_MENU_KEYS
            .iter()
            .copied()
            .filter(|key| settings_field_is_visible(key, false, false))
            .collect();

        // The SEVEN rows the ordinary Advanced pane must paint: the volume
        // slider, the palette, and the five voice toggles. Four of these shipped
        // but were reachable only by hand-editing `aterm.toml`; one is new. If
        // any regresses to Manual the menu is partial again and this fails by
        // name rather than by a silently shorter list.
        for required in [
            prefs::EDIT_TRAIL_SOUND_VOLUME,
            prefs::EDIT_TRAIL_SOUND_STYLE,
            prefs::EDIT_TONE_MELODY,
            prefs::EDIT_TRAIL_SOUND_BED,
            prefs::EDIT_TRAIL_SOUND_RIFF,
            prefs::EDIT_SPARKLE_BONK,
            prefs::EDIT_SPARKLE_BONK_DETONATION,
        ] {
            assert!(
                shown.contains(&required),
                "{required} is not reachable from the native Sound menu"
            );
        }

        // The audible BEL appears exactly where a beep call exists to suppress.
        assert_eq!(
            shown.contains(&prefs::EDIT_BELL_SOUND),
            cfg!(any(target_os = "macos", windows)),
            "the terminal bell row must not promise a beep this platform never makes"
        );

        // The MASTER switch is deliberately not duplicated into the box: it is a
        // Top Setting ("Music effects"), and a second copy would let two
        // controls disagree about one key. It stays findable by search.
        assert!(
            !settings_field_is_visible(prefs::EDIT_TRAIL_SOUNDS, false, false),
            "the master belongs to Top Settings, not a second Advanced row"
        );
        assert!(
            settings_field_is_visible(prefs::EDIT_TRAIL_SOUNDS, false, true),
            "the master must still answer a global search for sound"
        );
        // …but the box must SAY where it went, or a user who opens Sound looking
        // for the on/off switch finds seven rows and no master.
        let note = prefs::group_footnote("Sound").expect("the Sound box needs consequence copy");
        assert!(
            note.contains("Music effects") && note.contains("Top Settings"),
            "the Sound box must point at the master switch it does not host: {note}"
        );
        // …and it must SCOPE that master, because this box holds two
        // independent audio paths. `lib.rs::on_bell` reads neither
        // `trail_sounds` nor `trail_sound_volume`
        // (`sound_menu_keys_are_read_at_their_consumers` pins that), so copy
        // calling Music effects "the master switch" flatly promised a user that
        // muting it would stop the beep. It does not.
        assert!(
            note.contains("synth voices") && note.contains("bell"),
            "the Sound box must scope the master to the synth voices and name \
             the bell as the exception: {note}"
        );

        // The bonk keys' escape from the keyword-toy rule is exact: their
        // sparkle-words siblings stay Manual-only.
        for sibling in [
            "sparkle_words.profanity.density",
            "sparkle_words.profanity.intensity",
        ] {
            assert!(
                !settings_field_is_visible(sibling, false, false),
                "{sibling} must stay a Manual-only keyword-toy internal"
            );
        }
    }

    /// THE SOUND ROWS DISCLOSE THEIR REAL GATES, AND ONLY THEIR REAL GATES.
    ///
    /// A false "Inactive" note is worse than none — it tells a user a control is
    /// dead while the sound keeps playing. The two families in the Sound box
    /// have DIFFERENT gates and this pins the difference:
    ///
    ///   * the melody and the ambient bed ride `CursorGlow::drain_sound_cues`,
    ///     so `cursor_trail = false` really does silence them;
    ///   * the sing-along riff does NOT — it is gated on `glow_cfg.STYLE`, and
    ///     `resolve_cursor_glow` derives `style` from the style string
    ///     regardless of `enabled`, so the riff still sings with the trail off.
    ///     Its honest gate is the master switch.
    ///
    /// NON-VACUOUS: each case asserts the note it SHOULD carry as well as the
    /// note it must not, so a projection that stopped disclosing anything at all
    /// fails instead of passing the negative half.
    #[test]
    fn sound_rows_disclose_their_real_gates_and_no_false_ones() {
        let availability = audited_availability();
        let motion = crate::native_app::ViewMotionCx::default();

        // Cue-borne voices: the trail really is their gate.
        for key in [prefs::EDIT_TONE_MELODY, prefs::EDIT_TRAIL_SOUND_BED] {
            let effect = projected_effect("cursor_trail = false\n", &[], key, availability, motion);
            assert!(
                effect_note_contains(&effect, "Cursor trail is Off"),
                "{key} must disclose the trail gate it actually has: {effect:?}"
            );
            assert!(!effect.has_live_effect, "{key}");
        }

        // The riff: NOT trail-gated. It must not inherit that claim…
        let trail_off = projected_effect(
            "cursor_trail = false\n",
            &[],
            prefs::EDIT_TRAIL_SOUND_RIFF,
            availability,
            motion,
        );
        assert!(
            !effect_note_contains(&trail_off, "Cursor trail is Off"),
            "the riff still sings with the trail off; claiming otherwise is a lie: {trail_off:?}"
        );

        // …and it must disclose the master switch, which IS one of its gates.
        let music_off = projected_effect(
            "trail_sounds = false\n",
            &[],
            prefs::EDIT_TRAIL_SOUND_RIFF,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&music_off, "Music effects is Off"),
            "the riff must disclose the master switch that does silence it: {music_off:?}"
        );
        assert!(!music_off.has_live_effect);

        // The BONK rides the word-decoration tick, not the glow: the trail being
        // off must not claim it is inactive either.
        let bonk_trail_off = projected_effect(
            "cursor_trail = false\n",
            &[],
            prefs::EDIT_SPARKLE_BONK,
            availability,
            motion,
        );
        assert!(
            !effect_note_contains(&bonk_trail_off, "Cursor trail is Off"),
            "the bonk fires with the trail off: {bonk_trail_off:?}"
        );
        // Its REAL gate, asserted so the negative above cannot pass merely
        // because the bonk stopped disclosing anything at all.
        let bonk_master_off = projected_effect(
            "[sparkle_words]\nenabled = false\n",
            &[],
            prefs::EDIT_SPARKLE_BONK,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&bonk_master_off, "Sparkle Words master is Off"),
            "the bonk must disclose the sparkle master that does silence it: {bonk_master_off:?}"
        );
        // …and the MUSIC master, which since 2026-08-09 also silences it
        // (`app_render::bonk_sound_gain`'s `trail_sounds` term). Both bonk
        // rows, because both are sound-only leaves: `bonk_detonation` admits a
        // cue KIND into the same synth and moves nothing on glass.
        for key in [
            prefs::EDIT_SPARKLE_BONK,
            prefs::EDIT_SPARKLE_BONK_DETONATION,
        ] {
            let music_off =
                projected_effect("trail_sounds = false\n", &[], key, availability, motion);
            assert!(
                effect_note_contains(&music_off, "Music effects is Off"),
                "{key} must disclose the Music-effects master that does silence it: {music_off:?}"
            );
            assert!(!music_off.has_live_effect, "{key}");
        }

        // Platform truth: with no audio device the synth voices say so, while
        // the terminal bell — an OS alert sound, not a synth voice — does not.
        let silent = SettingsAvailability {
            trail_audio: false,
            ..availability
        };
        let muted_riff = projected_effect("", &[], prefs::EDIT_TRAIL_SOUND_RIFF, silent, motion);
        assert!(
            effect_note_contains(&muted_riff, "Audio unavailable"),
            "{muted_riff:?}"
        );
        let bell = projected_effect("", &[], prefs::EDIT_BELL_SOUND, silent, motion);
        assert!(
            !effect_note_contains(&bell, "Audio unavailable"),
            "the OS bell does not need the trail-audio device: {bell:?}"
        );
    }

    /// SERIOUS MODE IS DISCLOSED ON EVERY AUDIBLE ROW IT ACTUALLY SILENCES —
    /// and on none that it does not.
    ///
    /// The Sound-menu census (`prefs::SOUND_MENU_KEYS`) deliberately keeps
    /// `serious_mode` OUT of this box: it is a whole-product policy with its own
    /// "Effect policy" home, and a second control for one key is exactly the
    /// hazard that keeps the `trail_sounds` master in Top Settings. But it IS a
    /// real gate — `SeriousEffect::TerminalSound` is read at all three
    /// `app_render` sound seams and at `lib.rs::on_bell` — so the honest
    /// surfacing is a per-row note, not a row. Without this every Sound row
    /// reads "On" under Serious Mode while the machine is silent.
    ///
    /// NON-VACUOUS: every case asserts the DEFAULT posture is note-free first,
    /// so a projection that started shouting "Serious Mode" at everything (or
    /// that returned the note for reasons unrelated to serious mode) fails.
    #[test]
    fn serious_mode_is_disclosed_on_the_sound_rows_it_silences() {
        let availability = audited_availability();
        let motion = crate::native_app::ViewMotionCx::default();
        const TRAIL_ON: &str = "cursor_trail = true\n";
        const TRAIL_ON_SERIOUS: &str = "cursor_trail = true\nserious_mode = true\n";

        for key in [
            prefs::EDIT_TRAIL_SOUND_VOLUME,
            prefs::EDIT_TRAIL_SOUND_STYLE,
            prefs::EDIT_TONE_MELODY,
            prefs::EDIT_TRAIL_SOUND_BED,
            prefs::EDIT_TRAIL_SOUND_RIFF,
            prefs::EDIT_BELL_SOUND,
            // The bonks take the same note from the keyword-toy branch; pinning
            // them here keeps the BOX's promise whole rather than one branch's.
            prefs::EDIT_SPARKLE_BONK,
            prefs::EDIT_SPARKLE_BONK_DETONATION,
        ] {
            // Both postures AUTHOR the trail master. It is the top rung of the
            // same disclosure ladder ("Inactive · Cursor trail Off" outranks the
            // Serious Mode note), and its absent-key default is platform-split —
            // so leaving it unwritten would make the quiet case pass for the
            // wrong reason on Windows and the serious case fail outright.
            let quiet = projected_effect(TRAIL_ON, &[], key, availability, motion);
            assert!(
                !effect_note_contains(&quiet, "Serious Mode"),
                "{key} must not claim Serious Mode with Serious Mode off: {quiet:?}"
            );
            let serious = projected_effect(TRAIL_ON_SERIOUS, &[], key, availability, motion);
            assert!(
                effect_note_contains(&serious, "Serious Mode"),
                "{key} is silent under Serious Mode and must say so: {serious:?}"
            );
            assert!(!serious.has_live_effect, "{key}");
        }

        // THE MASTER TOO — via the cursor-trail block's `motion_suppression`,
        // not the sound branch above, which deliberately skips it. Pinned here
        // anyway so the BOX's promise is whole: if the master ever stopped
        // disclosing this, the Sound surface would have one row lying while its
        // eight neighbours told the truth.
        //
        // Note the distinction the copy gets right: this describes the CURRENT
        // STATE (with Serious Mode set, Music effects On is suppressed — true),
        // not the ACTION (toggling this control ON clears Serious Mode rather
        // than being suppressed by it —
        // `top_effect_controls_truthfully_escape_the_serious_mode_override`).
        let master = projected_effect(
            TRAIL_ON_SERIOUS,
            &[],
            prefs::EDIT_TRAIL_SOUNDS,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&master, "Serious Mode"),
            "Music effects On is silent under Serious Mode and must say so: {master:?}"
        );
    }

    /// The typing-sound picker's labels: `auto` reads as what it MEANS
    /// ("Follow the trail", not the generic "Automatic"), every instrument
    /// reads in sentence case, and the popup rows carry the same labels as
    /// the button. The static option list is the synth's roster (14 rows).
    #[test]
    fn typing_sound_choice_labels_read_as_instruments() {
        assert_eq!(
            setting_choice_label(prefs::EDIT_TRAIL_SOUND_STYLE, "auto"),
            "Follow the trail"
        );
        assert_eq!(
            setting_choice_label(prefs::EDIT_TRAIL_SOUND_STYLE, "auto (default)"),
            "Follow the trail (default)",
            "the unset row keeps its default annotation"
        );
        for (value, label) in [
            ("music box", "Music box"),
            ("ice chime", "Ice chime"),
            ("typewriter", "Typewriter"),
            ("mechanical", "Mechanical"),
            ("felt", "Felt"),
        ] {
            assert_eq!(
                setting_choice_label(prefs::EDIT_TRAIL_SOUND_STYLE, value),
                label
            );
        }
        // Other keys' `auto` keeps its generic label.
        assert_eq!(
            setting_choice_label(prefs::EDIT_WINDOW_THEME, "auto"),
            "Automatic"
        );
        let field = prefs::editable_fields(&crate::app_config::Config::default())
            .into_iter()
            .find(|f| f.key == prefs::EDIT_TRAIL_SOUND_STYLE)
            .expect("the typing-sound row");
        let choices = choices_for_field(&field, &[], &crate::app_config::ThemeCatalog::default())
            .expect("static options");
        assert_eq!(choices.len(), 14);
        assert_eq!(choices[0], "auto");
        assert!(choices.iter().any(|c| c == "typewriter"));
        let picker = ChoicePicker::new(
            prefs::EDIT_TRAIL_SOUND_STYLE,
            choices.clone(),
            "auto (default)",
            false,
            false,
            "auto",
            &crate::app_config::ThemeCatalog::default(),
        );
        assert_eq!(picker.options[0].label, "Follow the trail");
        assert!(picker.options.iter().any(|o| o.label == "Music box"));
        assert!(
            picker.options.iter().all(|o| o.label != "Glass bell"),
            "the glass bell died with v1 (§17.3 phase 7)"
        );
    }

    /// THE UNDERLINE ROW FITS ITS OWN BUTTON. `rainbow kitty underline` is the
    /// longest spelling the trail list has ever carried (23 characters, against
    /// the previous longest `rainbow kitty pet` at 17), and sentence-cased it
    /// measured 133.6 pt inside the 132.0 pt Top control at 1.0× text scale —
    /// the renderer clipped it to `Rainbow kitty underl…` and the Top paint
    /// audit went red
    /// (`top_settings_builtin_and_hidden_state_matrix_has_zero_renderer_overflow`).
    ///
    /// The fix is a PAINT LABEL, like `EDIT_MOTION`'s, not a narrower control
    /// and not a renamed config value: the button reads the family's shorter
    /// spelling, which stays honest (it names the highlighter-plus-strip mark,
    /// the geometry that spelling selects — and, since 2026-08-28, the family
    /// default) and stays a legal `cursor_trail_style` — pinned below by
    /// canonicalising the label itself.
    /// The committed value, the semantics and the open picker's rows keep the
    /// complete spelling.
    #[test]
    fn cursor_trail_underline_choice_label_fits_the_control() {
        // Every spelling the ENGINE routes to the strip gets the one label —
        // the predicate is asked, not a second copy of the list.
        for spelling in [
            "rainbow kitty underline",
            "rainbow underline",
            "underline rainbow",
            "nyan underline",
            "  Rainbow Kitty Underline  ",
        ] {
            assert_eq!(
                setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, spelling),
                "Rainbow underline",
                "{spelling:?} is an underline spelling and must read as the short label"
            );
        }
        // HONEST: the label is itself a spelling of the style it names, so it
        // resolves back to the value the control is holding.
        assert_eq!(
            prefs::cursor_trail_style_canonical("rainbow underline"),
            Some("rainbow kitty underline")
        );
        // Every other trail entry keeps its plain sentence case…
        for (value, label) in [
            ("rainbow kitty", "Rainbow kitty"),
            ("rainbow kitty pet", "Rainbow kitty pet"),
            ("rainbow kitty flying", "Rainbow kitty flying"),
            ("rainbow kitty tall", "Rainbow kitty tall"),
            ("off", "Off"),
        ] {
            assert_eq!(
                setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, value),
                label
            );
        }
        // …and the shortening is scoped to this key.
        assert_eq!(
            setting_choice_label(prefs::EDIT_WINDOW_THEME, "rainbow kitty underline"),
            "Rainbow kitty underline"
        );
        // The open list — which has the width for it — still names the config
        // spelling, so the row a screen reader announces is the value written.
        let field = prefs::editable_fields(&crate::app_config::Config::default())
            .into_iter()
            .find(|f| f.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .expect("the cursor-trail row");
        let choices = choices_for_field(&field, &[], &crate::app_config::ThemeCatalog::default())
            .expect("static options");
        assert!(choices.iter().any(|c| c == "rainbow kitty underline"));
        let picker = ChoicePicker::new(
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            choices,
            prefs::DEFAULT_CURSOR_TRAIL_STYLE,
            false,
            false,
            prefs::DEFAULT_CURSOR_TRAIL_STYLE,
            &crate::app_config::ThemeCatalog::default(),
        );
        assert!(
            picker
                .options
                .iter()
                .any(|option| option.label == "Rainbow kitty underline"),
            "picker rows: {:?}",
            picker
                .options
                .iter()
                .map(|option| option.label.clone())
                .collect::<Vec<_>>()
        );
    }

    /// EVERY SOUND-MENU KEY IS READ AT ITS CONSUMER — the pin that stops this
    /// panel from shipping a switch that does nothing.
    ///
    /// A row here is a PROMISE: flip it and the machine sounds different. The
    /// registry, the schema, the disclosure and the Advanced allowlist can all
    /// be satisfied by a key nothing reads, so the only thing that makes the
    /// promise true is an accessor call at the emission site. That is a
    /// CROSS-FILE property — `app_render.rs` emits the synth voices,
    /// `lib.rs::on_bell` emits the OS alert sound — so it is pinned here by
    /// reading those sources, alongside the behavioural tests that prove each
    /// gate's semantics (`app_render::sing_riff_gain_tests`,
    /// `lib::…::a_silenced_bell_never_consumes_the_audible_rate_limit_lane`).
    ///
    /// This replaces an earlier INVERTED handoff pin that asserted the
    /// consumers did NOT read the two newest keys. It passed for exactly as
    /// long as the switches were inert, which is the failure mode this test now
    /// exists to catch.
    ///
    /// NON-VACUOUS: it asserts its own preconditions first — the rows are
    /// Advanced-visible, the sources are non-empty, and each emission site it
    /// scans for is still present — so it cannot rot into a pass by matching a
    /// renamed or emptied file.
    #[test]
    fn sound_menu_keys_are_read_at_their_consumers() {
        let render = include_str!("app_render.rs");
        let host = include_str!("lib.rs");
        let input = include_str!("app_input.rs");

        // Precondition: the sources really loaded. An `include_str!` of a
        // renamed file would not compile, but an emptied one would make every
        // `contains` below fail loudly rather than pass — assert anyway so the
        // failure names the cause.
        assert!(
            render.len() > 100_000 && host.len() > 100_000 && input.len() > 10_000,
            "the consumer sources look truncated; the scans below are meaningless"
        );

        // Precondition: the rows really are on the audited Advanced surface, so
        // a missing gate would be a visible lie rather than a dormant key.
        assert!(
            settings_field_is_visible(prefs::EDIT_TRAIL_SOUND_RIFF, false, false),
            "the riff row is on the Advanced surface"
        );
        assert_eq!(
            settings_field_is_visible(prefs::EDIT_BELL_SOUND, false, false),
            cfg!(any(target_os = "macos", windows)),
            "the bell row is on the Advanced surface exactly where a beep exists"
        );

        // Precondition: the emission sites these scans are about still exist.
        assert!(
            render.contains("fn sing_riff_event("),
            "the sing-along riff event constructor moved; re-locate its gate"
        );
        assert_eq!(
            render
                .matches("self.trail_audio.push(sing_riff_event(")
                .count(),
            // Count emission sites, not the definition or the outro's reuse
            // of the pure event constructor. Both render paths read the gate.
            2,
            "the riff is pushed from exactly the two known render paths"
        );
        // W13: the macOS site was `objc2_app_kit::NSBeep()` and is now
        // `appkit::beep()` — the first-party binding of the SAME AppKit
        // function. The scan is for the CALL, not for the crate that used to
        // provide it, so it survives the next rename of the provider and would
        // still fail if the emission itself were removed.
        assert!(
            host.contains("crate::appkit::beep()") && host.contains("win32::beep()"),
            "the audible bel emission sites moved; re-locate their gate"
        );

        // THE WIRING ITSELF. Each Sound-menu key names the accessor its
        // consumer must call and the source that must call it.
        for (key, accessor, consumers) in [
            (
                prefs::EDIT_TRAIL_SOUNDS,
                "trail_sounds_or_default",
                &[render][..],
            ),
            (
                prefs::EDIT_TRAIL_SOUND_VOLUME,
                "trail_sound_volume()",
                &[render][..],
            ),
            (
                prefs::EDIT_TRAIL_SOUND_STYLE,
                "trail_sound_voice()",
                &[render][..],
            ),
            (
                prefs::EDIT_TONE_MELODY,
                "tone_melody_or_default",
                &[render, input][..],
            ),
            (
                prefs::EDIT_TRAIL_SOUND_BED,
                "trail_sound_bed_or_default",
                &[render][..],
            ),
            // The two keys the inverted pin used to certify as UNWIRED.
            (
                prefs::EDIT_TRAIL_SOUND_RIFF,
                "trail_sound_riff_or_default",
                &[render][..],
            ),
            (prefs::EDIT_BELL_SOUND, "bell_sound_or_default", &[host][..]),
            // The two BONK keys are `[sparkle_words]` leaves in the FILE but
            // SFX in the UI; their accessors are named after the feature, not
            // the key path.
            (
                prefs::EDIT_SPARKLE_BONK,
                "curse_bonk_enabled()",
                &[render][..],
            ),
            (
                prefs::EDIT_SPARKLE_BONK_DETONATION,
                "curse_bonk_detonation_enabled()",
                &[render][..],
            ),
        ] {
            assert!(
                prefs::SOUND_MENU_KEYS.contains(&key),
                "{key} is pinned here but is not on the Sound menu"
            );
            assert!(
                consumers.iter().any(|src| src.contains(accessor)),
                "{key} is a Sound-menu row whose consumer never reads \
                 `{accessor}` — the switch would do nothing"
            );
        }

        // BOTH riff seams, not just one: a split pane must not sing a song a
        // single pane suppresses. Both go through the one policy author,
        // identified by the argument only a real render seam can pass — the
        // window's RAW focus bit. Counting bare `sing_riff_gain(` instead would
        // also count the function's own definition and its unit tests, which is
        // a pin on this file's test layout rather than on the wiring.
        let production_calls = render
            .match_indices("sing_riff_gain(")
            .filter(|(at, needle)| {
                render[at + needle.len()..]
                    .trim_start()
                    .starts_with("ws.focused")
            })
            .count();
        // Each render path gates both its bar riff and its new outro through
        // the same focus/master/riff/volume policy. Check all four decisions
        // and both outro emissions, in addition to the two bar pushes above.
        assert_eq!(
            production_calls, 4,
            "both bar and outro pushes must resolve gain through the one policy function"
        );
        assert_eq!(
            render
                .matches("self.trail_audio.push(sing_outro_event(")
                .count(),
            2,
            "both render paths emit their gated outro"
        );

        // BOTH BONK SEAMS MUST FEED THE MASTER IN. This is a LAYOUT pin and it
        // is deliberately not the proof: the law lives in
        // `app_render::curse_bonk_drain_tests::music_effects_off_*` and the
        // composed call site is pinned behaviourally by
        // `split_sparkle_tests::a_composed_frame_stops_bonking_when_music_effects_is_off`.
        // The SINGLE-PANE seam lives inside `redraw_window`, which needs a real
        // present target and has no headless entry point, so this is what
        // stands between it and silently regressing to the state the skeptic
        // found on 2026-08-09 — a bonk that ignored the switch the Sound menu
        // names as its master. Identified, like the riff pin above, by the
        // argument only a real render seam passes.
        let bonk_calls: Vec<&str> = render
            .match_indices("bonk_sound_gain(")
            .map(|(at, needle)| &render[at + needle.len()..])
            .filter(|rest| rest.trim_start().starts_with("ws.focused"))
            .collect();
        assert_eq!(
            bonk_calls.len(),
            2,
            "both bonk drains must resolve gain through the one policy function"
        );
        for rest in bonk_calls {
            let head = &rest[..rest.len().min(600)];
            assert!(
                head.contains("bonk_master"),
                "a bonk render seam resolves gain without the Music-effects \
                 master: {head:?}"
            );
        }

        // ORDER IS LOAD-BEARING for the bell: `BellRateLimiter::try_fire`
        // MUTATES, so the key must be tested BEFORE it or a silenced bell burns
        // the beep floor's token.
        let gate = host
            .find("bell_sound_or_default")
            .expect("just asserted present");
        let fire = host
            .find("self.bell_beep.try_fire(now)")
            .expect("the audible bell's rate limiter moved; re-locate the gate");
        assert!(
            gate < fire,
            "`bell_sound` must short-circuit BEFORE the rate limiter consumes a token"
        );

        // THE TWO PATHS ARE INDEPENDENT — the fact the "Sound" footnote states.
        // The BEL's whole gate chain runs from `fn on_bell(` to the limiter, and
        // it must not contain the synth master or the synth volume: they are
        // cue-borne trail-audio keys and the bell is an OS alert sound. If that
        // ever changes, the footnote (and the bell row's disclosure, which
        // deliberately carries no "Music effects Off" note) becomes a lie.
        let on_bell = host.find("fn on_bell(").expect("the BEL handler moved");
        let chain = &host[on_bell..fire];
        assert!(
            !chain.contains("trail_sounds_or_default") && !chain.contains("trail_sound_volume"),
            "the OS alert sound must stay independent of the synth master and volume"
        );
    }

    #[test]
    fn visual_forms_hide_inert_and_compatibility_only_effect_controls() {
        for key in [
            "matrix_rain.materialize",
            "matrix_rain.ink_text",
            "matrix_rain.phosphor",
            "sparkle_words.orca.enabled",
            SPARKLE_MASTER_KEY,
        ] {
            assert!(!settings_field_is_visible(key, false, false), "{key}");
            assert!(!settings_field_is_visible(key, false, true), "{key}");
        }
        assert!(settings_field_is_visible(SPARKLE_WORDS_KEY, true, false));
        assert!(!settings_field_is_visible(prefs::EDIT_THEME, false, false));
        assert!(settings_field_is_visible(prefs::EDIT_THEME, true, false));
        for macos_only in [
            prefs::EDIT_FONT_THICKEN,
            prefs::EDIT_BACKGROUND_OPACITY,
            prefs::EDIT_SECURE_KEYBOARD_ENTRY,
        ] {
            assert_eq!(
                settings_field_is_visible(macos_only, false, false),
                cfg!(target_os = "macos"),
                "{macos_only} belongs in ordinary Advanced only where it has a live consumer"
            );
            assert!(
                settings_field_is_visible(macos_only, true, false),
                "Modified preserves authored cross-platform configuration"
            );
        }
        assert!(
            settings_field_is_visible(prefs::EDIT_ALLOW_OSC52_QUERY, false, false),
            "OSC 52 query has a live host: the GUI clipboard callback answers \
             authorized queries, so the switch is an ordinary security policy"
        );
        assert!(
            settings_field_is_visible(prefs::EDIT_ALLOW_OSC52_QUERY, true, false),
            "Modified still lists the authored value"
        );
        assert!(
            settings_field_is_visible(prefs::EDIT_CONFIRM_MULTILINE_PASTE, false, false),
            "the pastejacking confirm has a live host on every platform now \
             (macOS sheet / Windows dialog / Linux in-window banner)"
        );
        {
            let (key, supported) = (
                prefs::EDIT_ALLOW_NOTIFICATIONS,
                crate::notify::delivery_available(),
            );
            assert_eq!(
                settings_field_is_visible(key, false, false),
                supported,
                "{key} belongs in ordinary Advanced only with a real platform host"
            );
            assert_eq!(settings_field_is_visible(key, false, true), supported);
            assert!(
                settings_field_is_visible(key, true, false),
                "Modified preserves authored cross-platform configuration"
            );
        }

        for key in [
            prefs::EDIT_SHELL,
            "net.listen",
            "update.owner",
            "matrix_rain.fps",
            prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH,
            prefs::EDIT_SHOW_BUILD_BADGE,
            prefs::EDIT_COLUMNS,
            prefs::EDIT_LINES,
            prefs::EDIT_GPU,
        ] {
            assert!(!settings_field_is_visible(key, false, false), "{key}");
            assert!(!settings_field_is_visible(key, false, true), "{key}");
            assert!(
                settings_field_is_visible(key, true, false),
                "Modified retains explicit Manual-only key {key}"
            );
        }
        for key in [prefs::EDIT_SHELL_ARGS, prefs::EDIT_FONT_VARIATION] {
            assert!(prefs::manual_collection_key(key), "{key}");
            assert!(
                !settings_field_is_visible(key, true, false),
                "lossless collection {key} stays in Manual instead of a scalar row"
            );
        }
        assert!(prefs::config_asset_source_key(
            prefs::EDIT_CURSOR_NYAN_SPRITE
        ));
        assert!(prefs::manual_only_key(prefs::EDIT_CURSOR_NYAN_SPRITE));
        assert!(
            !settings_field_is_visible(prefs::EDIT_CURSOR_NYAN_SPRITE, true, true),
            "host-backed sprite source is edited through Manual's worker-validated path"
        );

        let fields = prefs::editable_fields(&Config::default());
        let ordinary_advanced_field = |field: &EditField| {
            settings_field_is_visible(field.key, false, false)
                && SettingsRoute::ALL
                    .into_iter()
                    .filter_map(SettingsRoute::section)
                    .any(|section| section == prefs::section_of(field.key))
        };
        let ordinary_count = fields
            .iter()
            .filter(|field| ordinary_advanced_field(field))
            .count();
        // 2026-07-24 UX audit: +3 on every platform — `cursor_trail_intensity`,
        // `trail_sound_volume`, `trail_sound_style`. This pin exists to force a
        // CONSCIOUS decision about the Advanced surface, so: all three already
        // shipped, all three are consumed by a live subsystem (`cursor_glow`
        // reads `cfg.intensity`; `trail_audio` reads both sound keys), and all
        // three were reachable ONLY from Manual. The audit found the owner
        // filing bugs — "too bright", "too quiet" — that these exact dials
        // answer. A knob a user cannot find is not restraint; it is a defect.
        //
        // THE SOUND MENU (owner ask: "add the volume and SFX menu to settings"):
        // +5 on every platform, +1 more where the beep exists.
        //   * `tone_melody`, `trail_sound_bed` — shipped, consumed by
        //     `app_render`/`app_input` every frame, Manual-only until now;
        //   * `sparkle_words.profanity.bonk` + `.bonk_detonation` — shipped and
        //     consumed by `drain_curse_bonk_cues`; they were hidden by the
        //     blanket keyword-toy rule even though they are SFX, not toy
        //     internals;
        //   * `trail_sound_riff` — NEW. The sing-along riff is TIER 5, the
        //     loudest voice in the engine, and had no switch but the master and
        //     the master volume;
        //   * `bell_sound` — NEW, macOS/Windows only. The audible BEL had no key
        //     at all and is not covered by `trail_sound_volume` (an OS alert
        //     sound is not a synth voice), so it was the one genuinely
        //     unreachable sound in the product.
        //
        // BOTH NEW KEYS ARE READ AT THEIR CONSUMERS — that is what makes this a
        // +2 on the surface rather than +2 lies
        // (`sound_menu_keys_are_read_at_their_consumers`, plus the behavioural
        // pins `app_render::sing_riff_gain_tests` and
        // `a_silenced_bell_never_consumes_the_audible_rate_limit_lane`).
        //
        // NOT counted, deliberately: `serious_mode`. It is a real gate on every
        // audible path but a whole-product policy with escape semantics, so it
        // stays a Top Effect control with its own "Effect policy" box and
        // reaches this box as a per-row disclosure instead — the reasoning is
        // recorded in full at `prefs::SOUND_MENU_KEYS`.
        //
        // THE RAINBOW WAKE DIAL was +1 on every platform from 2026-08-10 to
        // 2026-09-16, admitted on "carried every frame through
        // `GlowConfig::wake_persist_s`" and kept after that stopped being true.
        // It is retired; the count is one lower on every platform, and the
        // Cursor Kitty page carries its picker card and nothing else — which
        // `native_config_language::RETIRED_CONFIG_KEYS` and
        // `the_cursor_kitty_page_is_its_showcase_card` now say out loud.
        // THE TYPING-MOMENTUM GLOW (2026-09-08): +1 on every platform. The
        // owner asked for it by name ("the blinking cursor is annoying, I want
        // some momentum glow for typing faster that cools down"), it ships
        // DEFAULT ON, and `cursor_momentum_glow` is read at its consumer every
        // frame — `app_render`'s cursor-body tick reads
        // `cursor_momentum_glow_or_default()` — so the switch is a real one,
        // not a Manual-only expert key. It sits in the Cursor box beside
        // `cursor_blink`, the row it partly replaces (a warm cursor does not
        // blink), and is searchable as "blink".
        // THE [MACHINE] HOST SETTINGS (2026-09-14): +2 on macOS only. The owner
        // asked for "a settings panel for these checks to show confirmation":
        // `universal_control` and `spotlight_noindex` are applied by the
        // co-located atpkg's `machine apply` (as the window opens, by a terminal
        // session once a day, and at a pass after an edit) and by the Security
        // page's Apply now, and the page's "This Mac" card confirms what the
        // machine measured. Both actuate only on macOS (`defaults`, Spotlight),
        // so elsewhere they stay Modified/Manual-only like `font_thicken`.
        assert_eq!(
            ordinary_count,
            if cfg!(target_os = "macos") {
                57
            } else if cfg!(windows) {
                52
            } else {
                50
            },
            // +1 on every platform (2026-08-21): allow_osc52_query became an
            // ordinary Advanced switch when the GUI's clipboard callback
            // learned to answer authorized queries — a LIVE policy joins the
            // audited surface; anything still inert belongs in Manual.
            // +1 on Linux (2026-08-23): `confirm_multiline_paste` stopped being
            // hidden there when the pastejacking guard grew its in-window
            // banner (`paste_banner`) — the switch now actuates a real
            // confirmation on every platform, so it joins the audited surface
            // instead of the platform-unavailable shelf.
            // +1 on every platform (2026-08-27): `split_focus_mark`, the mark
            // that says which pane of a split takes keystrokes. Its consumer is
            // the split COMPOSITOR, which reads it while seeding the divider
            // grid on every composed frame, so it is live everywhere a split is
            // — not an expert knob for Manual.
            "the audited Advanced surface changed; new expert keys belong in Manual"
        );
        let ordinary_groups = fields
            .iter()
            .filter(|field| ordinary_advanced_field(field))
            .map(|field| prefs::group_of(field.key).0)
            .collect::<BTreeSet<_>>();
        let mut group_witnesses = vec![
            ("Colors", prefs::EDIT_FOREGROUND),
            ("Text & Contrast", prefs::EDIT_MINIMUM_CONTRAST),
            ("Font", prefs::EDIT_FONT_FAMILY),
            ("Shaping", prefs::EDIT_LIGATURES),
            ("Line layout", prefs::EDIT_LINE_HEIGHT),
            ("Rendering", prefs::EDIT_FONT_WEIGHT),
            ("Cursor", prefs::EDIT_CURSOR_STYLE),
            ("Motion", prefs::EDIT_MOTION),
            ("Stream fade", prefs::EDIT_STREAM_FADE),
            ("Matrix rain", prefs::EDIT_MATRIX_RAIN_ENABLED),
            ("Window padding", prefs::EDIT_WINDOW_PADDING),
            ("Session", prefs::EDIT_RESTORE_SESSION),
            ("Clipboard", prefs::EDIT_COPY_ON_SELECT),
            ("Keyboard", prefs::EDIT_PREDICTIVE_ECHO),
            ("Scrollback", prefs::EDIT_SCROLLBACK),
            ("Text direction & width", prefs::EDIT_BIDI),
            ("Permissions", prefs::EDIT_ALLOW_WINDOW_OPS),
            // 2026-07-24 UX audit: exposing `cursor_trail_intensity` (plus the
            // two trail-sound keys) surfaced the "Trail effect" caption, which
            // needs its own curated witness like every other group.
            ("Trail effect", prefs::EDIT_CURSOR_TRAIL_INTENSITY),
            // The Sound menu's curated witness is the master VOLUME slider —
            // the one control the owner named first, and the only one every
            // other row in the box is scaled by.
            ("Sound", prefs::EDIT_TRAIL_SOUND_VOLUME),
            // The Cursor Kitty page contributes NO ordinary group box. Its
            // "Companion" caption belongs to `cursor_trail_style`, a Top
            // Setting the ordinary form never draws — the showcase card owns
            // that row — and its one real box, "Rainbow wake", went with the
            // retired dial (2026-09-16).
        ];
        if cfg!(target_os = "macos") {
            group_witnesses.push(("Transparency", prefs::EDIT_BACKGROUND_OPACITY));
            // The Security page's second box: the [machine] host settings the
            // "This Mac" card confirms.
            group_witnesses.push(("This Mac", prefs::EDIT_MACHINE_SPOTLIGHT_NOINDEX));
        }
        group_witnesses.push(("Paste safety", prefs::EDIT_CONFIRM_MULTILINE_PASTE));
        assert_eq!(
            ordinary_groups,
            group_witnesses
                .iter()
                .map(|(group, _)| *group)
                .collect::<BTreeSet<_>>(),
            "every Advanced caption needs a retained, curated member",
        );
        for (group, key) in &group_witnesses {
            assert!(
                settings_field_is_visible(key, false, false),
                "{group}: {key}"
            );
            assert_eq!(prefs::group_of(key).0, *group, "{group}: {key}");
        }
        for (group, relevant_copy) in [
            ("Text & Contrast", "contrast"),
            ("Transparency", "opacity"),
            ("Rendering", "weight"),
            ("Motion", "motion"),
            ("Stream fade", "fades"),
            ("Matrix rain", "Rain"),
            ("Window padding", "padding"),
            ("Paste safety", "paste"),
            ("Keyboard", "Predictive echo"),
            ("Scrollback", "Searchable lines"),
            ("Text direction & width", "right-to-left"),
            ("Permissions", "request access"),
            // The This Mac box must say the second way its rows apply — the
            // card's own button — and how each change is undone.
            ("This Mac", "Apply now"),
            // The Sound box's footnote must name what the VOLUME slider does
            // and does not reach — the reason the bell needed its own row.
            ("Sound", "Volume"),
        ] {
            if ordinary_groups.contains(group) {
                let note = prefs::group_footnote(group)
                    .unwrap_or_else(|| panic!("{group} needs consequence copy"));
                assert!(
                    note.to_lowercase().contains(&relevant_copy.to_lowercase()),
                    "{group} copy does not describe its retained control: {note}",
                );
            }
        }
        assert!(
            prefs::group_footnote("Clipboard").is_none(),
            "copy-on-select must not inherit Manual-only paste-safety copy",
        );
        for field in fields.iter().filter(|field| ordinary_advanced_field(field)) {
            assert!(
                native_advanced_effect(field.key).is_some(),
                "Advanced row {} has no audited shipping consumer",
                field.key
            );
        }
        for restart_only in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
            assert_eq!(
                native_advanced_effect(restart_only),
                None,
                "restart-only {restart_only} must stay in Manual/Modified"
            );
        }
        for route in SettingsRoute::ALL {
            let Some(section) = route.section() else {
                continue;
            };
            let has_ordinary_row = fields.iter().any(|field| {
                prefs::section_of(field.key) == section
                    && settings_field_is_visible(field.key, false, false)
            });
            if !has_ordinary_row {
                // AN EMPTY DESTINATION IS THE DEFECT; A ROWLESS ONE IS NOT THE
                // SAME THING. This asked "does the route own a visible ordinary
                // field" as a proxy for "does the route show the user
                // anything", and the proxy held only while every destination
                // was built out of registry rows. Cursor Kitty is not: its
                // content is the companion showcase card (`cursor_kitty_card`,
                // which "can never be shed outright"), and its two filed keys
                // are a Top Setting and a Manual-only asset path. The proxy
                // also passed this page for six weeks while its one row was
                // `cursor_trail_wake_ms`, a dial nothing read — so it was
                // admitting an empty page and is now about to refuse a full
                // one. The exception is therefore enumerated, not widened, and
                // the card itself is pinned by
                // `the_cursor_kitty_page_is_its_showcase_card`.
                assert_eq!(
                    route,
                    SettingsRoute::CursorKitty,
                    "{} must not be an empty Advanced destination",
                    route.label()
                );
            }
        }

        let predictive = fields
            .iter()
            .find(|field| field.key == prefs::EDIT_PREDICTIVE_ECHO)
            .unwrap();
        let choices =
            choices_for_field(predictive, &[], &crate::app_config::ThemeCatalog::default())
                .unwrap();
        assert_eq!(choices, ["off", "adaptive"]);
    }

    #[test]
    fn restart_only_overrides_disclose_timing_in_rows_and_apply_feedback() {
        let snapshot =
            VersionedConfigService::new("columns = 96\nlines = 30\ngpu = false\n".to_string())
                .unwrap()
                .snapshot();
        let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        for key in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
            let expected_timing = if key == prefs::EDIT_GPU {
                "Applies next launch"
            } else {
                "Applies on a fresh launch; an authenticated update handoff preserves the live size"
            };
            let (index, field) = state
                .legacy
                .fields
                .iter()
                .enumerate()
                .find(|(_, field)| field.key == key)
                .unwrap();
            let compiled = UiTree::new(setting_row(
                &state,
                index,
                field,
                true,
                false,
                SettingsWidth::Wide,
            ))
            .compile(LogicalRect::new(0.0, 0.0, 720.0, 80.0))
            .unwrap();
            assert!(
                compiled
                    .semantic(&UiKey::new(format!("settings/label/{key}")))
                    .unwrap()
                    .label
                    .contains(expected_timing),
                "Modified visibly discloses timing for {key}"
            );
            assert!(
                compiled
                    .semantic(&UiKey::new(format!("settings/control/{key}")))
                    .unwrap()
                    .label
                    .contains(expected_timing),
                "the native control name discloses timing for {key}"
            );
        }

        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
            .unwrap();
        let requested = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(format!("settings/set/{}", prefs::EDIT_GPU)),
                    value: Some(SemanticInput::Bool(true)),
                }),
            )
            .unwrap();
        let operation = requested
            .effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
                _ => None,
            })
            .expect("restart-only edit reaches the shared config service");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ConfigPatchFinished {
                    operation,
                    outcome: ConfigPatchOutcome::Applied {
                        revision: 2,
                        undo: Some(7),
                    },
                },
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert_eq!(
            state.feedback.as_deref(),
            Some("Saved · Applies next launch · Undo available")
        );
    }

    #[test]
