    #[test]
    fn custom_ink_and_emphasis_dependencies_match_runtime_ownership() {
        let availability = audited_availability();
        let motion = crate::native_app::ViewMotionCx::default();
        let effect = |source: &str, key: &str, value: &str| {
            projected_effect(source, &[(key, value)], key, availability, motion)
        };
        let source = |recipe: &str| {
            format!(
                "[sparkle_words.profanity]\nstyle = \"rainbow\"\n\
                 [[sparkle_words.custom]]\nwords = [\"inkword\"]\n{recipe}\n"
            )
        };

        let rainbow: Config = aterm_toml::from_str(&source("ink = \"rainbow\"")).unwrap();
        let rainbow = SettingsViewState::new(&rainbow)
            .sparkle_spec_consumers
            .unwrap();
        assert!(rainbow.rainbow_ink);
        assert!(!rainbow.twotone_ink);

        let twotone_source = source("ink = \"twotone:#112233,#445566\"");
        let twotone: Config = aterm_toml::from_str(&twotone_source).unwrap();
        let twotone = SettingsViewState::new(&twotone)
            .sparkle_spec_consumers
            .unwrap();
        assert!(twotone.twotone_ink);
        assert!(!twotone.rainbow_ink);

        let graphic: Config =
            aterm_toml::from_str(&source("graphic = { collection = \"cats\" }")).unwrap();
        assert_eq!(
            SettingsViewState::new(&graphic).sparkle_spec_consumers,
            Some(aterm_effects::spec::SpecConsumerCapabilities::default())
        );

        let mut self_glow_table = aterm_effects::spec::SpecTable::default();
        self_glow_table.insert_custom(
            "glowword",
            aterm_effects::spec::WordEffectSpec {
                ink: Some(aterm_effects::spec::InkSpec {
                    colorway: aterm_effects::spec::Colorway::SelfGlow {
                        lift: 0.2,
                        amp: 0.5,
                        window_ms: 900,
                    },
                    sweep_once: true,
                }),
                ..Default::default()
            },
        );
        assert_eq!(
            self_glow_table.consumer_capabilities(),
            aterm_effects::spec::SpecConsumerCapabilities::default(),
            "SelfGlow owns its intensity and cannot consume shared strength/sweep"
        );

        let sweep = effect(&twotone_source, "sparkle_words.ink.sweep_ms", "1200");
        assert!(
            !effect_note_contains(&sweep, "TwoTone ink only"),
            "custom TwoTone consumes the shared sweep duration"
        );
        let rainbow_sweep = effect(
            &source("ink = \"rainbow\""),
            "sparkle_words.ink.sweep_ms",
            "1200",
        );
        assert!(effect_note_contains(&rainbow_sweep, "TwoTone ink only"));

        let loop_projection = effect(&twotone_source, "sparkle_words.ink.loop", "true");
        assert!(
            effect_note_contains(&loop_projection, "Class TwoTone only"),
            "custom sweep_once ownership must not make global ink.loop live"
        );

        let custom_emphasis = effect(&twotone_source, "sparkle_words.emphasis.enabled", "true");
        assert!(
            effect_note_contains(&custom_emphasis, "default Emphasis"),
            "custom overrides bypass the emphasis class gate"
        );
        let extra_words = effect(
            "[sparkle_words.emphasis]\nenabled = true\nextra_words = [\"wow\"]\n",
            "sparkle_words.emphasis.enabled",
            "true",
        );
        assert!(!effect_note_contains(&extra_words, "default Emphasis"));

        let blank_words = effect(
            "[sparkle_words.emphasis]\nenabled = true\nextra_words = [\"\", \"   \"]\n",
            "sparkle_words.emphasis.enabled",
            "true",
        );
        assert!(effect_note_contains(&blank_words, "default Emphasis"));

        let ink_off = effect(
            "[sparkle_words.ink]\nenabled = false\n\
             [sparkle_words.emphasis]\nenabled = true\nextra_words = [\"wow\"]\n",
            "sparkle_words.emphasis.enabled",
            "true",
        );
        assert!(effect_note_contains(&ink_off, "Keyword ink Off"));
    }

